"use client";

import * as React from "react";

import { cn } from "#/lib/forge/utils.ts";

export type NewsletterProps = Omit<React.ComponentPropsWithoutRef<"section">, "onSubmit"> & {
  title?: string;
  description?: string;
  eyebrow?: string;
  placeholder?: string;
  buttonLabel?: string;
  privacyText?: string;
  loading?: boolean;
  successMessage?: string;
  errorMessage?: string;
  disabled?: boolean;
  icon?: React.ReactNode;
  validationErrorMessage?: string;
  submitErrorMessage?: string;
  emailLabel?: string;
  loadingLabel?: string;
  onSubmit: (email: string) => void | Promise<void>;
};

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function Newsletter({
  title = "Stay in the loop",
  description = "Get product updates and practical tips delivered to your inbox.",
  eyebrow,
  placeholder = "you@example.com",
  buttonLabel = "Subscribe",
  privacyText,
  loading = false,
  successMessage,
  errorMessage,
  disabled = false,
  icon,
  validationErrorMessage = "Please enter a valid email address.",
  submitErrorMessage = "Something went wrong. Please try again.",
  emailLabel = "Email address",
  loadingLabel = "Submitting...",
  onSubmit,
  className,
  ...props
}: NewsletterProps) {
  const baseId = React.useId();
  const inputId = `${baseId}-email`;
  const helperId = `${baseId}-helper`;
  const errorId = `${baseId}-error`;
  const successId = `${baseId}-success`;

  const [email, setEmail] = React.useState("");
  const [validationError, setValidationError] = React.useState<string>();
  const [submitError, setSubmitError] = React.useState<string>();
  const [showStatus, setShowStatus] = React.useState(true);
  const [submitting, setSubmitting] = React.useState(false);

  const hasError = Boolean(validationError || submitError || (showStatus && errorMessage));
  const inlineError = validationError || submitError || (showStatus ? errorMessage : undefined);
  const inlineSuccess = !inlineError && showStatus ? successMessage : undefined;
  const isLoading = loading || submitting;
  const isDisabled = disabled || isLoading;

  const describedBy = [privacyText ? helperId : undefined, inlineError ? errorId : undefined]
    .filter(Boolean)
    .join(" ");

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (isDisabled) {
      return;
    }

    const normalizedEmail = email.trim();

    if (!EMAIL_REGEX.test(normalizedEmail)) {
      setShowStatus(false);
      setValidationError(validationErrorMessage);
      return;
    }

    setShowStatus(true);
    setValidationError(undefined);
    setSubmitError(undefined);

    try {
      setSubmitting(true);
      await Promise.resolve(onSubmit(normalizedEmail));
    } catch {
      setSubmitError(submitErrorMessage);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <section
      className={cn(
        "w-full rounded-xl border border-border bg-background p-5 shadow-sm sm:p-6",
        className,
      )}
      {...props}
    >
      <div className="space-y-2">
        {eyebrow ? (
          <p className="font-eyebrow text-xs font-semibold tracking-[0.14em] text-primary uppercase">
            {eyebrow}
          </p>
        ) : null}
        <div className="flex items-center gap-2">
          {icon ? <span className="text-muted-foreground">{icon}</span> : null}
          <h2 className="text-lg font-semibold text-foreground">{title}</h2>
        </div>
        <p className="text-sm text-muted-foreground">{description}</p>
      </div>

      <form className="mt-4" onSubmit={handleSubmit} noValidate>
        <label className="sr-only" htmlFor={inputId}>
          {emailLabel}
        </label>
        <div className="flex flex-col gap-3 sm:flex-row">
          <input
            id={inputId}
            type="email"
            name="email"
            autoComplete="email"
            value={email}
            onChange={(event) => {
              setEmail(event.target.value);
              setValidationError(undefined);
              setSubmitError(undefined);
              setShowStatus(false);
            }}
            placeholder={placeholder}
            disabled={isDisabled}
            aria-invalid={hasError}
            aria-describedby={describedBy || undefined}
            className="h-11 w-full rounded-md border border-border bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-60"
          />
          <button
            type="submit"
            disabled={isDisabled}
            className="inline-flex h-11 shrink-0 items-center justify-center rounded-md bg-primary px-4 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-60"
          >
            {isLoading ? loadingLabel : buttonLabel}
          </button>
        </div>

        {privacyText ? (
          <p className="mt-3 text-xs text-muted-foreground" id={helperId}>
            {privacyText}
          </p>
        ) : null}

        {inlineError ? (
          <p
            className="mt-2 text-sm text-red-600 dark:text-red-400"
            id={errorId}
            role="alert"
            aria-live="assertive"
          >
            {inlineError}
          </p>
        ) : null}

        {inlineSuccess ? (
          <p
            className="mt-2 text-sm text-emerald-700 dark:text-emerald-400"
            id={successId}
            role="status"
            aria-live="polite"
          >
            {inlineSuccess}
          </p>
        ) : null}
      </form>
    </section>
  );
}

src/components/forge/forms/newsletter-ex.text:
"use client";

import * as React from "react";

import { Newsletter } from "#/components/forge/forms/newsletter.tsx";

export function NewsletterExample() {
  const [loading, setLoading] = React.useState(false);
  const [successMessage, setSuccessMessage] = React.useState<string>();
  const [errorMessage, setErrorMessage] = React.useState<string>();

  async function handleSubmit(email: string) {
    setLoading(true);
    setSuccessMessage(undefined);
    setErrorMessage(undefined);

    try {
      await new Promise((resolve) => setTimeout(resolve, 600));
      setSuccessMessage(`Thanks for subscribing, ${email}!`);
    } catch {
      setErrorMessage("Could not subscribe right now. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <Newsletter
      eyebrow="Newsletter"
      title="Build better products"
      description="A monthly digest with experiments, release notes, and UX insights."
      placeholder="name@company.com"
      buttonLabel="Join now"
      privacyText="No spam. Unsubscribe any time."
      loading={loading}
      successMessage={successMessage}
      errorMessage={errorMessage}
      onSubmit={handleSubmit}
    />
  );
}

src/components/forge/layouts/cookie-bann.text:
"use client";

import { useCallback, useEffect, useState } from "react";

import { cn } from "#/lib/forge/utils.ts";

declare global {
  interface Window {
    gtag?: (...args: unknown[]) => void;
    dataLayer?: object[];
  }
}

export interface ConsentState {
  necessary: boolean;
  analytics: boolean;
  marketing: boolean;
}

const DEFAULT_CONSENT: ConsentState = {
  necessary: true,
  analytics: false,
  marketing: false,
};

function ensureGtag() {
  if (typeof window === "undefined") return;
  window.gtag =
    window.gtag ||
    ((...args: unknown[]) => {
      window.dataLayer = window.dataLayer || [];
      window.dataLayer.push(args);
    });
}

function serialize(state: ConsentState): string {
  return JSON.stringify(state);
}

function deserialize(raw: string): ConsentState | null {
  try {
    const parsed = JSON.parse(raw);
    if (
      typeof parsed === "object" &&
      parsed !== null &&
      typeof parsed.analytics === "boolean" &&
      typeof parsed.marketing === "boolean"
    ) {
      return {
        necessary: true,
        analytics: parsed.analytics,
        marketing: parsed.marketing,
      };
    }
    return null;
  } catch {
    return null;
  }
}

function applyConsent(state: ConsentState) {
  ensureGtag();
  window.gtag?.("consent", "update", {
    ad_storage: state.marketing ? "granted" : "denied",
    analytics_storage: state.analytics ? "granted" : "denied",
    ad_user_data: state.marketing ? "granted" : "denied",
    ad_personalization: state.marketing ? "granted" : "denied",
  });
}

export interface CookieBannerProps {
  consentKey?: string;
  manageEvent?: string;
  text: string;
  acceptAllLabel: string;
  acceptSelectionLabel: string;
  cancelLabel?: string;
  confirmLabel?: string;
  policyLabel: string;
  privacyHref: string;
  necessaryTitle?: string;
  necessaryDescription?: string;
  analyticsTitle?: string;
  analyticsDescription?: string;
  marketingTitle?: string;
  marketingDescription?: string;
  showAnalytics?: boolean;
  showMarketing?: boolean;
  dialogLabel?: string;
  hidden?: boolean;
}

export function CookieBanner({
  consentKey = "cookie-consent",
  manageEvent = "manage-cookies",
  text,
  acceptAllLabel,
  acceptSelectionLabel,
  cancelLabel = "Cancel",
  confirmLabel = "Confirm",
  policyLabel,
  privacyHref,
  necessaryTitle = "Necessary",
  necessaryDescription = "Required for the website to function properly.",
  analyticsTitle = "Statistics",
  analyticsDescription = "Helps us understand how visitors interact with the site.",
  marketingTitle = "Marketing",
  marketingDescription = "Measures conversions and personalizes advertising.",
  showAnalytics = true,
  showMarketing = true,
  dialogLabel = "Cookies",
  hidden = false,
}: CookieBannerProps) {
  const [visible, setVisible] = useState(false);
  const [customizing, setCustomizing] = useState(false);
  const [draft, setDraft] = useState(DEFAULT_CONSENT);

  const evaluate = useCallback(() => {
    const stored = localStorage.getItem(consentKey);
    if (stored) {
      const parsed = deserialize(stored);
      if (parsed) {
        applyConsent(parsed);
        setDraft(parsed);
        setCustomizing(false);
        setVisible(false);
        return;
      }
    }
    applyConsent(DEFAULT_CONSENT);
    setDraft(DEFAULT_CONSENT);
    setCustomizing(false);
    setVisible(true);
  }, [consentKey]);

  useEffect(() => {
    // oxlint-disable-next-line react-hooks-js/set-state-in-effect -- reads stored consent during hydration
    evaluate();
    const onStorage = (event: StorageEvent) => {
      if (event.key === consentKey) evaluate();
    };
    const onManage = () => {
      setCustomizing(false);
      setVisible(true);
    };
    window.addEventListener("storage", onStorage);
    window.addEventListener(manageEvent, onManage);
    return () => {
      window.removeEventListener("storage", onStorage);
      window.removeEventListener(manageEvent, onManage);
    };
  }, [evaluate, consentKey, manageEvent]);

  const acceptAll = () => {
    const state: ConsentState = { necessary: true, analytics: true, marketing: true };
    localStorage.setItem(consentKey, serialize(state));
    applyConsent(state);
    setCustomizing(false);
    setVisible(false);
  };

  const openSelection = () => {
    setDraft(DEFAULT_CONSENT);
    setCustomizing(true);
  };

  const cancelSelection = () => {
    setDraft(DEFAULT_CONSENT);
    setCustomizing(false);
  };

  const confirmSelection = () => {
    const state = { ...draft, necessary: true };
    localStorage.setItem(consentKey, serialize(state));
    applyConsent(state);
    setCustomizing(false);
    setVisible(false);
  };

  if (hidden || !visible) return null;

  return (
    <div
      role="dialog"
      aria-label={dialogLabel}
      aria-live="polite"
      className={cn(
        "fixed inset-x-0 bottom-0 z-[60] p-4 sm:p-6",
        "animate-in duration-300 fade-in slide-in-from-bottom-4",
      )}
    >
      <div className="container-premium">
        <div
          className={cn(
            "flex flex-col gap-3 rounded-xl border border-border bg-background px-4 py-3 shadow-lg",
            !customizing && "sm:flex-row sm:items-center",
          )}
        >
          <p className="min-w-0 flex-1 text-sm leading-relaxed text-foreground">
            {text}{" "}
            <a
              href={privacyHref}
              className="font-semibold text-primary underline underline-offset-2"
            >
              {policyLabel}
            </a>
          </p>

          {customizing && (
            <div className="grid gap-3 border-t border-border pt-3 sm:grid-cols-3">
              <label
                aria-label={necessaryTitle}
                className="flex cursor-not-allowed items-start gap-3 opacity-70"
              >
                <input
                  type="checkbox"
                  checked
                  disabled
                  className="mt-0.5 size-4 shrink-0 rounded accent-primary"
                />
                <span>
                  <span className="block text-sm font-semibold text-foreground">
                    {necessaryTitle}
                  </span>
                  <span className="block text-xs text-muted-foreground">
                    {necessaryDescription}
                  </span>
                </span>
              </label>

              {showAnalytics && (
                <label
                  aria-label={analyticsTitle}
                  className="flex cursor-pointer items-start gap-3"
                >
                  <input
                    type="checkbox"
                    checked={draft.analytics}
                    onChange={(event) =>
                      setDraft((state) => ({ ...state, analytics: event.target.checked }))
                    }
                    className="mt-0.5 size-4 shrink-0 rounded accent-primary"
                  />
                  <span>
                    <span className="block text-sm font-semibold text-foreground">
                      {analyticsTitle}
                    </span>
                    <span className="block text-xs text-muted-foreground">
                      {analyticsDescription}
                    </span>
                  </span>
                </label>
              )}

              {showMarketing && (
                <label
                  aria-label={marketingTitle}
                  className="flex cursor-pointer items-start gap-3"
                >
                  <input
                    type="checkbox"
                    checked={draft.marketing}
                    onChange={(event) =>
                      setDraft((state) => ({ ...state, marketing: event.target.checked }))
                    }
                    className="mt-0.5 size-4 shrink-0 rounded accent-primary"
                  />
                  <span>
                    <span className="block text-sm font-semibold text-foreground">
                      {marketingTitle}
                    </span>
                    <span className="block text-xs text-muted-foreground">
                      {marketingDescription}
                    </span>
                  </span>
                </label>
              )}
            </div>
          )}

          <div className="flex shrink-0 flex-wrap items-center justify-end gap-2">
            <button
              type="button"
              onClick={customizing ? cancelSelection : openSelection}
              aria-expanded={customizing}
              className="inline-flex h-10 items-center justify-center rounded-lg border border-border bg-background px-4 text-sm font-semibold text-foreground transition-colors outline-none hover:bg-muted focus-visible:ring-3 focus-visible:ring-ring/40"
            >
              {customizing ? cancelLabel : acceptSelectionLabel}
            </button>
            <button
              type="button"
              onClick={customizing ? confirmSelection : acceptAll}
              className="inline-flex h-10 items-center justify-center rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground transition-colors outline-none hover:bg-primary/90 focus-visible:ring-3 focus-visible:ring-primary/40"
            >
              {customizing ? confirmLabel : acceptAllLabel}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

