"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import type { ReactElement } from "react";

export interface IconTooltipProps {
  label?: string;
  children: ReactElement;
}

/** Compose with the existing control so its semantics, ref and layout stay intact. */
export function IconTooltip({ label, children }: IconTooltipProps) {
  if (!label) return children;

  return (
    <Tooltip.Root>
      <Tooltip.Trigger render={children} />
      <Tooltip.Portal>
        <Tooltip.Positioner sideOffset={8} className="z-[110]">
          <Tooltip.Popup
            role="tooltip"
            className="max-w-[min(20rem,calc(100vw-2rem))] rounded-md bg-popover px-3 py-2 text-xs break-words text-popover-foreground shadow-md dark:border dark:border-border dark:shadow-none"
          >
            {label}
          </Tooltip.Popup>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
}

src/intranet/components/forge/action-toa.text:
"use client";

import { Toast } from "@base-ui/react/toast";
import { CircleAlertIcon, CircleCheckIcon, InfoIcon, LoaderCircleIcon, XIcon } from "lucide-react";
import { createContext, useContext, type ReactNode } from "react";

import { IconTooltip } from "#/intranet/components/forge/icon-tooltip";
import { cn } from "#/intranet/forge/utils";

const ActionToastContext = createContext<string | null>(null);

export interface ActionToastProviderProps {
  children: ReactNode;
  closeLabel?: string;
}

export interface ActionToastData {
  content?: ReactNode;
  dismissible?: boolean;
  closeLabel?: string;
}

export const actionToastButtonClass =
  "inline-flex min-h-10 items-center justify-center gap-2 rounded-md px-3 text-sm font-medium transition-colors md:min-h-8 text-foreground outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-4 cursor-pointer disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed";

export interface ActionToastFooterProps {
  status?: ReactNode;
  actions?: ReactNode;
}

export function ActionToastFooter({ status, actions }: ActionToastFooterProps) {
  return (
    <div className="flex min-h-10 flex-wrap items-center gap-2 md:min-h-8">
      <div className="min-w-0 flex-1">{status}</div>
      <div className="ml-auto flex max-w-full flex-wrap justify-end gap-2">{actions}</div>
    </div>
  );
}

export function ActionToastProvider({ children, closeLabel }: ActionToastProviderProps) {
  const inherited = useContext(ActionToastContext);
  const label = closeLabel ?? inherited ?? "Close";
  return (
    <ActionToastContext.Provider value={label}>
      {inherited !== null ? (
        children
      ) : (
        <Toast.Provider limit={Infinity}>
          {children}
          <ActionToastViewport closeLabel={label} />
        </Toast.Provider>
      )}
    </ActionToastContext.Provider>
  );
}

export function useActionToast() {
  const { add } = Toast.useToastManager<ActionToastData>();
  const closeLabel = useContext(ActionToastContext) ?? "Close";
  return (message: string) => add({ title: message, type: "success", data: { closeLabel } });
}

function ActionToastViewport({ closeLabel }: { closeLabel: string }) {
  const { toasts } = Toast.useToastManager<ActionToastData>();
  return (
    <Toast.Portal>
      <Toast.Viewport className="fixed right-0 bottom-0 z-60 flex max-h-dvh w-full max-w-[26rem] flex-col gap-2 overflow-y-auto p-4 outline-none empty:p-0 sm:right-2 sm:bottom-2 sm:max-h-[calc(100dvh-1rem)]">
        {toasts.map((toast) => {
          const dismissible = toast.data?.dismissible !== false;
          const label = toast.data?.closeLabel ?? closeLabel;
          return (
            <Toast.Root
              key={toast.id}
              toast={toast}
              aria-busy={toast.type === "loading"}
              swipeDirection={dismissible ? undefined : []}
              onKeyDownCapture={(event) => {
                if (!dismissible && event.key === "Escape") event.stopPropagation();
              }}
              className="flex flex-col gap-3 rounded-xl bg-popover p-3 text-popover-foreground shadow-lg outline-none focus-visible:ring-2 focus-visible:ring-ring data-ending:opacity-0 data-limited:hidden motion-safe:transition-opacity dark:border dark:border-border dark:shadow-none"
            >
              <div className="flex items-center gap-3">
                {toast.type === "loading" ? (
                  <LoaderCircleIcon
                    className="size-5 shrink-0 text-status-pending-foreground motion-safe:animate-spin"
                    aria-hidden="true"
                  />
                ) : toast.type === "success" ? (
                  <CircleCheckIcon
                    className="size-5 shrink-0 text-status-success-foreground"
                    aria-hidden="true"
                  />
                ) : toast.type === "error" ? (
                  <CircleAlertIcon
                    className="size-5 shrink-0 text-destructive"
                    aria-hidden="true"
                  />
                ) : (
                  <InfoIcon
                    className="size-5 shrink-0 text-status-info-foreground"
                    aria-hidden="true"
                  />
                )}
                <Toast.Title className="min-w-0 flex-1 text-sm break-words" />
                {dismissible && (
                  <IconTooltip label={label}>
                    <Toast.Close
                      aria-label={label}
                      aria-hidden={false}
                      className={cn(actionToastButtonClass, "size-10 shrink-0 p-0 md:size-8")}
                    >
                      <XIcon className="size-4" aria-hidden="true" />
                    </Toast.Close>
                  </IconTooltip>
                )}
              </div>
              {toast.data?.content}
              {(toast.description || toast.actionProps) && (
                <div className="ms-8">
                  <ActionToastFooter
                    status={
                      <Toast.Description
                        className={cn(
                          "text-sm break-words",
                          toast.type === "error" ? "text-destructive" : "text-muted-foreground",
                        )}
                      />
                    }
                    actions={
                      <Toast.Action
                        className={actionToastButtonClass}
                        disabled={toast.actionProps?.disabled}
                      />
                    }
                  />
                </div>
              )}
            </Toast.Root>
          );
        })}
      </Toast.Viewport>
    </Toast.Portal>
  );
}

src/intranet/components/forge/ui/link.ts.text:
"use client";

// Framework-agnostic Link shim.
// Each site provides the implementation for its framework:
//   - Next.js   : re-export of `next/link`
//   - TanStack  : re-export of `@tanstack/react-router`'s Link (typed `to`)
// The registry imports this shim and never imports a framework router directly.

import { forwardRef } from "react";

import { cn } from "#/intranet/forge/utils.ts";

export interface LinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  href: string;
  children?: React.ReactNode;
}

/**
 * Minimal anchor-based Link. Sites that need router-aware navigation
 * (prefetch, active states) replace this file with a framework re-export —
 * the props above keep the component contract stable.
 */
export const Link = forwardRef<HTMLAnchorElement, LinkProps>(function Link(
  { href, className, children, ...props },
  ref,
) {
  return (
    <a href={href} ref={ref} className={cn(className)} {...props}>
      {children}
    </a>
  );
});

src/intranet/components/forge/ui/use-loc.text:
"use client";

// Framework-agnostic pathname hook (replaces `usePathname` from next/navigation).
// Each site provides the implementation for its framework:
//   - Next.js  : re-export of `next/navigation`'s usePathname
//   - TanStack : re-export of `@tanstack/react-router`'s useLocation().pathname

import { useSyncExternalStore } from "react";

function subscribe() {
  return () => {};
}

/**
 * Minimal pathname getter for environments without a router hook.
 * Sites with a real router replace this file with a framework re-export.
 */
export function usePathname(): string {
  return useSyncExternalStore(
    subscribe,
    () => (typeof window === "undefined" ? "" : window.location.pathname),
    () => "",
  );
}

src/intranet/components/forge/ui/script..text:
export interface ScriptProps extends React.ScriptHTMLAttributes<HTMLScriptElement> {
  id?: string;
  /** Framework hint — Next.js uses strategies; other frameworks ignore it. */
  strategy?: "afterInteractive" | "beforeInteractive" | "lazyOnload";
  /** Inline script source (JS string). */
  code?: string;
  children?: string;
}

/**
 * Minimal inline <script>. Sites that need framework script handling
 * (e.g. Next.js `beforeInteractive`) replace this file with a framework
 * component — the props above keep the component contract stable.
 */
export function Script({ id, strategy, code, children, ...props }: ScriptProps) {
  const source = code ?? children ?? "";
  return (
    <script
      id={id}
      data-strategy={strategy}
      dangerouslySetInnerHTML={{ __html: source }}
      {...props}
    />
  );
}

src/intranet/components/forge/ui/image.t.text:
import { cn } from "#/intranet/forge/utils.ts";

export interface ImageProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  src: string;
  alt: string;
  width?: number;
  height?: number;
  unoptimized?: boolean;
  /** Fill the parent (absolute inset-0) — next/image compatible. */
  fill?: boolean;
  /** Load eagerly with high fetch priority — next/image compatible. */
  priority?: boolean;
  sizes?: string;
  quality?: number;
}

/**
 * Plain <img> based Image. Sites that need an image optimizer replace
 * this file with a framework component — the props above keep the
 * component contract stable.
 */
export function Image({
  src,
  alt,
  width,
  height,
  unoptimized,
  fill,
  priority,
  sizes,
  quality,
  loading,
  className,
  ...props
}: ImageProps) {
  return (
    // oxlint-disable-next-line nextjs/no-img-element -- framework-agnostic shim
    <img
      src={src}
      alt={alt}
      width={fill ? undefined : width}
      height={fill ? undefined : height}
      sizes={sizes}
      loading={loading ?? (priority ? "eager" : "lazy")}
      fetchPriority={priority ? "high" : undefined}
      data-quality={quality}
      data-unoptimized={unoptimized || undefined}
      className={cn(fill && "absolute inset-0 h-full w-full", className)}
      {...props}
    />
  );
}

src/intranet/components/forge/plugins/au.text:
"use client";

import {
  ArrowBigUpDashIcon,
  ArrowRightIcon,
  EyeIcon,
  EyeOffIcon,
  LoaderCircleIcon,
} from "lucide-react";
import { useState, type ComponentType } from "react";

import { Link, type LinkProps } from "#/components/ui/link";
import {
  GoogleSignInButton,
  useAuthAction,
} from "#/intranet/components/forge/plugins/auth/auth-controls";
import { loginLabels, type LoginLabels } from "#/intranet/components/forge/plugins/auth/labels";
import { cn } from "#/intranet/forge/utils";

export {
  GoogleSignInButton,
  SignOutButton,
  useAuthAction,
  type AuthControlProps,
} from "#/intranet/components/forge/plugins/auth/auth-controls";
export type { LoginLabels } from "#/intranet/components/forge/plugins/auth/labels";
export {
  AuthLayout,
  type AuthLayoutProps,
  type AuthLayoutLabels,
} from "#/intranet/components/forge/plugins/auth/auth-layout";
export {
  ForgotPasswordForm,
  ResetPasswordForm,
  ChangePasswordForm,
  ChangePasswordPage,
  type ForgotPasswordFormProps,
  type ResetPasswordFormProps,
  type ChangePasswordFormProps,
  type ChangePasswordPageProps,
  type ChangePasswordValues,
} from "#/intranet/components/forge/plugins/auth/password-forms";
export type { PasswordLabels } from "#/intranet/components/forge/plugins/auth/password-labels";
export {
  AccessDeniedPage,
  type AccessDeniedPageProps,
  type AccessDeniedLabels,
} from "#/intranet/components/forge/plugins/auth/access-denied-page";
export interface LoginCredentials {
  email: string;
  password: string;
  rememberMe: boolean;
}
export interface LoginFormProps {
  onSignIn: (credentials: LoginCredentials) => Promise<void>;
  enabled?: boolean;
  forgotPasswordHref?: string;
  onGoogleSignIn?: () => Promise<void>;
  labels?: Partial<LoginLabels>;
  className?: string;
  linkComponent?: ComponentType<LinkProps>;
}
const inputClass =
  "h-12 w-full rounded-lg border border-input bg-transparent px-3 text-base shadow-xs outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50 md:text-sm";
const buttonClass =
  "inline-flex h-12 w-full items-center justify-center gap-2 rounded-lg text-sm font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-4";

export function LoginForm({
  onSignIn,
  enabled = true,
  forgotPasswordHref,
  onGoogleSignIn,
  labels: overrides,
  className,
  linkComponent: LoginLink = Link,
}: LoginFormProps) {
  const labels = { ...loginLabels, ...overrides };
  const [showPassword, setShowPassword] = useState(false);
  const [capsLock, setCapsLock] = useState(false);
  const action = useAuthAction();
  const [method, setMethod] = useState<"password" | "google">("password");
  const { pending, failed } = action;
  const googlePending = pending && method === "google";
  return (
    <div className={cn("flex flex-col gap-7", className)}>
      <div>
        <p className="mb-3 text-xs font-semibold tracking-widest text-primary! uppercase">
          {labels.teamSpace}
        </p>
        <h1 className="text-3xl font-semibold tracking-tight text-foreground sm:text-4xl">
          {labels.welcomeBack}
        </h1>
        <p className="mt-3 text-sm leading-relaxed text-muted-foreground!">
          {labels.welcomeSubtitle}
        </p>
      </div>

      {!enabled && (
        <output className="rounded-xl border border-border bg-muted/50 p-4 text-sm">
          {labels.unavailable}
        </output>
      )}

      {failed && (
        <p id="login-error" role="alert" className="text-sm text-destructive">
          {method === "google" ? labels.googleError : labels.loginError}
        </p>
      )}
      <form
        method="post"
        onSubmit={(event) => {
          event.preventDefault();
          const data = new FormData(event.currentTarget);
          const email = data.get("email");
          const password = data.get("password");
          if (typeof email !== "string" || typeof password !== "string") return;
          if (!enabled) return;
          void action.run(async () => {
            setMethod("password");
            await onSignIn({
              email: email.trim(),
              password,
              rememberMe: data.get("rememberMe") === "on",
            });
          });
        }}
        className="grid gap-5"
        aria-busy={pending}
      >
        <div className="grid gap-2">
          <label htmlFor="email">{labels.email}</label>
          <input
            id="email"
            name="email"
            type="email"
            autoComplete="username"
            autoCapitalize="none"
            spellCheck={false}
            placeholder="name@example.com"
            className={inputClass}
            readOnly={action.disabled}
            disabled={!enabled}
            aria-describedby={failed ? "login-error" : undefined}
            required
          />
        </div>
        <div className="grid gap-2">
          <label htmlFor="password">{labels.password}</label>
          <div className="relative">
            <input
              id="password"
              name="password"
              type={showPassword ? "text" : "password"}
              autoComplete="current-password"
              className={cn(inputClass, capsLock ? "pr-20" : "pr-12")}
              onKeyDown={(event) => setCapsLock(event.getModifierState("CapsLock"))}
              onKeyUp={(event) => setCapsLock(event.getModifierState("CapsLock"))}
              onClick={(event) => setCapsLock(event.getModifierState("CapsLock"))}
              onBlur={() => setCapsLock(false)}
              readOnly={action.disabled}
              disabled={!enabled}
              aria-describedby={
                [failed && "login-error", capsLock && "password-caps-lock"]
                  .filter(Boolean)
                  .join(" ") || undefined
              }
              required
            />
            <output
              id="password-caps-lock"
              htmlFor="password"
              title={capsLock ? labels.capsLockOn : undefined}
              className="absolute inset-y-0 right-12 flex items-center text-primary"
            >
              {capsLock && (
                <>
                  <ArrowBigUpDashIcon className="mx-2 size-4" aria-hidden="true" />
                  <span className="sr-only">{labels.capsLockOn}</span>
                </>
              )}
            </output>
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              aria-label={showPassword ? labels.hidePassword : labels.showPassword}
              aria-controls="password"
              aria-pressed={showPassword}
              className="absolute inset-y-0 right-0 flex w-12 items-center justify-center rounded-lg text-muted-foreground! hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"
            >
              {showPassword ? <EyeOffIcon className="size-4" /> : <EyeIcon className="size-4" />}
            </button>
          </div>
        </div>
        <div className="flex flex-wrap items-center justify-between gap-3 text-sm">
          <label className="flex cursor-pointer items-center gap-2 text-muted-foreground!">
            <input
              type="checkbox"
              name="rememberMe"
              className="size-4 accent-primary"
              disabled={action.disabled || !enabled}
            />
            {labels.rememberMe}
          </label>
          {forgotPasswordHref && (
            <LoginLink
              href={forgotPasswordHref}
              className="font-medium text-primary hover:underline"
            >
              {labels.forgotPassword}
            </LoginLink>
          )}
        </div>
        <button
          type="submit"
          className={cn(buttonClass, "bg-primary text-primary-foreground hover:bg-primary/90")}
          disabled={action.disabled || !enabled}
        >
          {pending && !googlePending ? <LoaderCircleIcon className="animate-spin" /> : null}
          {pending && !googlePending ? labels.signingIn : labels.signIn}
          {!pending && <ArrowRightIcon className="size-4" />}
        </button>
      </form>

      {onGoogleSignIn && (
        <>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <span className="h-px flex-1 bg-border" />
            {labels.orDivider}
            <span className="h-px flex-1 bg-border" />
          </div>
          <GoogleSignInButton
            className="w-full"
            label={labels.continueGoogle}
            pendingLabel={labels.connectingGoogle}
            pending={googlePending}
            disabled={action.disabled || !enabled}
            onClick={() =>
              void action.run(async () => {
                setMethod("google");
                await onGoogleSignIn();
              })
            }
          />
        </>
      )}
      <p className="border-t border-border pt-6 text-sm leading-relaxed text-muted-foreground!">
        {labels.contactAdmin}
      </p>
    </div>
  );
}

export {
