});

test.afterAll(async () => {
  await sql`DELETE FROM verification WHERE value IN (${id}, ${resetId}, ${failedId})`;
  await sql`DELETE FROM "user" WHERE id IN (${id}, ${resetId}, ${failedId})`;
  await sql.end();
  await unlink(mailPath).catch(() => {});
});

