"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";

import { cn } from "#/components/utils/cn.ts";
import { createLoadingStore } from "#/components/utils/loading-store.ts";

const LoadingContext = createContext<ReturnType<typeof createLoadingStore> | null>(null);

export interface LoadingProviderProps {
  children: ReactNode;
}

/** Place one provider around the app and one indicator below its navbar. */
export function LoadingProvider({ children }: LoadingProviderProps) {
  const inherited = useContext(LoadingContext);
  const [local] = useState(createLoadingStore);
  useEffect(() => () => local.dispose(), [local]);
  return <LoadingContext.Provider value={inherited ?? local}>{children}</LoadingContext.Provider>;
}

/** Report the real loading state; cleanup releases it on cancellation or unmount. */
export function useLoadingActivity(loading: boolean) {
  const store = useContext(LoadingContext);
  useEffect(() => {
    if (loading) return store?.start();
  }, [loading, store]);
}

/** Track imperative actions too, including promises that resolve before a render. */
export function useLoadingTask() {
  const store = useContext(LoadingContext);
  const pending = useRef(new Set<() => void>());
  useEffect(() => {
    const tasks = pending.current;
    return () => {
      tasks.forEach((finish) => finish());
      tasks.clear();
    };
  }, [store]);
  return useCallback(
    async <T,>(task: () => Promise<T>): Promise<T> => {
      const finish = store?.start();
      if (finish) pending.current.add(finish);
      try {
        return await task();
      } finally {
        finish?.();
        if (finish) pending.current.delete(finish);
      }
    },
    [store],
  );
}

export interface LoadingIndicatorProps {
  label?: string;
  className?: string;
}

export function LoadingIndicator({ label = "Loading…", className }: LoadingIndicatorProps) {
  const store = useContext(LoadingContext);
  return store ? <ActivityBar store={store} label={label} className={className} /> : null;
}

function ActivityBar({
  store,
  label,
  className,
}: LoadingIndicatorProps & { store: ReturnType<typeof createLoadingStore> }) {
  const state = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getServerSnapshot);
  return (
    <div
      data-slot="loading-indicator"
      data-state={state}
      hidden={state === "idle"}
      className={cn(
        "pointer-events-none fixed inset-x-0 top-0 z-[1100] h-1 overflow-hidden bg-primary/20 print:hidden",
        className,
      )}
    >
      <progress aria-label={label} className="sr-only" />
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          [data-slot="loading-indicator"] > div {
            transform: scaleX(0.9);
            transition: transform 8s ease-out;
          }
          [data-slot="loading-indicator"][data-state="complete"] > div {
            transform: scaleX(1);
            transition: transform 300ms linear;
          }
          @starting-style {
            [data-slot="loading-indicator"] > div,
            [data-slot="loading-indicator"][data-state="complete"] > div {
              transform: scaleX(0);
            }
          }
        }
      `}</style>
      <div aria-hidden="true" className="h-full w-full origin-left bg-primary" />
    </div>
  );
}

src/components/action-toast.tsx.text:
"use client";

import { Toast } from "@base-ui/react/toast";
import { CircleAlertIcon, CircleCheckIcon, InfoIcon, LoaderCircleIcon, XIcon } from "lucide-react";
import { createContext, useContext, type ReactNode } from "react";

import { IconTooltip } from "#/components/icon-tooltip.tsx";
import { cn } from "#/components/utils/cn.ts";

const ActionToastContext = createContext<string | null>(null);

export interface ActionToastProviderProps {
  children: ReactNode;
  closeLabel?: string;
}

export interface ActionToastData {
  content?: ReactNode;
  dismissible?: boolean;
  closeLabel?: string;
}

export const actionToastButtonClass =
  "inline-flex min-h-10 items-center justify-center gap-2 rounded-md px-3 text-sm font-medium transition-colors md:min-h-8 text-foreground outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-4 cursor-pointer disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed";

export interface ActionToastFooterProps {
  status?: ReactNode;
  actions?: ReactNode;
}

export function ActionToastFooter({ status, actions }: ActionToastFooterProps) {
  return (
    <div className="flex min-h-10 flex-wrap items-center gap-2 md:min-h-8">
      <div className="min-w-0 flex-1">{status}</div>
      <div className="ml-auto flex max-w-full flex-wrap justify-end gap-2">{actions}</div>
    </div>
  );
}

export function ActionToastProvider({ children, closeLabel }: ActionToastProviderProps) {
  const inherited = useContext(ActionToastContext);
  const label = closeLabel ?? inherited ?? "Close";
  return (
    <ActionToastContext.Provider value={label}>
      {inherited !== null ? (
        children
      ) : (
        <Toast.Provider limit={Infinity}>
          {children}
          <ActionToastViewport closeLabel={label} />
        </Toast.Provider>
      )}
    </ActionToastContext.Provider>
  );
}

export function useActionToast() {
  const { add } = Toast.useToastManager<ActionToastData>();
  const closeLabel = useContext(ActionToastContext) ?? "Close";
  return (message: string) => add({ title: message, type: "success", data: { closeLabel } });
}

function ActionToastViewport({ closeLabel }: { closeLabel: string }) {
  const { toasts } = Toast.useToastManager<ActionToastData>();
  const totalHeight = toasts.reduce((height, toast) => height + (toast.height ?? 0), 0);
  const expandedHeight = `calc(${totalHeight}px + ${Math.max(0, toasts.length - 1)} * 0.75rem + 2rem)`;
  return (
    <Toast.Portal>
      <Toast.Viewport
        style={({ expanded }) => ({ height: expanded ? expandedHeight : undefined })}
        className="fixed right-0 bottom-0 z-60 flex h-[calc(var(--toast-frontmost-height,0px)+4rem)] max-h-dvh w-full max-w-[26rem] flex-col-reverse p-4 outline-none empty:h-0 empty:p-0 data-expanded:overflow-x-hidden data-expanded:overflow-y-auto sm:right-2 sm:bottom-2 sm:max-h-[calc(100dvh-1rem)]"
      >
        {toasts.map((toast) => {
          const dismissible = toast.data?.dismissible !== false;
          const label = toast.data?.closeLabel ?? closeLabel;
          return (
            <Toast.Root
              key={toast.id}
              toast={toast}
              aria-busy={toast.type === "loading"}
              swipeDirection={dismissible ? undefined : []}
              onKeyDownCapture={(event) => {
                if (!dismissible && event.key === "Escape") event.stopPropagation();
              }}
              className={cn(
                "absolute inset-x-4 bottom-4 z-[calc(1000-var(--toast-index))] h-(--height) origin-bottom overflow-hidden rounded-xl bg-popover p-3 text-popover-foreground shadow-lg outline-none focus-visible:ring-2 focus-visible:ring-ring dark:border dark:border-border dark:shadow-none",
                // Match shadcn's Base UI motion while keeping every recovery toast in the queue.
                "[--gap:0.75rem] [--height:var(--toast-frontmost-height,var(--toast-height))] [--offset-y:calc(var(--toast-offset-y)*-1+var(--toast-index)*var(--gap)*-1+var(--toast-swipe-movement-y))] [--peek:0.75rem] [--scale:calc(1-var(--stack-index)*0.1)] [--shrink:calc(1-var(--scale))] [--stack-index:min(var(--toast-index),2)]",
                "[transform:translateX(var(--toast-swipe-movement-x))_translateY(calc(var(--toast-swipe-movement-y)-var(--stack-index)*var(--peek)-var(--shrink)*var(--height)))_scale(var(--scale))] motion-safe:[transition:transform_500ms_cubic-bezier(0.22,1,0.36,1),opacity_500ms,height_150ms]",
                "data-expanded:h-(--toast-height) data-expanded:[transform:translateX(var(--toast-swipe-movement-x))_translateY(var(--offset-y))] data-limited:hidden data-starting-style:[transform:translateY(150%)]",
                "data-ending-style:pointer-events-none [&[data-ending-style]:not([data-swipe-direction])]:[transform:translateY(150%)]",
                "data-ending-style:data-[swipe-direction=down]:[transform:translateY(calc(var(--toast-swipe-movement-y)+150%))] data-expanded:data-ending-style:data-[swipe-direction=down]:[transform:translateY(calc(var(--toast-swipe-movement-y)+150%))]",
                "data-ending-style:data-[swipe-direction=right]:[transform:translateX(calc(var(--toast-swipe-movement-x)+150%))_translateY(var(--offset-y))] data-expanded:data-ending-style:data-[swipe-direction=right]:[transform:translateX(calc(var(--toast-swipe-movement-x)+150%))_translateY(var(--offset-y))]",
              )}
            >
              <Toast.Content className="flex flex-col gap-3 data-behind:pointer-events-none data-behind:opacity-0 data-expanded:pointer-events-auto data-expanded:opacity-100 motion-safe:transition-opacity motion-safe:duration-250 motion-safe:ease-[cubic-bezier(0.22,1,0.36,1)]">
                <div className="flex items-center gap-3">
                  {toast.type === "loading" ? (
                    <LoaderCircleIcon
                      className="size-5 shrink-0 text-status-pending-foreground motion-safe:animate-spin"
                      aria-hidden="true"
                    />
                  ) : toast.type === "success" ? (
                    <CircleCheckIcon
                      className="size-5 shrink-0 text-status-success-foreground"
                      aria-hidden="true"
                    />
                  ) : toast.type === "error" ? (
                    <CircleAlertIcon
                      className="size-5 shrink-0 text-destructive"
                      aria-hidden="true"
                    />
                  ) : (
                    <InfoIcon
                      className="size-5 shrink-0 text-status-info-foreground"
                      aria-hidden="true"
                    />
                  )}
                  <Toast.Title className="min-w-0 flex-1 text-sm break-words" />
                  {dismissible && (
                    <IconTooltip label={label}>
                      <Toast.Close
                        aria-label={label}
                        aria-hidden={false}
                        className={cn(actionToastButtonClass, "size-10 shrink-0 p-0 md:size-8")}
                      >
                        <XIcon className="size-4" aria-hidden="true" />
                      </Toast.Close>
                    </IconTooltip>
                  )}
                </div>
                {toast.data?.content}
                {(toast.description || toast.actionProps) && (
                  <div className="ms-8">
                    <ActionToastFooter
                      status={
                        <Toast.Description
                          className={cn(
                            "text-sm break-words",
                            toast.type === "error" ? "text-destructive" : "text-muted-foreground",
                          )}
                        />
                      }
                      actions={
                        <Toast.Action
                          className={actionToastButtonClass}
                          disabled={toast.actionProps?.disabled}
                        />
                      }
                    />
                  </div>
                )}
              </Toast.Content>
            </Toast.Root>
          );
        })}
      </Toast.Viewport>
    </Toast.Portal>
  );
}

src/components/table-pagination.tsx.text:
"use client";

import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react";
import type { ReactNode } from "react";

import { IconTooltip } from "#/components/icon-tooltip.tsx";
import { cn } from "#/components/utils/cn.ts";
import { tableFooterClass } from "#/components/utils/table-styles.ts";

export interface TablePaginationProps {
  summary?: ReactNode;
  /** Current page, including cursor paging when the total is unknown. */
  page?: number;
  /** Omit when the total is unknown. */
  pageCount?: number;
  onPrevious: () => void;
  onNext: () => void;
  previousDisabled?: boolean;
  nextDisabled?: boolean;
  disabled?: boolean;
  label?: string;
  previousLabel?: string;
  nextLabel?: string;
  className?: string;
}

const buttonClass =
  "group/pagination inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-md border border-border bg-background text-foreground outline-none transition-colors enabled:hover:bg-accent enabled:hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 md:size-8";

export function TablePagination({
  summary,
  page,
  pageCount,
  onPrevious,
  onNext,
  previousDisabled = false,
  nextDisabled = false,
  disabled = false,
  label = "Pagination",
  previousLabel = "Previous page",
  nextLabel = "Next page",
  className,
}: TablePaginationProps) {
  return (
    <nav aria-label={label} className={cn(tableFooterClass, className)}>
      {summary != null && (
        <span className="min-w-0 text-sm text-muted-foreground tabular-nums">{summary}</span>
      )}
      <div className="flex shrink-0 items-center gap-2">
        <IconTooltip label={previousLabel}>
          <button
            type="button"
            className={buttonClass}
            disabled={disabled || previousDisabled}
            onClick={onPrevious}
            aria-label={previousLabel}
          >
            <ChevronLeftIcon
              className="size-4 shrink-0 motion-safe:transition-transform motion-safe:duration-150 motion-safe:group-[:enabled:focus-visible]/pagination:-translate-x-0.5 motion-safe:group-[:enabled:hover]/pagination:-translate-x-0.5"
              aria-hidden="true"
            />
          </button>
        </IconTooltip>
        {page != null && (
          <span
            className="min-w-9 text-center text-sm whitespace-nowrap text-muted-foreground tabular-nums"
            aria-live="polite"
            aria-atomic="true"
          >
            {pageCount == null ? page : `${page}/${pageCount}`}
          </span>
        )}
        <IconTooltip label={nextLabel}>
          <button
            type="button"
            className={buttonClass}
            disabled={disabled || nextDisabled}
            onClick={onNext}
            aria-label={nextLabel}
          >
            <ChevronRightIcon
              className="size-4 shrink-0 motion-safe:transition-transform motion-safe:duration-150 motion-safe:group-[:enabled:focus-visible]/pagination:translate-x-0.5 motion-safe:group-[:enabled:hover]/pagination:translate-x-0.5"
              aria-hidden="true"
            />
          </button>
        </IconTooltip>
      </div>
    </nav>
  );
}

src/components/table-selection.tsx.text:
"use client";

import { Dialog } from "@base-ui/react/dialog";
import { XIcon, Trash2Icon } from "lucide-react";
import { useCallback, useEffect, useLayoutEffect, useRef, useState, type ReactNode } from "react";

import { useActionToast } from "#/components/action-toast.tsx";
import { IconTooltip } from "#/components/icon-tooltip.tsx";
import { cn } from "#/components/utils/cn.ts";
import {
  tableSelectionLabels,
  type TableSelectionLabels,
} from "#/components/utils/table-selection-labels.ts";
import { useOptimisticAction } from "#/components/utils/use-optimistic-action.ts";
export type { TableSelectionLabels } from "#/components/utils/table-selection-labels";

export interface TableDeletionOptions<T> {
  onDelete: (item: T, requestId: string) => Promise<unknown>;
  prepare?: (items: readonly T[]) => Promise<ReactNode>;
  onComplete?: (count: number) => void;
}
interface DeletionSession<T> {
  scope: string;
  options: TableDeletionOptions<T>;
  entries: { item: T; requestId: string }[];
  phase: "preparing" | "ready" | "deleting";
  ready: boolean;
  details?: ReactNode;
  failure?: { stage: "prepare" | "delete"; cause: unknown };
  attempted: number;
}

export function useTableSelection<T extends { id: string }>(items: readonly T[], scope = "") {
  const [state, setState] = useState({ ids: [] as string[], scope });
  const [session, setSession] = useState<DeletionSession<T> | null>(null);
  const active = useRef<DeletionSession<T> | null>(null);
  const requestPending = useRef(false);
  const mounted = useRef(true);
  const currentScope = useRef(scope);
  const optimistic = useOptimisticAction<string | undefined>(undefined, scope);
  const dispose = useCallback(() => {
    active.current = null;
    if (mounted.current) setSession(null);
  }, []);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      active.current = null;
    };
  }, []);
  useLayoutEffect(() => {
    currentScope.current = scope;
    if (active.current && active.current.scope !== scope && active.current.attempted === 0)
      dispose();
  }, [scope, dispose]);
  const selected = items.filter((item) => state.scope === scope && state.ids.includes(item.id));
  if (state.scope !== scope || selected.length !== state.ids.length) {
    setState({ ids: selected.map((item) => item.id), scope });
  }
  const visible = session && (session.scope === scope || session.attempted > 0) ? session : null;
  const pending = (!!visible && visible.phase !== "ready") || optimistic.pending;
  const current = (target: DeletionSession<T>) => mounted.current && active.current === target;
  const busy = () =>
    requestPending.current || (!!active.current && active.current.phase !== "ready");
  const publish = (target: DeletionSession<T>) => {
    if (current(target)) setSession({ ...target });
  };
  async function prepare(target: DeletionSession<T>, options: TableDeletionOptions<T>) {
    target.phase = "preparing";
    target.ready = false;
    target.details = undefined;
    publish(target);
    try {
      const details = await options.prepare?.(target.entries.map(({ item }) => item));
      if (!current(target)) return;
      target.details = details;
      target.ready = true;
    } catch (cause) {
      if (!current(target)) return;
      target.failure = { stage: "prepare", cause };
    }
    target.phase = "ready";
    publish(target);
  }
  async function confirm(provided: TableDeletionOptions<T>) {
    const target = active.current;
    if (!target || busy()) return;
    const options = target.scope === currentScope.current ? provided : target.options;
    target.options = options;
    target.failure = undefined;
    if (!target.ready) return prepare(target, options);
    target.phase = "deleting";
    const entries = target.entries;
    target.attempted = entries.length;
    publish(target);
    const failed: typeof entries = [];
    let reason: unknown;
    for (const entry of entries) {
      if (!current(target)) return;
      try {
        requestPending.current = true;
        await optimistic.run(
          () => entry.item.id,
          () => options.onDelete(entry.item, entry.requestId),
        );
        if (current(target))
          setState((previous) =>
            previous.scope === target.scope
              ? { ...previous, ids: previous.ids.filter((id) => id !== entry.item.id) }
              : previous,
          );
      } catch (error) {
        failed.push(entry);
        reason = error;
      } finally {
        requestPending.current = false;
      }
    }
    if (!current(target)) return;
    if (!failed.length) {
      dispose();
      options.onComplete?.(entries.length);
    } else {
      target.entries = failed;
      target.failure = { stage: "delete", cause: reason };
      await prepare(target, options);
    }
  }
  return {
    selected,
    scope,
    pending,
    isDeleting: (id: string) =>
      visible?.scope === scope && optimistic.pending && optimistic.value === id,
    deletion: {
      items: visible?.entries.map(({ item }) => item) ?? [],
      details: visible?.details,
      ready: visible?.ready ?? false,
      failure: visible?.failure,
      attempted: visible?.attempted ?? 0,
      open(options: TableDeletionOptions<T>, targets: readonly T[] = selected) {
        if (busy() || !targets.length) return;
        const target: DeletionSession<T> = {
          scope,
          options,
          entries: targets.map((item) => ({ item, requestId: crypto.randomUUID() })),
          phase: "preparing",
          ready: false,
          attempted: 0,
        };
        active.current = target;
        void prepare(target, options);
      },
      confirm,
      close() {
        if (!busy()) dispose();
      },
      /** A dialog can unmount while its table remains mounted. */
      dispose,
    },
    all: items.length > 0 && selected.length === items.length,
    mixed: selected.length > 0 && selected.length < items.length,
    toggleAll: (checked: boolean) => {
      if (!busy()) setState({ ids: checked ? items.map((item) => item.id) : [], scope });
    },
    toggle: (id: string, checked: boolean) => {
      if (busy()) return;
      setState((current) => ({
        scope,
        ids: checked
          ? [...current.ids.filter((value) => value !== id), id]
          : current.ids.filter((value) => value !== id),
      }));
    },
  };
}

export interface TableSelectionCheckboxProps {
  label: string;
  checked: boolean;
  mixed?: boolean;
  disabled?: boolean;
  onChange: (checked: boolean) => void;
}
export function TableSelectionCheckbox({
  label,
  checked,
  mixed = false,
  disabled,
  onChange,
}: TableSelectionCheckboxProps) {
  return (
    <label className="inline-flex size-10 items-center justify-center md:size-8">
      <input
        type="checkbox"
        aria-label={label}
        checked={checked}
        ref={(input) => {
          if (input) input.indeterminate = mixed;
        }}
        disabled={disabled}
        onChange={(event) => onChange(event.target.checked)}
        className="size-4 cursor-pointer accent-primary focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50"
      />
    </label>
  );
}

const buttonClass =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-md border border-border px-3 text-sm font-medium outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 md:min-h-8";
const destructiveClass =
  "border-transparent bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30";

export interface TableBulkDeleteProps<T extends { id: string }> {
  selection: ReturnType<typeof useTableSelection<T>>;
  getName: (item: T) => string;
  onDelete: (item: T, requestId: string) => Promise<unknown>;
  /** Fetch and display any server-owned deletion preview before allowing confirmation. */
  prepare?: (items: readonly T[]) => Promise<ReactNode>;
  errorMessage?: (error: unknown) => string;
  description?: ReactNode;
  labels?: Partial<TableSelectionLabels>;
  disabled?: boolean;
}
export function TableBulkDelete<T extends { id: string }>({
  selection,
  getName,
  onDelete,
  prepare,
  errorMessage,
  description,
  labels: overrides,
  disabled,
}: TableBulkDeleteProps<T>) {
  const labels = { ...tableSelectionLabels, ...overrides };
  const { deletion } = selection;
  useEffect(() => deletion.dispose, [deletion.dispose]);
  const notify = useActionToast();
  const options: TableDeletionOptions<T> = {
    onDelete,
    prepare,
    onComplete: () => {
      if (labels.bulkDeleted) notify(labels.bulkDeleted);
    },
  };
  const failure = deletion.failure
    ? (errorMessage?.(deletion.failure.cause) ??
      (deletion.failure.stage === "prepare" ? labels.bulkPrepareError : labels.bulkDeleteError))
    : "";
  const actionLabel = `${labels.deleteSelected} (${selection.selected.length})`;
  const actionDisabled = disabled || selection.pending || selection.selected.length === 0;
  return (
    <>
      <div className="size-10 shrink-0 md:size-8">
        <IconTooltip label={actionLabel}>
          <button
            type="button"
            aria-label={actionLabel}
            className={cn(
              buttonClass,
              actionDisabled
                ? "bg-background text-foreground disabled:hover:bg-background"
                : destructiveClass,
              "size-10 p-0 md:size-8",
            )}
            disabled={actionDisabled}
            onClick={() => {
              if (!actionDisabled) deletion.open(options);
            }}
          >
            <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
          </button>
        </IconTooltip>
      </div>
      <Dialog.Root
        open={deletion.items.length > 0}
        onOpenChange={(open) => {
          if (!open) deletion.close();
        }}
      >
        <Dialog.Portal>
          <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
          <Dialog.Popup className="fixed top-1/2 left-1/2 z-50 grid max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 scroll-py-32 gap-4 overflow-y-auto rounded-xl border border-border bg-popover px-6 text-popover-foreground shadow-xl">
            <div
              data-dialog-header
              className="sticky top-0 z-20 -mx-6 space-y-2 bg-popover px-6 pt-5 pb-0"
            >
              <div className="flex items-start justify-between gap-3">
                <Dialog.Title className="min-w-0 flex-1 text-lg font-semibold break-words">
                  {labels.bulkDeleteTitle}
                </Dialog.Title>
                <IconTooltip label={labels.bulkClose ?? labels.bulkCancel}>
                  <Dialog.Close
                    type="button"
                    aria-label={labels.bulkClose ?? labels.bulkCancel}
                    disabled={selection.pending}
                    className={cn(buttonClass, "size-10 shrink-0 p-0 md:size-8")}
                  >
                    <XIcon className="size-4 shrink-0" aria-hidden="true" />
                  </Dialog.Close>
                </IconTooltip>
              </div>
              <Dialog.Description className="text-sm text-muted-foreground">
                {description ?? labels.bulkDeleteDescription}
              </Dialog.Description>
            </div>
            <ul className="max-h-48 list-inside list-disc overflow-y-auto text-sm">
              {deletion.items.map((item) => (
                <li key={item.id} className="break-words">
                  {getName(item)}
                </li>
              ))}
            </ul>
            {prepare && (
              <div
                className="h-32 overflow-y-auto"
                aria-busy={selection.pending && !deletion.ready}
              >
                {deletion.details ??
                  (selection.pending && (
                    <output className="block text-sm text-muted-foreground">
                      {labels.bulkPending}
                    </output>
                  ))}
              </div>
            )}
            <div className="h-10 overflow-y-auto text-sm text-destructive">
              {failure && <p role="alert">{failure}</p>}
            </div>
            <div
              data-dialog-footer
              className="sticky bottom-0 z-10 -mx-6 flex flex-wrap justify-end gap-2 bg-popover px-6 pt-0 pb-5"
            >
              <Dialog.Close className={buttonClass} disabled={selection.pending}>
                {labels.bulkCancel}
              </Dialog.Close>
              <button
                type="button"
                className={cn(buttonClass, destructiveClass)}
                disabled={disabled || selection.pending}
                onClick={() => {
                  if (!disabled) void deletion.confirm(options);
                }}
              >
                {selection.pending
                  ? labels.bulkPending
                  : deletion.ready
                    ? labels.bulkConfirm
                    : labels.bulkRetry}
              </button>
            </div>
          </Dialog.Popup>
        </Dialog.Portal>
      </Dialog.Root>
    </>
  );
}

src/components/image-crop.tsx.text:
"use client";

import { Dialog } from "@base-ui/react/dialog";
import { XIcon } from "lucide-react";
import { useEffect, useId, useRef, useState } from "react";

import { IconTooltip } from "#/components/icon-tooltip.tsx";
import { cn } from "#/components/utils/cn.ts";
import {
  exportImageCrop,
  imageCropRect,
  validImageCropSize,
  type ImageCropSize,
} from "#/components/utils/crop-image.ts";
import { submitDialogOnShortcut } from "#/components/utils/dialog-submit.ts";

export type { ImageCropSize } from "#/components/utils/crop-image";

const defaultLabels = {
  title: "Crop image",
  description: "Drag the image or use the sliders to frame it. Confirm to create a WebP image.",
  preview: "Crop preview",
  zoom: "Zoom",
  horizontal: "Horizontal position",
  vertical: "Vertical position",
  cancel: "Cancel",
  close: "Close",
  confirm: "Use image",
  loading: "Loading image…",
  pending: "Preparing image…",
  invalid: "Choose a JPEG, PNG or WebP image within the upload size limit.",
  dimensions: "The requested image dimensions are invalid or too large.",
  decodeError: "This image could not be opened or is too large. Choose another image.",
  saveError: "The image could not be prepared or uploaded. Try again, or choose another image.",
};
export type ImageCropLabels = Omit<typeof defaultLabels, "close"> & { close?: string };

export interface ImageCropDialogProps extends ImageCropSize {
  file: File | null;
  onConfirm: (file: File) => void | Promise<void>;
  onCancel: () => void;
  labels?: Partial<ImageCropLabels>;
  maxFileBytes?: number;
  className?: string;
}

const buttonClass =
  "inline-flex min-h-10 cursor-pointer items-center justify-center rounded-md px-3 text-sm font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50 md:min-h-8";

export function ImageCropDialog(props: ImageCropDialogProps) {
  return props.file ? <CropSession {...props} file={props.file} /> : null;
}

function CropSession({
  file,
  width,
  height,
  onConfirm,
  onCancel,
  labels: overrides,
  maxFileBytes = 10 * 1024 * 1024,
  className,
}: ImageCropDialogProps & { file: File }) {
  const labels = { ...defaultLabels, ...overrides };
  const id = `factory-image-crop-${useId()}`;
  const canvas = useRef<HTMLCanvasElement>(null);
  const lock = useRef(false);
  const drag = useRef<{ x: number; y: number; horizontal: number; vertical: number } | null>(null);
  const [loaded, setLoaded] = useState<{ file: File; image: HTMLImageElement } | null>(null);
  const [position, setPosition] = useState({ zoom: 1, x: 0.5, y: 0.5 });
  const prepared = useRef<{
    source: File;
    width: number;
    height: number;
    position: typeof position;
    file: File;
  } | null>(null);
  const [error, setError] = useState<keyof ImageCropLabels | null>(null);
  const [pending, setPending] = useState(false);
  const ready = loaded?.file === file && validImageCropSize({ width, height });

  useEffect(() => {
    let canceled = false;
    let url: string | undefined;
    const image = new Image();
    void Promise.resolve()
      .then(() => {
        if (canceled) return;
        setLoaded(null);
        setError(null);
        setPosition({ zoom: 1, x: 0.5, y: 0.5 });
        if (!validImageCropSize({ width, height })) {
          setError("dimensions");
          return;
        }
        if (
          !file.size ||
          !Number.isFinite(maxFileBytes) ||
          maxFileBytes <= 0 ||
          file.size > maxFileBytes ||
          !["image/jpeg", "image/png", "image/webp"].includes(file.type)
        ) {
          setError("invalid");
          return;
        }
        image.onload = () => {
          if (canceled) return;
          if (
            !image.naturalWidth ||
            !image.naturalHeight ||
            image.naturalWidth * image.naturalHeight > 40_000_000
          ) {
            setError("decodeError");
            return;
          }
          setLoaded({ file, image });
        };
        image.onerror = () => {
          if (!canceled) setError("decodeError");
        };
        url = URL.createObjectURL(file);
        image.src = url;
      })
      .catch(() => {
        if (!canceled) setError("decodeError");
      });
    return () => {
      canceled = true;
      image.onload = null;
      image.onerror = null;
      if (url) URL.revokeObjectURL(url);
    };
  }, [file, width, height, maxFileBytes]);

  useEffect(() => {
    if (!ready || !loaded || !canvas.current) return;
    const context = canvas.current.getContext("2d");
    if (!context) return;
    const crop = imageCropRect(
      { width: loaded.image.naturalWidth, height: loaded.image.naturalHeight },
      { width, height },
      position.zoom,
      position.x,
      position.y,
    );
    context.clearRect(0, 0, canvas.current.width, canvas.current.height);
    context.drawImage(
      loaded.image,
      crop.x,
      crop.y,
      crop.width,
      crop.height,
      0,
      0,
      canvas.current.width,
      canvas.current.height,
    );
  }, [loaded, ready, width, height, position]);

  async function confirm() {
    if (!ready || !loaded || lock.current) return;
    lock.current = true;
    setPending(true);
    setError(null);
    try {
      // Reuse the same File on retry so host upload idempotency keys stay stable.
      const cached = prepared.current;
      const result =
        cached?.source === file &&
        cached.width === width &&
        cached.height === height &&
        cached.position === position
          ? cached.file
          : await exportImageCrop(
              loaded.image,
              file,
              { width, height },
              position.zoom,
              position.x,
              position.y,
            );
      prepared.current = { source: file, width, height, position, file: result };
      if (result.size > maxFileBytes) throw new Error("Image exceeds upload limit");
      await onConfirm(result);
    } catch {
      setError("saveError");
    } finally {
      lock.current = false;
      setPending(false);
    }
  }

  return (
    <Dialog.Root
      open
      onOpenChange={(open) => {
        if (!open && !lock.current) onCancel();
      }}
    >
      <Dialog.Portal>
        {/* Notifications from a previous upload must not cover the active crop editor. */}
        <Dialog.Backdrop className="fixed inset-0 z-70 bg-foreground/30" />
        <Dialog.Popup
          className={cn(
            "fixed top-1/2 left-1/2 z-70 max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-xl -translate-x-1/2 -translate-y-1/2 scroll-py-32 overflow-y-auto rounded-xl bg-card px-5 text-card-foreground shadow-xl sm:px-6",
            className,
          )}
          onKeyDown={submitDialogOnShortcut}
        >
          <div
            data-dialog-header
            className="sticky top-0 z-20 -mx-5 mb-0 flex items-start justify-between gap-3 bg-card px-5 pt-5 pb-2 sm:-mx-6 sm:px-6"
          >
            <Dialog.Title className="min-w-0 flex-1 text-lg font-semibold break-words">
              {labels.title}
            </Dialog.Title>
            <IconTooltip label={labels.close ?? labels.cancel}>
              <Dialog.Close
                type="button"
                aria-label={labels.close ?? labels.cancel}
                disabled={pending}
                className="inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-md text-foreground hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50 md:size-8"
              >
                <XIcon className="size-4 shrink-0" aria-hidden="true" />
              </Dialog.Close>
            </IconTooltip>
          </div>
          <Dialog.Description className="text-sm text-muted-foreground">
            {labels.description}
          </Dialog.Description>
          <form
            onSubmit={(event) => {
              event.preventDefault();
              event.stopPropagation();
              void confirm();
            }}
            className="contents space-y-4 [&>:first-child]:mt-5"
          >
            <div className="flex h-64 items-center justify-center overflow-hidden rounded-lg border border-border bg-muted sm:h-72">
              <canvas
                ref={canvas}
                width={
                  validImageCropSize({ width, height })
                    ? Math.max(1, Math.round(560 * Math.min(1, width / height)))
                    : 560
                }
                height={
                  validImageCropSize({ width, height })
                    ? Math.max(1, Math.round(560 * Math.min(1, height / width)))
                    : 315
                }
                // oxlint-disable-next-line jsx-a11y/prefer-tag-over-role -- Canvas is the interactive crop preview, not a static image.
                role="img"
                aria-label={labels.preview}
                className={cn(
                  "max-h-full max-w-full touch-none object-contain",
                  ready ? "cursor-move" : "invisible",
                  pending && "cursor-not-allowed",
                )}
                onPointerDown={(event) => {
                  if (!ready || pending) return;
                  event.currentTarget.setPointerCapture(event.pointerId);
                  drag.current = {
                    x: event.clientX,
                    y: event.clientY,
                    horizontal: position.x,
                    vertical: position.y,
                  };
                }}
                onPointerMove={(event) => {
                  if (!drag.current || !loaded || pending) return;
                  const crop = imageCropRect(
                    { width: loaded.image.naturalWidth, height: loaded.image.naturalHeight },
                    { width, height },
                    position.zoom,
                  );
                  const bounds = event.currentTarget.getBoundingClientRect();
                  const travelX = loaded.image.naturalWidth - crop.width;
                  const travelY = loaded.image.naturalHeight - crop.height;
                  setPosition({
                    ...position,
                    x:
                      travelX > 0
                        ? Math.max(
                            0,
                            Math.min(
                              1,
                              drag.current.horizontal -
                                ((event.clientX - drag.current.x) * crop.width) /
                                  bounds.width /
                                  travelX,
                            ),
                          )
                        : 0.5,
                    y:
                      travelY > 0
                        ? Math.max(
                            0,
                            Math.min(
                              1,
                              drag.current.vertical -
                                ((event.clientY - drag.current.y) * crop.height) /
                                  bounds.height /
                                  travelY,
                            ),
                          )
                        : 0.5,
                  });
                }}
                onLostPointerCapture={() => {
                  drag.current = null;
                }}
              />
            </div>
            <p className="text-sm text-muted-foreground">
              {width} × {height} · WebP
            </p>
            <fieldset disabled={!ready || pending} className="space-y-3">
              {(
                [
                  ["zoom", labels.zoom, 1, 3],
                  ["x", labels.horizontal, 0, 1],
                  ["y", labels.vertical, 0, 1],
                ] as const
              ).map(([key, label, min, max]) => (
                <div key={key} className="space-y-1">
                  <label htmlFor={`${id}-${key}`} className="block text-sm font-medium">
                    {label}
                  </label>
                  <input
                    id={`${id}-${key}`}
                    type="range"
                    min={min}
                    max={max}
                    step={0.01}
                    value={position[key]}
                    onChange={(event) =>
                      setPosition({ ...position, [key]: Number(event.target.value) })
                    }
                    className="block min-h-6 w-full cursor-pointer accent-primary focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50"
                  />
                </div>
              ))}
            </fieldset>
            <div className="min-h-16 text-sm">
              {error ? (
                <p role="alert" className="text-destructive">
                  {labels[error]}
                </p>
              ) : (
                <output className="text-muted-foreground">
                  {pending ? labels.pending : !ready ? labels.loading : ""}
                </output>
              )}
            </div>
            <div
              data-dialog-footer
              className="sticky bottom-0 z-10 -mx-5 flex flex-wrap justify-end gap-2 bg-card px-5 pt-0 pb-5 sm:-mx-6 sm:px-6"
            >
              <Dialog.Close
                type="button"
                disabled={pending}
                className={cn(
                  buttonClass,
                  "border border-border hover:bg-accent hover:text-accent-foreground",
                )}
              >
                {labels.cancel}
              </Dialog.Close>
              <button
                type="submit"
                disabled={!ready || pending}
                className={cn(
                  buttonClass,
                  "bg-primary text-primary-foreground hover:bg-primary/90",
                )}
              >
                {labels.confirm}
              </button>
            </div>
          </form>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

src/components/intranet-sidebar.tsx.text:
"use client";

import { Dialog } from "@base-ui/react/dialog";
import { Menu } from "@base-ui/react/menu";
import {
  ChevronsUpDownIcon,
  Loader2Icon,
  LogOutIcon,
  PanelLeftIcon,
  XIcon,
  SettingsIcon,
} from "lucide-react";
import * as React from "react";

import { IconTooltip } from "#/components/icon-tooltip.tsx";
import { Link } from "#/components/link.tsx";
import { useAuthAction } from "#/components/plugins/auth/auth-controls.tsx";
import {
  SidebarNavigation,
  type SidebarLinkProps,
  type SidebarNavItem,
  type SidebarNavGroup,
} from "#/components/sidebar-navigation.tsx";
import { cn } from "#/components/utils/cn.ts";
import { useSidebarMobile } from "#/components/utils/use-sidebar-mobile.ts";

export type IntranetLinkProps = SidebarLinkProps;
export type IntranetNavItem = SidebarNavItem;
export type IntranetNavGroup = SidebarNavGroup;

export interface IntranetSidebarProps {
  /** Use a compact symbol-only logo; the site name is rendered separately. */
  brand: { name: string; href: string; logo?: React.ReactNode };
  /** Compatible with Better Auth's standard session user fields. */
  user: { name: string; email: string; image?: string | null };
  groups: IntranetNavGroup[];
  pathname: string;
  profileHref: string;
  /** Call Better Auth, throw on result.error, then invalidate the host session. */
  onSignOut: () => Promise<void>;
  linkComponent?: React.ComponentType<IntranetLinkProps>;
  version?: string;
  /** External requires an IntranetSidebarToggle inside the same provider. */
  togglePlacement?: "sidebar" | "external";
  labels?: Partial<typeof defaultLabels>;
  className?: string;
}

const defaultLabels = {
  navigation: "Side navigation",
  toggle: "Toggle side navigation",
  close: "Close side navigation",
  expand: "Expand",
  collapse: "Collapse",
  profile: "Profile settings",
  userMenu: "User menu",
  signOut: "Sign out",
  signingOut: "Signing out…",
  signOutError: "Could not sign out. Please try again.",
};

const focusClassName = "outline-none focus-visible:ring-2 focus-visible:ring-ring";
const sidebarFocusClassName = "outline-none focus-visible:ring-2 focus-visible:ring-sidebar-ring";

type SidebarContextValue = {
  id: string;
  isMobile: boolean;
  open: boolean;
  mobileOpen: boolean;
  setMobileOpen: (open: boolean) => void;
  toggle: () => void;
  triggerRef: React.RefObject<HTMLButtonElement | null>;
};
const SidebarContext = React.createContext<SidebarContextValue | null>(null);

export function useIntranetSidebar() {
  const context = React.useContext(SidebarContext);
  if (!context)
    throw new Error("Use an IntranetSidebarProvider around the sidebar and its toggle.");
  return context;
}

export type IntranetSidebarProviderProps = React.ComponentProps<"div"> & {
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
};

export function IntranetSidebarProvider({
  children,
  defaultOpen = true,
  open: controlledOpen,
  onOpenChange,
  className,
  onFocusCapture,
  ...props
}: IntranetSidebarProviderProps) {
  const [localOpen, setLocalOpen] = React.useState(defaultOpen);
  const [mobileOpen, setMobileOpen] = React.useState(false);
  const isMobile = useSidebarMobile();
  const open = controlledOpen ?? localOpen;
  const id = `factory-intranet-sidebar-${React.useId()}`;
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const sidebarHadFocus = React.useRef(false);
  const toggle = React.useCallback(() => {
    if (isMobile) setMobileOpen((value) => !value);
    else {
      if (controlledOpen === undefined) setLocalOpen(!open);
      onOpenChange?.(!open);
    }
  }, [isMobile, controlledOpen, open, onOpenChange]);

  React.useEffect(() => {
    if (!isMobile && !open && sidebarHadFocus.current) {
      document
        .querySelector<HTMLButtonElement>(`button[aria-controls="${CSS.escape(id)}"]`)
        ?.focus();
    }
  }, [isMobile, open, id]);

  React.useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      const target = event.target;
      if (
        target instanceof HTMLElement &&
        (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName))
      )
        return;
      if (event.key.toLowerCase() === "b" && (event.metaKey || event.ctrlKey) && !event.altKey) {
        event.preventDefault();
        toggle();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [toggle]);

  return (
    <SidebarContext.Provider
      value={{ id, isMobile, open, mobileOpen, setMobileOpen, toggle, triggerRef }}
    >
      <div
        data-slot="sidebar-wrapper"
        className={cn(
          "flex min-h-[calc(100svh-var(--intranet-top-offset,0rem))] w-full",
          className,
        )}
        onFocusCapture={(event) => {
          sidebarHadFocus.current = Boolean(
            event.target.closest('[data-slot="sidebar"], [data-sidebar-profile-menu]'),
          );
          onFocusCapture?.(event);
        }}
        {...props}
      >
        {children}
      </div>
    </SidebarContext.Provider>
  );
}

export type IntranetSidebarToggleProps = React.ComponentProps<"button">;

export function IntranetSidebarToggle({
  className,
  onClick,
  children,
  "aria-label": label = defaultLabels.toggle,
  ...props
}: IntranetSidebarToggleProps) {
  const { id, isMobile, open, mobileOpen, toggle, triggerRef } = useIntranetSidebar();
  return (
    <IconTooltip label={label}>
      <button
        type="button"
        data-sidebar="trigger"
        aria-label={label}
        aria-controls={id}
        aria-expanded={isMobile ? mobileOpen : open}
        className={cn(
          "inline-flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-lg hover:bg-accent disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed print:hidden",
          focusClassName,
          className,
        )}
        onClick={(event) => {
          onClick?.(event);
          if (!event.defaultPrevented) {
            triggerRef.current = event.currentTarget;
            toggle();
          }
        }}
        {...props}
      >
        {children ?? <PanelLeftIcon className="size-4" aria-hidden="true" />}
      </button>
    </IconTooltip>
  );
}

export type IntranetSidebarInsetProps = React.ComponentProps<"main"> & {
  /** Use a div when the host page already supplies its main landmark. */
  as?: "main" | "div";
};
export function IntranetSidebarInset({
  as: Component = "main",
  className,
  ...props
}: IntranetSidebarInsetProps) {
  return React.createElement(Component, {
    "data-slot": "sidebar-inset",
    className: cn("relative flex min-w-0 flex-1 flex-col bg-background", className),
    ...props,
  });
}

function UserAvatar({ user }: Pick<IntranetSidebarProps, "user">) {
  const [failedImage, setFailedImage] = React.useState<string>();
  const initials = (user.name.trim() || user.email)
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0])
    .join("")
    .toUpperCase();
  return (
    <span className="flex size-8 shrink-0 items-center justify-center overflow-hidden rounded-full bg-muted text-xs leading-none font-medium text-foreground">
      {user.image && user.image !== failedImage ? (
        <img
          src={user.image}
          alt=""
          className="size-full object-cover"
          onError={() => setFailedImage(user.image ?? undefined)}
        />
      ) : (
        initials
      )}
    </span>
  );
}

export function IntranetSidebar({
  brand,
  user,
  groups,
  pathname,
  profileHref,
  onSignOut,
  linkComponent: LinkComponent = Link,
  version,
  togglePlacement = "sidebar",
  labels: overrides,
  className,
}: IntranetSidebarProps) {
  const { id, open, isMobile, mobileOpen, setMobileOpen, triggerRef } = useIntranetSidebar();
  const labels = { ...defaultLabels, ...overrides };
  const signOutAction = useAuthAction();
  const { pending: signingOut, failed: signOutFailed } = signOutAction;
  const closeMobile = () => setMobileOpen(false);

  const content = (
    <>
      <header
        className={cn(
          "flex h-12 shrink-0 items-center px-4",
          (togglePlacement === "sidebar" || isMobile) && "pr-12",
        )}
      >
        <LinkComponent
          href={brand.href}
          className={cn("flex min-w-0 items-center gap-2 rounded-sm", sidebarFocusClassName)}
          onClick={closeMobile}
        >
          {brand.logo && (
            <span
              aria-hidden="true"
              className="flex size-7 shrink-0 items-center justify-center [&>img]:size-full [&>img]:object-contain [&>svg]:size-full"
            >
              {brand.logo}
            </span>
          )}
          <span className="truncate text-base font-semibold" title={brand.name}>
            {brand.name}
          </span>
        </LinkComponent>
      </header>
      <div className="mx-2 border-t border-sidebar-border" />
      <SidebarNavigation
        groups={groups}
        pathname={pathname}
        linkComponent={LinkComponent}
        onNavigate={closeMobile}
        label={labels.navigation}
        labels={labels}
      />
      {version && <p className="px-2 py-1 text-center text-xs text-muted-foreground">{version}</p>}
      <div className="mx-2 border-t border-sidebar-border" />
      <footer className="shrink-0 p-2">
        {signOutFailed && (
          <p role="alert" className="px-2 pb-2 text-sm text-destructive">
            {labels.signOutError}
          </p>
        )}
        <Menu.Root key={open ? "expanded" : "collapsed"}>
          <Menu.Trigger
            aria-label={labels.userMenu}
            className={cn(
              "flex w-full cursor-pointer items-center gap-2 rounded-lg px-2 py-2 text-left hover:bg-sidebar-accent hover:text-sidebar-accent-foreground disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed",
              sidebarFocusClassName,
            )}
          >
            <UserAvatar user={user} />
            <span className="flex min-w-0 flex-1 flex-col">
              <span className="truncate text-sm font-medium">{user.name || user.email}</span>
              <span className="truncate text-xs text-muted-foreground">{user.email}</span>
            </span>
            {signingOut ? (
              <Loader2Icon className="size-4 animate-spin" aria-hidden="true" />
            ) : (
              <ChevronsUpDownIcon className="size-4 shrink-0 opacity-50" aria-hidden="true" />
            )}
          </Menu.Trigger>
          <Menu.Portal>
            <Menu.Positioner side="top" align="start" sideOffset={8} className="z-50">
              <Menu.Popup
                data-sidebar-profile-menu=""
                className="min-w-56 rounded-lg border border-border bg-popover p-1 text-popover-foreground shadow-lg outline-none"
              >
                <Menu.Item
                  render={<LinkComponent href={profileHref} />}
                  onClick={closeMobile}
                  className={cn(
                    "flex cursor-pointer items-center gap-2 rounded-md px-2 py-2 text-sm data-disabled:cursor-not-allowed data-highlighted:bg-accent",
                    focusClassName,
                  )}
                >
                  <SettingsIcon className="size-4" aria-hidden="true" />
                  {labels.profile}
                </Menu.Item>
                <Menu.Separator className="my-1 border-t border-border" />
                <Menu.Item
                  disabled={signOutAction.disabled}
                  onClick={() => void signOutAction.run(onSignOut)}
                  className={cn(
                    "flex cursor-pointer items-center gap-2 rounded-md px-2 py-2 text-sm data-disabled:cursor-not-allowed data-disabled:opacity-50 data-highlighted:bg-accent",
                    focusClassName,
                  )}
                >
                  <LogOutIcon className="size-4" aria-hidden="true" />
                  {signingOut ? labels.signingOut : labels.signOut}
                </Menu.Item>
              </Menu.Popup>
            </Menu.Positioner>
          </Menu.Portal>
        </Menu.Root>
        <output className="sr-only">{signingOut ? labels.signingOut : ""}</output>
      </footer>
    </>
  );

  return (
    <>
      {togglePlacement === "sidebar" && (
        <IntranetSidebarToggle
          aria-label={labels.toggle}
          className={cn(
            "fixed top-[calc(var(--intranet-top-offset,0rem)+0.5rem)] left-2 z-30 border border-sidebar-border bg-sidebar text-sidebar-foreground shadow-sm hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-sidebar-ring",
            !isMobile && open && "left-[13.5rem]",
          )}
        />
      )}
      {isMobile ? (
        <Dialog.Root open={mobileOpen} onOpenChange={setMobileOpen}>
          <Dialog.Portal>
            <Dialog.Backdrop className="fixed inset-0 z-40 bg-foreground/40 print:hidden" />
            <Dialog.Popup
              id={id}
              finalFocus={() =>
                triggerRef.current ??
                document.querySelector<HTMLButtonElement>(
                  `button[aria-controls="${CSS.escape(id)}"]`,
                )
              }
              aria-describedby={undefined}
              data-slot="sidebar"
              className={cn(
                "fixed inset-y-0 left-0 z-50 flex h-dvh w-72 max-w-[calc(100vw-2rem)] flex-col border-r border-sidebar-border bg-sidebar text-sidebar-foreground outline-none print:hidden",
                className,
              )}
            >
              <Dialog.Title className="sr-only">{labels.navigation}</Dialog.Title>
              <IconTooltip label={labels.close}>
                <Dialog.Close
                  aria-label={labels.close}
                  className={cn(
                    "absolute top-2 right-2 flex size-8 cursor-pointer items-center justify-center rounded-lg hover:bg-sidebar-accent hover:text-sidebar-accent-foreground disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed",
                    sidebarFocusClassName,
                  )}
                >
                  <XIcon className="size-4" aria-hidden="true" />
                </Dialog.Close>
              </IconTooltip>
              {content}
            </Dialog.Popup>
          </Dialog.Portal>
        </Dialog.Root>
      ) : (
        <div
          className={cn(
            "hidden shrink-0 transition-[width] duration-200 motion-reduce:transition-none md:block print:hidden",
            open ? "w-64" : "w-0",
          )}
        >
          <aside
            id={id}
            aria-label={labels.navigation}
            inert={!open}
            data-slot="sidebar"
            data-state={open ? "expanded" : "collapsed"}
            className={cn(
              "fixed top-[var(--intranet-top-offset,0rem)] bottom-0 left-0 z-20 flex h-[calc(100svh-var(--intranet-top-offset,0rem))] w-64 flex-col border-r border-sidebar-border bg-sidebar text-sidebar-foreground transition-transform duration-200 motion-reduce:transition-none",
              !open && "invisible -translate-x-full",
              className,
            )}
          >
            {content}
          </aside>
        </div>
      )}
    </>
  );
}

