"use client";

import type { ReactNode } from "react";

import {
  IntranetSidebar,
  IntranetSidebarInset,
  IntranetSidebarProvider,
  IntranetSidebarToggle,
  type IntranetSidebarProps,
  useIntranetSidebar,
} from "#/components/intranet-sidebar.tsx";
import { cn } from "#/components/utils/cn.ts";

function ShellSidebarToggle({ label }: { label?: string }) {
  const { isMobile, open } = useIntranetSidebar();

  return (
    <IntranetSidebarToggle
      aria-label={label}
      className={cn(
        !isMobile &&
          open &&
          "fixed top-[calc(var(--intranet-top-offset,0rem)+0.5rem)] left-[13.5rem] z-30 border border-sidebar-border bg-sidebar text-sidebar-foreground shadow-sm hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-sidebar-ring",
      )}
    />
  );
}

export interface IntranetShellProps extends Omit<
  IntranetSidebarProps,
  "togglePlacement" | "className"
> {
  /** Full banner content; the host owns its colors and spacing. */
  banner?: ReactNode;
  topbar?: ReactNode;
  /** Place the supplied toggle in your navbar; it moves beside the brand when expanded. */
  renderTopbar?: (toggle: ReactNode) => ReactNode;
  controls?: ReactNode;
  children?: ReactNode;
  /** Hide the topbar and keep the sidebar's standalone toggle available. */
  showTopbar?: boolean;
  className?: string;
  contentClassName?: string;
  sidebarClassName?: string;
  /** Use div when the page already provides its main landmark. */
  insetAs?: "main" | "div";
  /** Disable the content wrapper when the host owns page spacing and print layout. */
  wrapContent?: boolean;
}

export function IntranetShell({
  banner,
  topbar,
  renderTopbar,
  controls,
  children,
  showTopbar = true,
  className,
  contentClassName,
  sidebarClassName,
  insetAs = "main",
  wrapContent = true,
  ...sidebarProps
}: IntranetShellProps) {
  const toggle = <ShellSidebarToggle label={sidebarProps.labels?.toggle} />;

  return (
    <IntranetSidebarProvider>
      <IntranetSidebar
        {...sidebarProps}
        className={cn(showTopbar && "[&>header]:pr-12", sidebarClassName)}
        togglePlacement={showTopbar ? "external" : "sidebar"}
      />
      <IntranetSidebarInset
        as={insetAs}
        className={cn(!showTopbar && "pt-12 print:pt-0", className)}
      >
        {banner && <div className="print:hidden">{banner}</div>}
        {showTopbar &&
          (renderTopbar ? (
            renderTopbar(toggle)
          ) : (
            <header className="flex min-h-14 items-center gap-2 border-b border-border px-4 py-2 print:hidden">
              {toggle}
              <div className="flex min-w-0 flex-1 items-center gap-2">
                {topbar ?? (
                  <span className="truncate text-sm font-medium">{sidebarProps.brand.name}</span>
                )}
              </div>
              {controls && <div className="ml-auto flex items-center gap-2">{controls}</div>}
            </header>
          ))}
        {wrapContent ? (
          <div
            data-slot="intranet-content"
            className={cn("flex-1 p-4 sm:p-6 print:p-0", contentClassName)}
          >
            {children}
          </div>
        ) : (
          children
        )}
      </IntranetSidebarInset>
    </IntranetSidebarProvider>
  );
}

src/components/utils/consent-analytics.t.text:
export interface AnalyticsConsent {
  analytics: boolean;
  marketing: boolean;
}

export interface ConsentAnalyticsOptions {
  measurementId?: string;
  adsId?: string;
  adsConversionLabel?: string;
  nonce?: string;
  /** Optional host script manager. Resolve only when the script is ready; reject on failure. */
  loadScript?: (url: string) => Promise<void>;
}

export interface ConsentAnalytics {
  /** Connect to CookieBanner.onConsentChange; catch failures in the host. Calling again retries. */
  updateConsent: (consent: AnalyticsConsent) => Promise<void>;
  /** Events before consent or before a successful load are discarded, never replayed later. */
  trackEvent: (name: string, parameters?: Record<string, unknown>) => boolean;
  trackAdsConversion: (action: string) => boolean;
}

declare global {
  interface Window {
    gtag?: (...args: unknown[]) => void;
    dataLayer?: object[];
    __forgeGoogleConsent?: AnalyticsConsent;
    [key: `ga-disable-${string}`]: boolean | undefined;
  }
}

const denied: AnalyticsConsent = { analytics: false, marketing: false };
function googleConsent(consent: AnalyticsConsent) {
  return {
    ad_storage: consent.marketing ? "granted" : "denied",
    analytics_storage: consent.analytics ? "granted" : "denied",
    ad_user_data: consent.marketing ? "granted" : "denied",
    ad_personalization: consent.marketing ? "granted" : "denied",
  };
}

/** Sets Consent Mode v2 defaults and choices without loading scripts or making requests. */
export function applyGoogleConsent(consent: AnalyticsConsent): void {
  if (typeof window === "undefined") return;
  window.dataLayer ??= [];
  window.gtag ??= function () {
    // The Google tag queue uses Arguments objects, as in Google's installation snippet.
    window.dataLayer!.push(arguments);
  };
  const previous = window.__forgeGoogleConsent;
  if (!previous) window.gtag("consent", "default", googleConsent(denied));
  if (
    !previous ||
    previous.analytics !== consent.analytics ||
    previous.marketing !== consent.marketing
  ) {
    window.gtag("consent", "update", googleConsent(consent));
    window.__forgeGoogleConsent = { ...consent };
  }
}

function insertScript(url: string, nonce?: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.async = true;
    script.src = url;
    script.dataset.forgeAnalytics = "";
    if (nonce) script.nonce = nonce;
    const timer = setTimeout(() => finish(new Error("Google tag loading timed out.")), 30_000);
    function finish(error?: Error) {
      clearTimeout(timer);
      script.onload = null;
      script.onerror = null;
      if (error) {
        script.remove();
        reject(error);
      } else resolve();
    }
    script.onload = () => finish();
    script.onerror = () => finish(new Error("Could not load the Google tag."));
    document.head.appendChild(script);
  });
}

/** Create once in a host module. Construction and calls during SSR have no browser effects. */
export function createConsentAnalytics(options: ConsentAnalyticsOptions = {}): ConsentAnalytics {
  const measurementId = options.measurementId?.trim();
  const adsId = options.adsId?.trim();
  const conversionLabel = options.adsConversionLabel?.trim().replace(/^\/+/, "");
  if (measurementId && !/^G-[A-Z0-9]+$/.test(measurementId))
    throw new Error("Expected a GA4 measurement ID starting with G-.");
  if (adsId && !/^AW-\d+$/.test(adsId))
    throw new Error("Expected a Google Ads ID starting with AW-.");
  let consent = denied;
  let loading: Promise<void> | undefined;
  let ready = false;
  let initialized = false;
  const configured = new Set<string>();

  function configure() {
    for (const id of [consent.analytics && measurementId, consent.marketing && adsId]) {
      if (id && !configured.has(id)) {
        // Explicit event destinations keep analytics events out of the Ads destination.
        window.gtag?.("config", id);
        configured.add(id);
      }
    }
  }

  return {
    async updateConsent(next) {
      if (typeof window === "undefined") return;
      consent = { analytics: next.analytics === true, marketing: next.marketing === true };
      if (measurementId) window[`ga-disable-${measurementId}`] = !consent.analytics;
      applyGoogleConsent(consent);
      const id = (consent.analytics && measurementId) || (consent.marketing && adsId);
      if (!id) return;
      if (ready) {
        configure();
        return;
      }
      if (!loading) {
        if (!initialized) {
          window.gtag?.("js", new Date());
          initialized = true;
        }
        loading = Promise.resolve()
          .then(async () => {
            const currentId = (consent.analytics && measurementId) || (consent.marketing && adsId);
            if (!currentId) return;
            const url = `https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(currentId)}`;
            const load = options.loadScript ?? ((src: string) => insertScript(src, options.nonce));
            await load(url);
            ready = true;
          })
          .finally(() => {
            loading = undefined;
          });
      }
      await loading;
      // Consent may have changed while the script was loading.
      if (ready) configure();
    },
    trackEvent(name, parameters = {}) {
      if (
        typeof window === "undefined" ||
        !window.__forgeGoogleConsent?.analytics ||
        !consent.analytics ||
        !ready ||
        !measurementId ||
        !configured.has(measurementId)
      )
        return false;
      window.gtag?.("event", name, { ...parameters, send_to: measurementId });
      return true;
    },
    trackAdsConversion(action) {
      if (
        typeof window === "undefined" ||
        !window.__forgeGoogleConsent?.marketing ||
        !consent.marketing ||
        !ready ||
        !adsId ||
        !conversionLabel ||
        !configured.has(adsId)
      )
        return false;
      window.gtag?.("event", "conversion", {
        send_to: `${adsId}/${conversionLabel}`,
        event_category: "engagement",
        event_label: action,
      });
      return true;
    },
  };
}

src/components/forge/forms/newsletter.ts.text:
"use client";

import * as React from "react";

import { cn } from "#/intranet/forge/utils.ts";

export type NewsletterProps = Omit<React.ComponentPropsWithoutRef<"section">, "onSubmit"> & {
  title?: string;
  description?: string;
  eyebrow?: string;
  placeholder?: string;
  buttonLabel?: string;
  privacyText?: string;
  loading?: boolean;
  successMessage?: string;
  errorMessage?: string;
  disabled?: boolean;
  icon?: React.ReactNode;
  validationErrorMessage?: string;
  submitErrorMessage?: string;
  emailLabel?: string;
  loadingLabel?: string;
  onSubmit: (email: string) => void | Promise<void>;
};

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function Newsletter({
  title = "Stay in the loop",
  description = "Get product updates and practical tips delivered to your inbox.",
  eyebrow,
  placeholder = "you@example.com",
  buttonLabel = "Subscribe",
  privacyText,
  loading = false,
  successMessage,
  errorMessage,
  disabled = false,
  icon,
  validationErrorMessage = "Please enter a valid email address.",
  submitErrorMessage = "Could not subscribe. Please try again.",
  emailLabel = "Email address",
  loadingLabel = "Subscribing…",
  onSubmit,
  className,
  ...props
}: NewsletterProps) {
  const baseId = `factory-newsletter-${React.useId()}`;
  const inputId = `${baseId}-email`;
  const helperId = `${baseId}-helper`;
  const errorId = `${baseId}-error`;
  const successId = `${baseId}-success`;

  const [email, setEmail] = React.useState("");
  const [validationError, setValidationError] = React.useState<string>();
  const [submitError, setSubmitError] = React.useState<string>();
  const [showStatus, setShowStatus] = React.useState(true);
  const [submitting, setSubmitting] = React.useState(false);

  const hasError = Boolean(validationError || submitError || (showStatus && errorMessage));
  const inlineError = validationError || submitError || (showStatus ? errorMessage : undefined);
  const inlineSuccess = !inlineError && showStatus ? successMessage : undefined;
  const isLoading = loading || submitting;
  const isDisabled = disabled || isLoading;

  const describedBy = [privacyText ? helperId : undefined, inlineError ? errorId : undefined]
    .filter(Boolean)
    .join(" ");

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (isDisabled) {
      return;
    }

    const normalizedEmail = email.trim();

    if (!EMAIL_REGEX.test(normalizedEmail)) {
      setShowStatus(false);
      setValidationError(validationErrorMessage);
      return;
    }

    setShowStatus(true);
    setValidationError(undefined);
    setSubmitError(undefined);

    try {
      setSubmitting(true);
      await Promise.resolve(onSubmit(normalizedEmail));
    } catch {
      setSubmitError(submitErrorMessage);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <section
      className={cn(
        "w-full rounded-xl border border-border bg-background p-5 shadow-sm sm:p-6",
        className,
      )}
      {...props}
    >
      <div className="space-y-2">
        {eyebrow ? (
          <p className="font-eyebrow text-xs font-semibold tracking-[0.14em] text-primary uppercase">
            {eyebrow}
          </p>
        ) : null}
        <div className="flex items-center gap-2">
          {icon ? <span className="text-muted-foreground">{icon}</span> : null}
          <h2 className="text-lg font-semibold text-foreground">{title}</h2>
        </div>
        <p className="text-sm text-muted-foreground">{description}</p>
      </div>

      <form className="mt-4" onSubmit={handleSubmit} noValidate>
        <label className="mb-2 block text-sm font-medium" htmlFor={inputId}>
          {emailLabel}
        </label>
        <div className="flex flex-col gap-3 sm:flex-row">
          <input
            id={inputId}
            type="email"
            name="email"
            autoComplete="email"
            value={email}
            onChange={(event) => {
              setEmail(event.target.value);
              setValidationError(undefined);
              setSubmitError(undefined);
              setShowStatus(false);
            }}
            placeholder={placeholder}
            disabled={isDisabled}
            aria-invalid={hasError}
            aria-describedby={describedBy || undefined}
            className="h-11 w-full rounded-lg border border-input bg-background px-3 text-base text-foreground placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-60 md:text-sm"
          />
          <button
            type="submit"
            disabled={isDisabled}
            className="inline-flex h-11 shrink-0 cursor-pointer items-center justify-center rounded-lg bg-primary px-4 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-60 aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed"
          >
            {isLoading ? loadingLabel : buttonLabel}
          </button>
        </div>

        {privacyText ? (
          <p className="mt-3 text-xs text-muted-foreground" id={helperId}>
            {privacyText}
          </p>
        ) : null}

        {inlineError ? (
          <p
            className="mt-2 text-sm text-destructive"
            id={errorId}
            role="alert"
            aria-live="assertive"
          >
            {inlineError}
          </p>
        ) : null}

        {inlineSuccess ? (
          <output
            className="mt-2 block rounded-lg bg-status-success px-3 py-2 text-sm text-status-success-foreground"
            id={successId}
            aria-live="polite"
          >
            {inlineSuccess}
          </output>
        ) : null}
      </form>
    </section>
  );
}

src/components/forge/layouts/cookie-bann.text:
"use client";

import { XIcon } from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";

import { IconTooltip } from "#/intranet/components/forge/icon-tooltip.tsx";
import { cn } from "#/intranet/forge/utils.ts";
import { applyGoogleConsent } from "#/components/utils/consent-analytics.ts";

export interface ConsentState {
  necessary: boolean;
  analytics: boolean;
  marketing: boolean;
}

const DEFAULT_CONSENT: ConsentState = {
  necessary: true,
  analytics: false,
  marketing: false,
};

function deserialize(raw: string): ConsentState | null {
  try {
    const parsed = JSON.parse(raw);
    if (
      typeof parsed === "object" &&
      parsed !== null &&
      typeof parsed.analytics === "boolean" &&
      typeof parsed.marketing === "boolean"
    ) {
      return {
        necessary: true,
        analytics: parsed.analytics,
        marketing: parsed.marketing,
      };
    }
    return null;
  } catch {
    return null;
  }
}

export interface CookieBannerProps {
  consentKey?: string;
  manageEvent?: string;
  text: string;
  acceptAllLabel: string;
  acceptSelectionLabel: string;
  cancelLabel?: string;
  closeLabel?: string;
  confirmLabel?: string;
  policyLabel: string;
  privacyHref: string;
  necessaryTitle?: string;
  necessaryDescription?: string;
  analyticsTitle?: string;
  analyticsDescription?: string;
  marketingTitle?: string;
  marketingDescription?: string;
  showAnalytics?: boolean;
  showMarketing?: boolean;
  dialogLabel?: string;
  hidden?: boolean;
  /** Called after consent updates on hydration, save, and cross-tab changes, never for draft edits.
   * Keep this callback idempotent; load tracking scripts only for granted categories.
   */
  onConsentChange?: (consent: ConsentState) => void;
}

function readConsent(key: string): ConsentState | null {
  try {
    const stored = localStorage.getItem(key);
    return stored ? deserialize(stored) : null;
  } catch {
    // Storage can be unavailable; consent still works for this mounted page.
    return null;
  }
}

export function CookieBanner({
  consentKey = "cookie-consent",
  manageEvent = "manage-cookies",
  text,
  acceptAllLabel,
  acceptSelectionLabel,
  cancelLabel = "Cancel",
  closeLabel = "Close",
  confirmLabel = "Confirm selection",
  policyLabel,
  privacyHref,
  necessaryTitle = "Necessary",
  necessaryDescription = "Required for the website to function properly.",
  analyticsTitle = "Statistics",
  analyticsDescription = "Helps us understand how visitors interact with the site.",
  marketingTitle = "Marketing",
  marketingDescription = "Measures conversions and personalizes advertising.",
  showAnalytics = true,
  showMarketing = false,
  dialogLabel = "Cookies",
  hidden = false,
  onConsentChange,
}: CookieBannerProps) {
  const [visible, setVisible] = useState(false);
  const [customizing, setCustomizing] = useState(false);
  const [draft, setDraft] = useState(DEFAULT_CONSENT);
  const savedConsent = useRef(DEFAULT_CONSENT);
  const consentCallback = useRef(onConsentChange);

  useEffect(() => {
    consentCallback.current = onConsentChange;
  }, [onConsentChange]);

  const normalizeConsent = useCallback(
    (state: ConsentState): ConsentState => ({
      necessary: true,
      analytics: showAnalytics && state.analytics,
      marketing: showMarketing && state.marketing,
    }),
    [showAnalytics, showMarketing],
  );

  const notifyConsent = useCallback((state: ConsentState) => {
    savedConsent.current = state;
    applyGoogleConsent(state);
    consentCallback.current?.({ ...state });
  }, []);

  const evaluate = useCallback(() => {
    const stored = readConsent(consentKey);
    const state = normalizeConsent(stored ?? DEFAULT_CONSENT);
    setDraft(state);
    setCustomizing(false);
    setVisible(stored === null);
    notifyConsent(state);
  }, [consentKey, normalizeConsent, notifyConsent]);

  useEffect(() => {
    // oxlint-disable-next-line react/set-state-in-effect -- hydrate saved consent and listen for external changes
    evaluate();
    const onStorage = (event: StorageEvent) => {
      if (event.key === consentKey || event.key === null) evaluate();
    };
    const onManage = () => {
      setDraft(normalizeConsent(readConsent(consentKey) ?? savedConsent.current));
      setCustomizing(false);
      setVisible(true);
    };
    window.addEventListener("storage", onStorage);
    window.addEventListener(manageEvent, onManage);
    return () => {
      window.removeEventListener("storage", onStorage);
      window.removeEventListener(manageEvent, onManage);
    };
  }, [evaluate, consentKey, manageEvent, normalizeConsent]);

  const saveConsent = (selection: ConsentState) => {
    const state = normalizeConsent(selection);
    try {
      localStorage.setItem(consentKey, JSON.stringify(state));
    } catch {
      // Retain the choice in memory when persistence is blocked.
    }
    setDraft(state);
    setCustomizing(false);
    setVisible(false);
    notifyConsent(state);
  };

  const cancelSelection = () => {
    setDraft(savedConsent.current);
    setCustomizing(false);
  };

  if (hidden || !visible) return null;

  return (
    <dialog
      id="factory-cookie-banner"
      open
      aria-label={dialogLabel}
      aria-live="polite"
      className={cn(
        "fixed inset-x-0 top-auto bottom-0 z-[60] m-0 w-full max-w-none border-0 bg-transparent p-4 sm:p-6",
        "animate-in duration-300 fade-in slide-in-from-bottom-4",
      )}
    >
      <div className="container-premium">
        <div
          className={cn(
            "relative flex flex-col gap-3 rounded-xl border border-border bg-background px-4 py-3 pr-16 shadow-lg",
            !customizing && "sm:flex-row sm:items-center",
          )}
        >
          <IconTooltip label={closeLabel}>
            <button
              type="button"
              aria-label={closeLabel}
              className="absolute top-3 right-3 inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-md text-foreground hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50 md:size-8"
              onClick={() => {
                cancelSelection();
                setVisible(false);
              }}
            >
              <XIcon className="size-4 shrink-0" aria-hidden="true" />
            </button>
          </IconTooltip>
          <p className="min-w-0 flex-1 text-sm leading-relaxed text-foreground">
            {text}{" "}
            <a
              href={privacyHref}
              className="font-semibold text-primary underline underline-offset-2"
            >
              {policyLabel}
            </a>
          </p>

          {customizing && (
            <div className="grid gap-3 border-t border-border pt-3 sm:grid-cols-3">
              <label
                aria-label={necessaryTitle}
                className="flex cursor-not-allowed items-start gap-3 opacity-70"
              >
                <input
                  type="checkbox"
                  checked
                  disabled
                  className="mt-0.5 size-4 shrink-0 rounded accent-primary"
                />
                <span>
                  <span className="block text-sm font-semibold text-foreground">
                    {necessaryTitle}
                  </span>
                  <span className="block text-xs text-muted-foreground">
                    {necessaryDescription}
                  </span>
                </span>
              </label>

              {showAnalytics && (
                <label
                  aria-label={analyticsTitle}
                  className="flex cursor-pointer items-start gap-3"
                >
                  <input
                    type="checkbox"
                    checked={draft.analytics}
                    onChange={(event) =>
                      setDraft((state) => ({
                        ...state,
                        analytics: event.target.checked,
                      }))
                    }
                    className="mt-0.5 size-4 shrink-0 rounded accent-primary"
                  />
                  <span>
                    <span className="block text-sm font-semibold text-foreground">
                      {analyticsTitle}
                    </span>
                    <span className="block text-xs text-muted-foreground">
                      {analyticsDescription}
                    </span>
                  </span>
                </label>
              )}

              {showMarketing && (
                <label
                  aria-label={marketingTitle}
                  className="flex cursor-pointer items-start gap-3"
                >
                  <input
                    type="checkbox"
                    checked={draft.marketing}
                    onChange={(event) =>
                      setDraft((state) => ({
                        ...state,
                        marketing: event.target.checked,
                      }))
                    }
                    className="mt-0.5 size-4 shrink-0 rounded accent-primary"
                  />
                  <span>
                    <span className="block text-sm font-semibold text-foreground">
                      {marketingTitle}
                    </span>
                    <span className="block text-xs text-muted-foreground">
                      {marketingDescription}
                    </span>
                  </span>
                </label>
              )}
            </div>
          )}

          <div className="flex shrink-0 flex-wrap items-center justify-end gap-2">
            <button
              type="button"
              onClick={customizing ? cancelSelection : () => setCustomizing(true)}
              aria-expanded={customizing}
              className="inline-flex h-10 cursor-pointer items-center justify-center rounded-lg border border-border bg-background px-4 text-sm font-semibold text-foreground transition-colors outline-none hover:bg-muted focus-visible:ring-3 focus-visible:ring-ring/40 disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed"
            >
              {customizing ? cancelLabel : acceptSelectionLabel}
            </button>
            <button
              type="button"
              onClick={() =>
                saveConsent(
                  customizing ? draft : { necessary: true, analytics: true, marketing: true },
                )
              }
              className="inline-flex h-10 cursor-pointer items-center justify-center rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground transition-colors outline-none hover:bg-primary/90 focus-visible:ring-3 focus-visible:ring-primary/40 disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed"
            >
              {customizing ? confirmLabel : acceptAllLabel}
            </button>
          </div>
        </div>
      </div>
    </dialog>
  );
}

src/intranet/components/forge/sidebar-na.text:
"use client";

import { Collapsible } from "@base-ui/react/collapsible";
import { ChevronDownIcon } from "lucide-react";
import * as React from "react";

import { IconTooltip } from "#/intranet/components/forge/icon-tooltip.tsx";
import { Link } from "#/intranet/components/forge/ui/link.tsx";
import { cn } from "#/intranet/forge/utils.ts";
import { itemIsActive } from "#/intranet/components/forge/navigation/intranet-sidebar-active.ts";

export type SidebarLinkProps = React.ComponentProps<"a"> & { href: string };
type NavItemBase = {
  id: string;
  label: string;
  icon?: React.ReactNode;
  /** Non-interactive status or count, with its accessible description supplied by the host. */
  badge?: React.ReactNode;
  onNavigate?: () => void;
};
export type SidebarNavItem = NavItemBase &
  (
    | {
        href: string;
        exact?: boolean;
        items?: never;
        collapsible?: never;
        onSelect?: never;
        active?: never;
      }
    | {
        items: SidebarNavItem[];
        collapsible?: boolean;
        href?: string;
        exact?: boolean;
        onSelect?: never;
        active?: never;
      }
    | {
        onSelect: () => void;
        active: boolean;
        href?: never;
        exact?: never;
        items?: never;
        collapsible?: never;
      }
  );

export interface SidebarNavGroup {
  id: string;
  label?: string;
  items: SidebarNavItem[];
  footer?: React.ReactNode | ((onNavigate: () => void) => React.ReactNode);
}

export interface SidebarNavigationProps {
  groups: SidebarNavGroup[];
  pathname?: string;
  linkComponent?: React.ComponentType<SidebarLinkProps>;
  onNavigate?: () => void;
  label?: string;
  labels?: { expand?: string; collapse?: string };
  className?: string;
}

const sidebarFocusClassName = "outline-none focus-visible:ring-2 focus-visible:ring-sidebar-ring";
export const sidebarNavItemClass = `relative flex min-h-10 w-full cursor-pointer items-center gap-2 rounded-none border-l-2 border-transparent px-2 py-1.5 text-sm text-sidebar-foreground transition-colors disabled:cursor-not-allowed disabled:opacity-50 md:min-h-8 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground ${sidebarFocusClassName}`;
export const sidebarNavActiveClass =
  "rounded-l-none border-sidebar-primary bg-sidebar-accent/40 font-semibold text-sidebar-primary";

function NavigationItem({
  item,
  pathname,
  LinkComponent,
  closeMobile,
  labels,
  nested = false,
}: {
  item: SidebarNavItem;
  pathname: string;
  LinkComponent: React.ComponentType<SidebarLinkProps>;
  closeMobile: () => void;
  labels: { expand: string; collapse: string };
  nested?: boolean;
}) {
  const active = itemIsActive(item, pathname);
  const [expansion, setExpansion] = React.useState({ pathname, open: active });
  if (expansion.pathname !== pathname) setExpansion({ pathname, open: expansion.open || active });
  const expanded = expansion.open;
  const itemClasses = cn(
    nested && "-ml-[9px] w-[calc(100%+9px)] rounded-l-none bg-clip-padding pl-[17px]",
    active && sidebarNavActiveClass,
  );
  const childList = Boolean(item.items?.length) && (
    <ul className="ml-4 space-y-0.5 border-l border-sidebar-border px-2 py-1">
      {item.items?.map((child) => (
        <NavigationItem
          key={child.id}
          item={child}
          nested
          pathname={pathname}
          LinkComponent={LinkComponent}
          closeMobile={closeMobile}
          labels={labels}
        />
      ))}
    </ul>
  );
  const label = (
    <>
      {item.icon && (
        <span className="shrink-0 [&>svg]:size-4" aria-hidden="true">
          {item.icon}
        </span>
      )}
      <span className="min-w-0 flex-1 text-left wrap-anywhere">{item.label}</span>
      {item.badge != null && <span className="shrink-0">{item.badge}</span>}
    </>
  );
  const link = item.onSelect ? (
    <button
      type="button"
      aria-current={active ? "page" : undefined}
      className={cn(sidebarNavItemClass, itemClasses)}
      onClick={() => {
        item.onSelect?.();
        closeMobile();
      }}
    >
      {label}
    </button>
  ) : (
    item.href && (
      <LinkComponent
        href={item.href}
        aria-current={
          (item.items ? itemIsActive({ href: item.href, exact: true }, pathname) : active)
            ? "page"
            : undefined
        }
        className={cn(sidebarNavItemClass, "min-w-0 flex-1", itemClasses)}
        onClick={(event) => {
          if (
            !event.defaultPrevented &&
            event.button === 0 &&
            !event.metaKey &&
            !event.ctrlKey &&
            !event.shiftKey &&
            !event.altKey
          ) {
            item.onNavigate?.();
            closeMobile();
          }
        }}
      >
        {label}
      </LinkComponent>
    )
  );

  if (!childList) return link ? <li>{link}</li> : null;
  if (item.collapsible === false)
    return (
      <li>
        {link || (
          <p className="flex items-center gap-2 px-2 pt-2 text-xs font-medium text-muted-foreground uppercase">
            {label}
          </p>
        )}
        {childList}
      </li>
    );

  const chevron = (
    <ChevronDownIcon
      className={cn(
        "size-4 shrink-0 transition-transform motion-reduce:transition-none",
        expanded && "rotate-180",
      )}
      aria-hidden="true"
    />
  );
  return (
    <li>
      <Collapsible.Root open={expanded} onOpenChange={(open) => setExpansion({ pathname, open })}>
        {link ? (
          <div className="flex items-center gap-1">
            {link}
            <IconTooltip label={`${expanded ? labels.collapse : labels.expand} ${item.label}`}>
              <Collapsible.Trigger
                aria-label={`${expanded ? labels.collapse : labels.expand} ${item.label}`}
                className={cn(
                  "flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-lg hover:bg-sidebar-accent hover:text-sidebar-accent-foreground disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed",
                  sidebarFocusClassName,
                )}
              >
                {chevron}
              </Collapsible.Trigger>
            </IconTooltip>
          </div>
        ) : (
          <Collapsible.Trigger className={cn(sidebarNavItemClass, itemClasses)}>
            {label}
            {chevron}
          </Collapsible.Trigger>
        )}
        <Collapsible.Panel>{childList}</Collapsible.Panel>
      </Collapsible.Root>
    </li>
  );
}

export function SidebarNavigation({
  groups,
  pathname = "",
  linkComponent: LinkComponent = Link,
  onNavigate,
  label = "Side navigation",
  labels: overrides,
  className,
}: SidebarNavigationProps) {
  const labels = { expand: "Expand", collapse: "Collapse", ...overrides };
  return (
    <nav aria-label={label} className={cn("min-h-0 flex-1 overflow-y-auto py-2", className)}>
      {groups
        .filter((group) => group.items.length > 0 || group.footer)
        .map((group) => (
          <section key={group.id} aria-label={group.label} className="px-2 py-2">
            {group.label && (
              <h2 className="px-2 pb-2 text-xs font-semibold text-muted-foreground">
                {group.label}
              </h2>
            )}
            <ul className="space-y-0.5">
              {group.items.map((item) => (
                <NavigationItem
                  key={item.id}
                  item={item}
                  pathname={pathname}
                  LinkComponent={LinkComponent}
                  closeMobile={() => onNavigate?.()}
                  labels={labels}
                />
              ))}
            </ul>
            {typeof group.footer === "function" ? group.footer(() => onNavigate?.()) : group.footer}
          </section>
        ))}
    </nav>
  );
}

