        <IconTooltip label={nextLabel}>
          <button
            type="button"
            className={buttonClass}
            disabled={disabled || nextDisabled}
            onClick={onNext}
            aria-label={nextLabel}
          >
            <ChevronRightIcon
              className="size-4 shrink-0 motion-safe:transition-transform motion-safe:duration-150 motion-safe:group-[:enabled:focus-visible]/pagination:translate-x-0.5 motion-safe:group-[:enabled:hover]/pagination:translate-x-0.5"
              aria-hidden="true"
            />
          </button>
        </IconTooltip>
      </div>
    </nav>
  );
}

src/intranet/components/forge/table-sele.text:
"use client";

import { Dialog } from "@base-ui/react/dialog";
import { XIcon, Trash2Icon } from "lucide-react";
import { useCallback, useEffect, useLayoutEffect, useRef, useState, type ReactNode } from "react";

import { useActionToast } from "#/intranet/components/forge/action-toast.tsx";
import { IconTooltip } from "#/intranet/components/forge/icon-tooltip.tsx";
import { cn } from "#/intranet/forge/utils.ts";
import {
  tableSelectionLabels,
  type TableSelectionLabels,
} from "#/intranet/components/forge/utils/table-selection-labels.ts";
import { useOptimisticAction } from "#/intranet/components/forge/utils/use-optimistic-action.ts";
export type { TableSelectionLabels } from "#/intranet/components/forge/utils/table-selection-labels";

export interface TableDeletionOptions<T> {
  onDelete: (item: T, requestId: string) => Promise<unknown>;
  prepare?: (items: readonly T[]) => Promise<ReactNode>;
  onComplete?: (count: number) => void;
}
interface DeletionSession<T> {
  scope: string;
  options: TableDeletionOptions<T>;
  entries: { item: T; requestId: string }[];
  phase: "preparing" | "ready" | "deleting";
  ready: boolean;
  details?: ReactNode;
  failure?: { stage: "prepare" | "delete"; cause: unknown };
  attempted: number;
}

export function useTableSelection<T extends { id: string }>(items: readonly T[], scope = "") {
  const [state, setState] = useState({ ids: [] as string[], scope });
  const [session, setSession] = useState<DeletionSession<T> | null>(null);
  const active = useRef<DeletionSession<T> | null>(null);
  const requestPending = useRef(false);
  const mounted = useRef(true);
  const currentScope = useRef(scope);
  const optimistic = useOptimisticAction<string | undefined>(undefined, scope);
  const dispose = useCallback(() => {
    active.current = null;
    if (mounted.current) setSession(null);
  }, []);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      active.current = null;
    };
  }, []);
  useLayoutEffect(() => {
    currentScope.current = scope;
    if (active.current && active.current.scope !== scope && active.current.attempted === 0)
      dispose();
  }, [scope, dispose]);
  const selected = items.filter((item) => state.scope === scope && state.ids.includes(item.id));
  if (state.scope !== scope || selected.length !== state.ids.length) {
    setState({ ids: selected.map((item) => item.id), scope });
  }
  const visible = session && (session.scope === scope || session.attempted > 0) ? session : null;
  const pending = (!!visible && visible.phase !== "ready") || optimistic.pending;
  const current = (target: DeletionSession<T>) => mounted.current && active.current === target;
  const busy = () =>
    requestPending.current || (!!active.current && active.current.phase !== "ready");
  const publish = (target: DeletionSession<T>) => {
    if (current(target)) setSession({ ...target });
  };
  async function prepare(target: DeletionSession<T>, options: TableDeletionOptions<T>) {
    target.phase = "preparing";
    target.ready = false;
    target.details = undefined;
    publish(target);
    try {
      const details = await options.prepare?.(target.entries.map(({ item }) => item));
      if (!current(target)) return;
      target.details = details;
      target.ready = true;
    } catch (cause) {
      if (!current(target)) return;
      target.failure = { stage: "prepare", cause };
    }
    target.phase = "ready";
    publish(target);
  }
  async function confirm(provided: TableDeletionOptions<T>) {
    const target = active.current;
    if (!target || busy()) return;
    const options = target.scope === currentScope.current ? provided : target.options;
    target.options = options;
    target.failure = undefined;
    if (!target.ready) return prepare(target, options);
    target.phase = "deleting";
    const entries = target.entries;
    target.attempted = entries.length;
    publish(target);
    const failed: typeof entries = [];
    let reason: unknown;
    for (const entry of entries) {
      if (!current(target)) return;
      try {
        requestPending.current = true;
        await optimistic.run(
          () => entry.item.id,
          () => options.onDelete(entry.item, entry.requestId),
        );
        if (current(target))
          setState((previous) =>
            previous.scope === target.scope
              ? { ...previous, ids: previous.ids.filter((id) => id !== entry.item.id) }
              : previous,
          );
      } catch (error) {
        failed.push(entry);
        reason = error;
      } finally {
        requestPending.current = false;
      }
    }
    if (!current(target)) return;
    if (!failed.length) {
      dispose();
      options.onComplete?.(entries.length);
    } else {
      target.entries = failed;
      target.failure = { stage: "delete", cause: reason };
      await prepare(target, options);
    }
  }
  return {
    selected,
    scope,
    pending,
    isDeleting: (id: string) =>
      visible?.scope === scope && optimistic.pending && optimistic.value === id,
    deletion: {
      items: visible?.entries.map(({ item }) => item) ?? [],
      details: visible?.details,
      ready: visible?.ready ?? false,
      failure: visible?.failure,
      attempted: visible?.attempted ?? 0,
      open(options: TableDeletionOptions<T>, targets: readonly T[] = selected) {
        if (busy() || !targets.length) return;
        const target: DeletionSession<T> = {
          scope,
          options,
          entries: targets.map((item) => ({ item, requestId: crypto.randomUUID() })),
          phase: "preparing",
          ready: false,
          attempted: 0,
        };
        active.current = target;
        void prepare(target, options);
      },
      confirm,
      close() {
        if (!busy()) dispose();
      },
      /** A dialog can unmount while its table remains mounted. */
      dispose,
    },
    all: items.length > 0 && selected.length === items.length,
    mixed: selected.length > 0 && selected.length < items.length,
    toggleAll: (checked: boolean) => {
      if (!busy()) setState({ ids: checked ? items.map((item) => item.id) : [], scope });
    },
    toggle: (id: string, checked: boolean) => {
      if (busy()) return;
      setState((current) => ({
        scope,
        ids: checked
          ? [...current.ids.filter((value) => value !== id), id]
          : current.ids.filter((value) => value !== id),
      }));
    },
  };
}

export interface TableSelectionCheckboxProps {
  label: string;
  checked: boolean;
  mixed?: boolean;
  disabled?: boolean;
  onChange: (checked: boolean) => void;
}
export function TableSelectionCheckbox({
  label,
  checked,
  mixed = false,
  disabled,
  onChange,
}: TableSelectionCheckboxProps) {
  return (
    <label className="inline-flex size-10 items-center justify-center md:size-8">
      <input
        type="checkbox"
        aria-label={label}
        checked={checked}
        ref={(input) => {
          if (input) input.indeterminate = mixed;
        }}
        disabled={disabled}
        onChange={(event) => onChange(event.target.checked)}
        className="size-4 cursor-pointer accent-primary focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50"
      />
    </label>
  );
}

const buttonClass =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-md border border-border px-3 text-sm font-medium outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 md:min-h-8";
const destructiveClass =
  "border-transparent bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30";

export interface TableBulkDeleteProps<T extends { id: string }> {
  selection: ReturnType<typeof useTableSelection<T>>;
  getName: (item: T) => string;
  onDelete: (item: T, requestId: string) => Promise<unknown>;
  /** Fetch and display any server-owned deletion preview before allowing confirmation. */
  prepare?: (items: readonly T[]) => Promise<ReactNode>;
  errorMessage?: (error: unknown) => string;
  description?: ReactNode;
  labels?: Partial<TableSelectionLabels>;
  disabled?: boolean;
}
export function TableBulkDelete<T extends { id: string }>({
  selection,
  getName,
  onDelete,
  prepare,
  errorMessage,
  description,
  labels: overrides,
  disabled,
}: TableBulkDeleteProps<T>) {
  const labels = { ...tableSelectionLabels, ...overrides };
  const { deletion } = selection;
  useEffect(() => deletion.dispose, [deletion.dispose]);
  const notify = useActionToast();
  const options: TableDeletionOptions<T> = {
    onDelete,
    prepare,
    onComplete: () => {
      if (labels.bulkDeleted) notify(labels.bulkDeleted);
    },
  };
  const failure = deletion.failure
    ? (errorMessage?.(deletion.failure.cause) ??
      (deletion.failure.stage === "prepare" ? labels.bulkPrepareError : labels.bulkDeleteError))
    : "";
  const actionLabel = `${labels.deleteSelected} (${selection.selected.length})`;
  const actionDisabled = disabled || selection.pending || selection.selected.length === 0;
  return (
    <>
      <div className="size-10 shrink-0 md:size-8">
        <IconTooltip label={actionLabel}>
          <button
            type="button"
            aria-label={actionLabel}
            className={cn(
              buttonClass,
              actionDisabled
                ? "bg-background text-foreground disabled:hover:bg-background"
                : destructiveClass,
              "size-10 p-0 md:size-8",
            )}
            disabled={actionDisabled}
            onClick={() => {
              if (!actionDisabled) deletion.open(options);
            }}
          >
            <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
          </button>
        </IconTooltip>
      </div>
      <Dialog.Root
        open={deletion.items.length > 0}
        onOpenChange={(open) => {
          if (!open) deletion.close();
        }}
      >
        <Dialog.Portal>
          <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
          <Dialog.Popup className="fixed top-1/2 left-1/2 z-50 grid max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 scroll-py-32 gap-4 overflow-y-auto rounded-xl border border-border bg-popover px-6 text-popover-foreground shadow-xl">
            <div
              data-dialog-header
              className="sticky top-0 z-20 -mx-6 space-y-2 bg-popover px-6 pt-5 pb-0"
            >
              <div className="flex items-start justify-between gap-3">
                <Dialog.Title className="min-w-0 flex-1 text-lg font-semibold break-words">
                  {labels.bulkDeleteTitle}
                </Dialog.Title>
                <IconTooltip label={labels.bulkClose ?? labels.bulkCancel}>
                  <Dialog.Close
                    type="button"
                    aria-label={labels.bulkClose ?? labels.bulkCancel}
                    disabled={selection.pending}
                    className={cn(buttonClass, "size-10 shrink-0 p-0 md:size-8")}
                  >
                    <XIcon className="size-4 shrink-0" aria-hidden="true" />
                  </Dialog.Close>
                </IconTooltip>
              </div>
              <Dialog.Description className="text-sm text-muted-foreground">
                {description ?? labels.bulkDeleteDescription}
              </Dialog.Description>
            </div>
            <ul className="max-h-48 list-inside list-disc overflow-y-auto text-sm">
              {deletion.items.map((item) => (
                <li key={item.id} className="break-words">
                  {getName(item)}
                </li>
              ))}
            </ul>
            {prepare && (
              <div
                className="h-32 overflow-y-auto"
                aria-busy={selection.pending && !deletion.ready}
              >
                {deletion.details ??
                  (selection.pending && (
                    <output className="block text-sm text-muted-foreground">
                      {labels.bulkPending}
                    </output>
                  ))}
              </div>
            )}
            <div className="h-10 overflow-y-auto text-sm text-destructive">
              {failure && <p role="alert">{failure}</p>}
            </div>
            <div
              data-dialog-footer
              className="sticky bottom-0 z-10 -mx-6 flex flex-wrap justify-end gap-2 bg-popover px-6 pt-0 pb-5"
            >
              <Dialog.Close className={buttonClass} disabled={selection.pending}>
                {labels.bulkCancel}
              </Dialog.Close>
              <button
                type="button"
                className={cn(buttonClass, destructiveClass)}
                disabled={disabled || selection.pending}
                onClick={() => {
                  if (!disabled) void deletion.confirm(options);
                }}
              >
                {selection.pending
                  ? labels.bulkPending
                  : deletion.ready
                    ? labels.bulkConfirm
                    : labels.bulkRetry}
              </button>
            </div>
          </Dialog.Popup>
        </Dialog.Portal>
      </Dialog.Root>
    </>
  );
}

src/intranet/components/forge/image-crop.text:
"use client";

import { Dialog } from "@base-ui/react/dialog";
import { XIcon } from "lucide-react";
import { useEffect, useId, useRef, useState } from "react";

import { IconTooltip } from "#/intranet/components/forge/icon-tooltip.tsx";
import { cn } from "#/intranet/forge/utils.ts";
import {
  exportImageCrop,
  imageCropRect,
  validImageCropSize,
  type ImageCropSize,
} from "#/intranet/components/forge/utils/crop-image.ts";
import { submitDialogOnShortcut } from "#/intranet/components/forge/utils/dialog-submit.ts";

export type { ImageCropSize } from "#/intranet/components/forge/utils/crop-image";

const defaultLabels = {
  title: "Crop image",
  description: "Drag the image or use the sliders to frame it. Confirm to create a WebP image.",
  preview: "Crop preview",
  zoom: "Zoom",
  horizontal: "Horizontal position",
  vertical: "Vertical position",
  cancel: "Cancel",
  close: "Close",
  confirm: "Use image",
  loading: "Loading image…",
  pending: "Preparing image…",
  invalid: "Choose a JPEG, PNG or WebP image within the upload size limit.",
  dimensions: "The requested image dimensions are invalid or too large.",
  decodeError: "This image could not be opened or is too large. Choose another image.",
  saveError: "The image could not be prepared or uploaded. Try again, or choose another image.",
};
export type ImageCropLabels = Omit<typeof defaultLabels, "close"> & { close?: string };

export interface ImageCropDialogProps extends ImageCropSize {
  file: File | null;
  onConfirm: (file: File) => void | Promise<void>;
  onCancel: () => void;
  labels?: Partial<ImageCropLabels>;
  maxFileBytes?: number;
  className?: string;
}

const buttonClass =
  "inline-flex min-h-10 cursor-pointer items-center justify-center rounded-md px-3 text-sm font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50 md:min-h-8";

export function ImageCropDialog(props: ImageCropDialogProps) {
  return props.file ? <CropSession {...props} file={props.file} /> : null;
}

function CropSession({
  file,
  width,
  height,
  onConfirm,
  onCancel,
  labels: overrides,
  maxFileBytes = 10 * 1024 * 1024,
  className,
}: ImageCropDialogProps & { file: File }) {
  const labels = { ...defaultLabels, ...overrides };
  const id = `factory-image-crop-${useId()}`;
  const canvas = useRef<HTMLCanvasElement>(null);
  const lock = useRef(false);
  const drag = useRef<{ x: number; y: number; horizontal: number; vertical: number } | null>(null);
  const [loaded, setLoaded] = useState<{ file: File; image: HTMLImageElement } | null>(null);
  const [position, setPosition] = useState({ zoom: 1, x: 0.5, y: 0.5 });
  const prepared = useRef<{
    source: File;
    width: number;
    height: number;
    position: typeof position;
    file: File;
  } | null>(null);
  const [error, setError] = useState<keyof ImageCropLabels | null>(null);
  const [pending, setPending] = useState(false);
  const ready = loaded?.file === file && validImageCropSize({ width, height });

  useEffect(() => {
    let canceled = false;
    let url: string | undefined;
    const image = new Image();
    void Promise.resolve()
      .then(() => {
        if (canceled) return;
        setLoaded(null);
        setError(null);
        setPosition({ zoom: 1, x: 0.5, y: 0.5 });
        if (!validImageCropSize({ width, height })) {
          setError("dimensions");
          return;
        }
        if (
          !file.size ||
          !Number.isFinite(maxFileBytes) ||
          maxFileBytes <= 0 ||
          file.size > maxFileBytes ||
          !["image/jpeg", "image/png", "image/webp"].includes(file.type)
        ) {
          setError("invalid");
          return;
        }
        image.onload = () => {
          if (canceled) return;
          if (
            !image.naturalWidth ||
            !image.naturalHeight ||
            image.naturalWidth * image.naturalHeight > 40_000_000
          ) {
            setError("decodeError");
            return;
          }
          setLoaded({ file, image });
        };
        image.onerror = () => {
          if (!canceled) setError("decodeError");
        };
        url = URL.createObjectURL(file);
        image.src = url;
      })
      .catch(() => {
        if (!canceled) setError("decodeError");
      });
    return () => {
      canceled = true;
      image.onload = null;
      image.onerror = null;
      if (url) URL.revokeObjectURL(url);
    };
  }, [file, width, height, maxFileBytes]);

  useEffect(() => {
    if (!ready || !loaded || !canvas.current) return;
    const context = canvas.current.getContext("2d");
    if (!context) return;
    const crop = imageCropRect(
      { width: loaded.image.naturalWidth, height: loaded.image.naturalHeight },
      { width, height },
      position.zoom,
      position.x,
      position.y,
    );
    context.clearRect(0, 0, canvas.current.width, canvas.current.height);
    context.drawImage(
      loaded.image,
      crop.x,
      crop.y,
      crop.width,
      crop.height,
      0,
      0,
      canvas.current.width,
      canvas.current.height,
    );
  }, [loaded, ready, width, height, position]);

  async function confirm() {
    if (!ready || !loaded || lock.current) return;
    lock.current = true;
    setPending(true);
    setError(null);
    try {
      // Reuse the same File on retry so host upload idempotency keys stay stable.
      const cached = prepared.current;
      const result =
        cached?.source === file &&
        cached.width === width &&
        cached.height === height &&
        cached.position === position
          ? cached.file
          : await exportImageCrop(
              loaded.image,
              file,
              { width, height },
              position.zoom,
              position.x,
              position.y,
            );
      prepared.current = { source: file, width, height, position, file: result };
      if (result.size > maxFileBytes) throw new Error("Image exceeds upload limit");
      await onConfirm(result);
    } catch {
      setError("saveError");
    } finally {
      lock.current = false;
      setPending(false);
    }
  }

  return (
    <Dialog.Root
      open
      onOpenChange={(open) => {
        if (!open && !lock.current) onCancel();
      }}
    >
      <Dialog.Portal>
        {/* Notifications from a previous upload must not cover the active crop editor. */}
        <Dialog.Backdrop className="fixed inset-0 z-70 bg-foreground/30" />
        <Dialog.Popup
          className={cn(
            "fixed top-1/2 left-1/2 z-70 max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-xl -translate-x-1/2 -translate-y-1/2 scroll-py-32 overflow-y-auto rounded-xl bg-card px-5 text-card-foreground shadow-xl sm:px-6",
            className,
          )}
          onKeyDown={submitDialogOnShortcut}
        >
          <div
            data-dialog-header
            className="sticky top-0 z-20 -mx-5 mb-0 flex items-start justify-between gap-3 bg-card px-5 pt-5 pb-2 sm:-mx-6 sm:px-6"
          >
            <Dialog.Title className="min-w-0 flex-1 text-lg font-semibold break-words">
              {labels.title}
            </Dialog.Title>
            <IconTooltip label={labels.close ?? labels.cancel}>
              <Dialog.Close
                type="button"
                aria-label={labels.close ?? labels.cancel}
                disabled={pending}
                className="inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-md text-foreground hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50 md:size-8"
              >
                <XIcon className="size-4 shrink-0" aria-hidden="true" />
              </Dialog.Close>
            </IconTooltip>
          </div>
          <Dialog.Description className="text-sm text-muted-foreground">
            {labels.description}
          </Dialog.Description>
          <form
            onSubmit={(event) => {
              event.preventDefault();
              event.stopPropagation();
              void confirm();
            }}
            className="contents space-y-4 [&>:first-child]:mt-5"
          >
            <div className="flex h-64 items-center justify-center overflow-hidden rounded-lg border border-border bg-muted sm:h-72">
              <canvas
                ref={canvas}
                width={
                  validImageCropSize({ width, height })
                    ? Math.max(1, Math.round(560 * Math.min(1, width / height)))
                    : 560
                }
                height={
                  validImageCropSize({ width, height })
                    ? Math.max(1, Math.round(560 * Math.min(1, height / width)))
                    : 315
                }
                // oxlint-disable-next-line jsx-a11y/prefer-tag-over-role -- Canvas is the interactive crop preview, not a static image.
                role="img"
                aria-label={labels.preview}
                className={cn(
                  "max-h-full max-w-full touch-none object-contain",
                  ready ? "cursor-move" : "invisible",
                  pending && "cursor-not-allowed",
                )}
                onPointerDown={(event) => {
                  if (!ready || pending) return;
                  event.currentTarget.setPointerCapture(event.pointerId);
                  drag.current = {
                    x: event.clientX,
                    y: event.clientY,
                    horizontal: position.x,
                    vertical: position.y,
                  };
                }}
                onPointerMove={(event) => {
                  if (!drag.current || !loaded || pending) return;
                  const crop = imageCropRect(
                    { width: loaded.image.naturalWidth, height: loaded.image.naturalHeight },
                    { width, height },
                    position.zoom,
                  );
                  const bounds = event.currentTarget.getBoundingClientRect();
                  const travelX = loaded.image.naturalWidth - crop.width;
                  const travelY = loaded.image.naturalHeight - crop.height;
                  setPosition({
                    ...position,
                    x:
                      travelX > 0
                        ? Math.max(
                            0,
                            Math.min(
                              1,
                              drag.current.horizontal -
                                ((event.clientX - drag.current.x) * crop.width) /
                                  bounds.width /
                                  travelX,
                            ),
                          )
                        : 0.5,
                    y:
                      travelY > 0
                        ? Math.max(
                            0,
                            Math.min(
                              1,
                              drag.current.vertical -
                                ((event.clientY - drag.current.y) * crop.height) /
                                  bounds.height /
                                  travelY,
                            ),
                          )
                        : 0.5,
                  });
                }}
                onLostPointerCapture={() => {
                  drag.current = null;
                }}
              />
            </div>
            <p className="text-sm text-muted-foreground">
              {width} × {height} · WebP
            </p>
            <fieldset disabled={!ready || pending} className="space-y-3">
              {(
                [
                  ["zoom", labels.zoom, 1, 3],
                  ["x", labels.horizontal, 0, 1],
                  ["y", labels.vertical, 0, 1],
                ] as const
              ).map(([key, label, min, max]) => (
                <div key={key} className="space-y-1">
                  <label htmlFor={`${id}-${key}`} className="block text-sm font-medium">
                    {label}
                  </label>
                  <input
                    id={`${id}-${key}`}
                    type="range"
                    min={min}
                    max={max}
                    step={0.01}
                    value={position[key]}
                    onChange={(event) =>
                      setPosition({ ...position, [key]: Number(event.target.value) })
                    }
                    className="block min-h-6 w-full cursor-pointer accent-primary focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50"
                  />
                </div>
              ))}
            </fieldset>
            <div className="min-h-16 text-sm">
              {error ? (
                <p role="alert" className="text-destructive">
                  {labels[error]}
                </p>
              ) : (
                <output className="text-muted-foreground">
                  {pending ? labels.pending : !ready ? labels.loading : ""}
                </output>
              )}
            </div>
            <div
              data-dialog-footer
              className="sticky bottom-0 z-10 -mx-5 flex flex-wrap justify-end gap-2 bg-card px-5 pt-0 pb-5 sm:-mx-6 sm:px-6"
            >
              <Dialog.Close
                type="button"
                disabled={pending}
                className={cn(
                  buttonClass,
                  "border border-border hover:bg-accent hover:text-accent-foreground",
                )}
              >
                {labels.cancel}
              </Dialog.Close>
              <button
                type="submit"
                disabled={!ready || pending}
                className={cn(
                  buttonClass,
                  "bg-primary text-primary-foreground hover:bg-primary/90",
                )}
              >
                {labels.confirm}
              </button>
            </div>
          </form>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

