"use client";

import {
  ArrowBigUpDashIcon,
  ArrowRightIcon,
  EyeIcon,
  EyeOffIcon,
  LoaderCircleIcon,
} from "lucide-react";
import { useEffect, useId, useRef, useState, type ComponentType } from "react";

import { ActionToastProvider, useActionToast } from "#/intranet/components/forge/action-toast.tsx";
import { IconTooltip } from "#/intranet/components/forge/icon-tooltip.tsx";
import { Link, type LinkProps } from "#/intranet/components/forge/ui/link.tsx";
import { GoogleSignInButton, useAuthAction } from "#/intranet/components/forge/plugins/auth/auth-controls.tsx";
import { loginLabels, type LoginLabels } from "#/intranet/components/forge/plugins/auth/labels.ts";
import { cn } from "#/intranet/forge/utils.ts";

export {
  GoogleSignInButton,
  SignOutButton,
  useAuthAction,
  type AuthControlProps,
} from "#/intranet/components/forge/plugins/auth/auth-controls";
export type { LoginLabels } from "#/intranet/components/forge/plugins/auth/labels";
export {
  AuthLayout,
  type AuthLayoutProps,
  type AuthLayoutLabels,
} from "#/intranet/components/forge/plugins/auth/auth-layout";
export {
  ForgotPasswordForm,
  ResetPasswordForm,
  ChangePasswordForm,
  ChangePasswordPage,
  type ForgotPasswordFormProps,
  type ResetPasswordFormProps,
  type ChangePasswordFormProps,
  type ChangePasswordPageProps,
  type ChangePasswordValues,
} from "#/intranet/components/forge/plugins/auth/password-forms";
export type { PasswordLabels } from "#/intranet/components/forge/plugins/auth/password-labels";
export {
  AccessDeniedPage,
  type AccessDeniedPageProps,
  type AccessDeniedLabels,
} from "#/intranet/components/forge/plugins/auth/access-denied-page";
export {
  AccountEmailChange,
  emailChangeLabels,
  type AccountEmailChangeProps,
} from "#/intranet/components/forge/plugins/auth/account-email-change";
export {
  AccountPage,
  type AccountPageProps,
  type AccountTab,
} from "#/intranet/components/forge/plugins/auth/account-page";
export {
  AccountSecurity,
  type AccountSecurityData,
  type AccountSecurityProps,
} from "#/intranet/components/forge/plugins/auth/account-security";
export {
  AgentKeys,
  type AgentKey,
  type AgentKeysProps,
} from "#/intranet/components/forge/plugins/auth/agent-keys";
export type { AccountLabels, SecurityLabels } from "#/intranet/components/forge/plugins/auth/account-labels";
export interface LoginCredentials {
  email: string;
  password: string;
  rememberMe: boolean;
}
export interface LoginFormProps {
  onSignIn: (credentials: LoginCredentials) => Promise<void>;
  defaultEmail?: string;
  verificationStatus?: "success" | "error";
  enabled?: boolean;
  forgotPasswordHref?: string;
  onGoogleSignIn?: () => Promise<void>;
  labels?: Partial<LoginLabels>;
  className?: string;
  linkComponent?: ComponentType<LinkProps>;
}
const inputClass =
  "h-12 w-full rounded-lg border border-input bg-transparent px-3 text-base shadow-xs outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50 md:text-sm";
const buttonClass =
  "inline-flex h-12 w-full items-center justify-center gap-2 rounded-lg text-sm font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-4 cursor-pointer disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed";

export function LoginForm(props: LoginFormProps) {
  return (
    <ActionToastProvider>
      <LoginFormContent {...props} />
    </ActionToastProvider>
  );
}

function LoginFormContent({
  onSignIn,
  defaultEmail,
  verificationStatus,
  enabled = true,
  forgotPasswordHref,
  onGoogleSignIn,
  labels: overrides,
  className,
  linkComponent: LoginLink = Link,
}: LoginFormProps) {
  const labels = { ...loginLabels, ...overrides };
  const toast = useActionToast();
  const verificationNotified = useRef(false);
  useEffect(() => {
    if (verificationStatus !== "success" || verificationNotified.current) return;
    verificationNotified.current = true;
    toast(labels.emailVerified);
  }, [verificationStatus, labels.emailVerified, toast]);
  const id = `factory-login-${useId()}`;
  const [showPassword, setShowPassword] = useState(false);
  const [capsLock, setCapsLock] = useState(false);
  const action = useAuthAction();
  const [method, setMethod] = useState<"password" | "google">("password");
  const { pending, failed } = action;
  const googlePending = pending && method === "google";
  return (
    <div className={cn("flex flex-col gap-7", className)}>
      <div>
        <p className="mb-3 text-xs font-semibold tracking-widest text-primary! uppercase">
          {labels.teamSpace}
        </p>
        <h1 className="text-3xl font-semibold tracking-tight text-foreground sm:text-4xl">
          {labels.welcomeBack}
        </h1>
        <p className="mt-3 text-sm leading-relaxed text-muted-foreground!">
          {labels.welcomeSubtitle}
        </p>
      </div>

      {!enabled && (
        <output className="rounded-xl border border-border bg-muted/50 p-4 text-sm">
          {labels.unavailable}
        </output>
      )}

      {verificationStatus === "error" && (
        <p role="alert" className="text-sm text-destructive">
          {labels.verificationError}
        </p>
      )}
      {failed && (
        <p id={`${id}-error`} role="alert" className="text-sm text-destructive">
          {method === "google" ? labels.googleError : labels.loginError}
        </p>
      )}
      <form
        onSubmit={(event) => {
          event.preventDefault();
          const data = new FormData(event.currentTarget);
          const email = data.get("email");
          const password = data.get("password");
          if (typeof email !== "string" || typeof password !== "string") return;
          if (!enabled) return;
          void action.run(async () => {
            setMethod("password");
            await onSignIn({
              email: email.trim(),
              password,
              rememberMe: data.get("rememberMe") === "on",
            });
            setShowPassword(false);
          });
        }}
        className="grid gap-5"
        aria-busy={pending}
      >
        <div className="grid gap-2">
          <label htmlFor={`${id}-email`}>{labels.email}</label>
          <input
            id={`${id}-email`}
            name="email"
            type="email"
            defaultValue={defaultEmail}
            autoComplete="username"
            autoCapitalize="none"
            spellCheck={false}
            placeholder="name@example.com"
            className={inputClass}
            readOnly={action.disabled}
            disabled={!enabled}
            aria-describedby={failed ? `${id}-error` : undefined}
            required
          />
        </div>
        <div className="grid gap-2">
          <label htmlFor={`${id}-password`}>{labels.password}</label>
          <div className="relative">
            <input
              id={`${id}-password`}
              name="password"
              type={showPassword ? "text" : "password"}
              autoComplete="current-password"
              autoCapitalize="none"
              spellCheck={false}
              className={cn(inputClass, capsLock ? "pr-20" : "pr-12")}
              onKeyDown={(event) => setCapsLock(event.getModifierState("CapsLock"))}
              onKeyUp={(event) => setCapsLock(event.getModifierState("CapsLock"))}
              onClick={(event) => setCapsLock(event.getModifierState("CapsLock"))}
              onBlur={() => setCapsLock(false)}
              readOnly={action.disabled}
              disabled={!enabled}
              aria-describedby={
                [failed && `${id}-error`, capsLock && `${id}-caps-lock`]
                  .filter(Boolean)
                  .join(" ") || undefined
              }
              required
            />
            <output
              id={`${id}-caps-lock`}
              htmlFor={`${id}-password`}
              title={capsLock ? labels.capsLockOn : undefined}
              className="absolute inset-y-0 right-12 flex items-center text-primary"
            >
              {capsLock && (
                <>
                  <ArrowBigUpDashIcon className="mx-2 size-4" aria-hidden="true" />
                  <span className="sr-only">{labels.capsLockOn}</span>
                </>
              )}
            </output>
            <IconTooltip label={showPassword ? labels.hidePassword : labels.showPassword}>
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                disabled={action.disabled || !enabled}
                aria-label={showPassword ? labels.hidePassword : labels.showPassword}
                aria-controls={`${id}-password`}
                aria-pressed={showPassword}
                className="absolute inset-y-0 right-0 flex w-12 cursor-pointer items-center justify-center rounded-lg text-muted-foreground! hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed"
              >
                {showPassword ? (
                  <EyeOffIcon className="size-4" aria-hidden="true" />
                ) : (
                  <EyeIcon className="size-4" aria-hidden="true" />
                )}
              </button>
            </IconTooltip>
          </div>
        </div>
        <div className="flex flex-wrap items-center justify-between gap-3 text-sm">
          <label className="flex cursor-pointer items-center gap-2 text-muted-foreground!">
            <input
              type="checkbox"
              name="rememberMe"
              defaultChecked
              className="size-4 accent-primary"
              disabled={action.disabled || !enabled}
            />
            {labels.rememberMe}
          </label>
          {forgotPasswordHref && (
            <LoginLink
              href={forgotPasswordHref}
              className="font-medium text-primary hover:underline"
            >
              {labels.forgotPassword}
            </LoginLink>
          )}
        </div>
        <button
          type="submit"
          className={cn(buttonClass, "bg-primary text-primary-foreground hover:bg-primary/90")}
          disabled={action.disabled || !enabled}
        >
          {pending && !googlePending ? <LoaderCircleIcon className="animate-spin" /> : null}
          {pending && !googlePending ? labels.signingIn : labels.signIn}
          {!pending && <ArrowRightIcon className="size-4" />}
        </button>
      </form>

      {onGoogleSignIn && (
        <>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <span className="h-px flex-1 bg-border" />
            {labels.orDivider}
            <span className="h-px flex-1 bg-border" />
          </div>
          <GoogleSignInButton
            className="w-full"
            label={labels.continueGoogle}
            pendingLabel={labels.connectingGoogle}
            pending={googlePending}
            disabled={action.disabled || !enabled}
            onClick={() =>
              void action.run(async () => {
                setMethod("google");
                await onGoogleSignIn();
              })
            }
          />
        </>
      )}
      <p className="border-t border-border pt-6 text-sm leading-relaxed text-muted-foreground!">
        {labels.contactAdmin}
      </p>
    </div>
  );
}

"use client";

import { LogOutIcon, RefreshCwIcon } from "lucide-react";
import { useRef, useState, type ReactNode } from "react";

import { useLoadingActivity } from "#/intranet/components/forge/loading-indicator.tsx";
import { securityLabels, type SecurityLabels } from "#/intranet/components/forge/plugins/auth/account-labels.ts";
import {
  accountButtonClass,
  accountCardClass,
  accountDate,
} from "#/intranet/components/forge/plugins/auth/account-styles.ts";
import { passwordLabels, type PasswordLabels } from "#/intranet/components/forge/plugins/auth/password-labels.ts";
import { cn } from "#/intranet/forge/utils.ts";

export interface AccountSecurityData {
  signInMethod: string | null;
  providers: string[];
  sessions: {
    id: string;
    current: boolean;
    userAgent?: string | null;
    ipAddress?: string | null;
    createdAt: Date | string;
    expiresAt: Date | string;
  }[];
}
export interface AccountSecurityProps {
  email: string;
  data?: AccountSecurityData;
  loading?: boolean;
  error?: boolean;
  onRetry: () => void;
  onRequestPasswordReset?: () => Promise<void>;
  onRevokeSession: (id: string) => Promise<void>;
  agentKeys?: ReactNode;
  /** The host's ChangePasswordForm adapter, shown only for a credential account. */
  passwordForm?: ReactNode;
  labels?: Partial<SecurityLabels>;
  passwordLabels?: Partial<PasswordLabels>;
  locale?: string;
  className?: string;
}
export function AccountSecurity({
  email,
  data,
  loading = false,
  error = false,
  onRetry,
  onRequestPasswordReset,
  onRevokeSession,
  agentKeys,
  passwordForm,
  labels: overrides,
  passwordLabels: passwordOverrides,
  locale,
  className,
}: AccountSecurityProps) {
  useLoadingActivity(loading);
  const labels = { ...securityLabels, ...overrides };
  const passwords = { ...passwordLabels, ...passwordOverrides };
  const [reset, setReset] = useState<"idle" | "pending" | "success" | "error">("idle");
  const [revoking, setRevoking] = useState<string | null>(null);
  const [revokeFailed, setRevokeFailed] = useState(false);
  const resetLock = useRef(false);
  const revokeLock = useRef(false);
  const providerName = (provider: string) =>
    provider === "credential"
      ? labels.emailPassword
      : provider === "github"
        ? "GitHub"
        : provider === "google"
          ? "Google"
          : provider;
  return (
    <div className={cn("grid min-w-0 gap-6", className)}>
      {agentKeys}
      <section className={accountCardClass}>
        <h2 className="font-semibold">{labels.signInMethods}</h2>
        <div className="mt-4 min-h-24 space-y-4" aria-busy={loading}>
          {error && (
            <div role="alert" className="space-y-3">
              <p>{labels.securityError}</p>
              <button
                type="button"
                className={accountButtonClass}
                disabled={loading}
                onClick={onRetry}
              >
                <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
                {labels.retry}
              </button>
            </div>
          )}
          {!data ? (
            !error && <output>{labels.loadingSecurity}</output>
          ) : (
            <>
              <p className="text-muted-foreground">
                {data.signInMethod
                  ? `${labels.signedInWith} ${providerName(data.signInMethod)}`
                  : labels.unknownMethod}
              </p>
              <ul className="divide-y divide-border">
                {data.providers.map((provider) => (
                  <li
                    key={provider}
                    className="flex flex-wrap items-center justify-between gap-4 py-3"
                  >
                    <div>
                      <p className="font-medium">{providerName(provider)}</p>
                      <p className="text-sm text-muted-foreground">
                        {provider === "credential" ? email : labels.connected}
                      </p>
                    </div>
                    {provider === "credential" && onRequestPasswordReset && (
                      <button
                        type="button"
                        className={accountButtonClass}
                        disabled={error || reset === "pending" || reset === "success"}
                        onClick={async () => {
                          if (resetLock.current) return;
                          resetLock.current = true;
                          setReset("pending");
                          try {
                            await onRequestPasswordReset();
                            setReset("success");
                          } catch {
                            setReset("error");
                            resetLock.current = false;
                          }
                        }}
                      >
                        {reset === "pending"
                          ? labels.sending
                          : reset === "success"
                            ? labels.resetSent
                            : labels.resetPassword}
                      </button>
                    )}
                  </li>
                ))}
              </ul>
              <div className="min-h-5 text-sm">
                {reset === "success" && (
                  <output className="text-muted-foreground">{passwords.resetSent}</output>
                )}
                {reset === "error" && (
                  <p role="alert" className="text-destructive">
                    {passwords.resetRequestError}
                  </p>
                )}
              </div>
              {data.providers.includes("credential") && passwordForm && !error && (
                <div className="max-w-md space-y-4 border-t border-border pt-4">
                  <h3 className="font-medium">{passwords.changePasswordTitle}</h3>
                  {passwordForm}
                </div>
              )}
            </>
          )}
        </div>
      </section>
      <section className={accountCardClass}>
        <h2 className="font-semibold">{labels.sessions}</h2>
        <p className="mt-2 text-sm text-muted-foreground">{labels.sessionsDescription}</p>
        <div className="mt-4 min-h-24" aria-busy={loading}>
          {!data ? (
            <output>{error ? labels.sessionsUnavailable : labels.loadingSecurity}</output>
          ) : (
            <ul className="divide-y divide-border">
              {data.sessions.map((session) => (
                <li
                  key={session.id}
                  className="flex flex-col justify-between gap-4 py-4 first:pt-0 last:pb-0 sm:flex-row sm:items-center"
                >
                  <div className="min-w-0 space-y-1">
                    <p className="font-medium">
                      {session.current ? labels.currentSession : labels.otherSession}
                    </p>
                    <p className="max-w-2xl text-sm break-all text-muted-foreground">
                      {session.userAgent || labels.unknownBrowser}
                    </p>
                    <p className="text-sm text-muted-foreground tabular-nums">
                      {session.ipAddress || labels.unknownIp} · {labels.created}{" "}
                      {accountDate(session.createdAt, locale)} · {labels.expires}{" "}
                      {accountDate(session.expiresAt, locale)}
                    </p>
                  </div>
                  {!session.current && (
                    <button
                      type="button"
                      className={cn(accountButtonClass, "shrink-0 self-start sm:self-center")}
                      disabled={error || revoking !== null}
                      onClick={async () => {
                        if (revokeLock.current) return;
                        revokeLock.current = true;
                        setRevoking(session.id);
                        setRevokeFailed(false);
                        try {
                          await onRevokeSession(session.id);
                        } catch {
                          setRevokeFailed(true);
                        } finally {
                          revokeLock.current = false;
                          setRevoking(null);
                        }
                      }}
                    >
                      <LogOutIcon className="size-4 shrink-0" aria-hidden="true" />
                      {revoking === session.id ? labels.signingOut : labels.signOut}
                    </button>
                  )}
                </li>
              ))}
            </ul>
          )}
          <div className="mt-3 min-h-5 text-sm text-destructive">
            {revokeFailed && <p role="alert">{labels.revokeError}</p>}
          </div>
        </div>
      </section>
    </div>
  );
}

export const accountCardClass =
  "min-w-0 rounded-2xl border border-border bg-card p-5 text-card-foreground sm:p-6";
export const accountButtonClass =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-md border border-border px-3 text-sm font-medium outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50";
export const accountPrimaryClass =
  "border-transparent bg-primary text-primary-foreground hover:bg-primary/90";
export const accountInputClass =
  "h-10 w-full rounded-md border border-input bg-transparent px-3 text-base outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50 md:text-sm";
export const accountDialogClass =
  "fixed top-1/2 left-1/2 z-50 grid max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 gap-4 scroll-py-32 overflow-y-auto rounded-2xl border border-border bg-popover px-6 text-popover-foreground shadow-lg";
export function accountDate(value: Date | string, locale?: string) {
  return new Date(value).toLocaleString(locale, { dateStyle: "medium", timeStyle: "short" });
}

"use client";

import { Dialog } from "@base-ui/react/dialog";
import { XIcon, CopyIcon, PlusIcon, RefreshCwIcon, Trash2Icon } from "lucide-react";
import { useId, useRef, useState, type ReactNode } from "react";

import { ActionToastProvider, useActionToast } from "#/intranet/components/forge/action-toast.tsx";
import { IconTooltip } from "#/intranet/components/forge/icon-tooltip.tsx";
import { useLoadingActivity } from "#/intranet/components/forge/loading-indicator.tsx";
import { securityLabels, type SecurityLabels } from "#/intranet/components/forge/plugins/auth/account-labels.ts";
import {
  accountButtonClass,
  accountPrimaryClass,
  accountCardClass,
  accountInputClass,
  accountDialogClass,
  accountDate,
} from "#/intranet/components/forge/plugins/auth/account-styles.ts";
import { useTableSelection, type TableDeletionOptions } from "#/intranet/components/forge/table-selection.tsx";
import { cn } from "#/intranet/forge/utils.ts";
import { tableActionCellClass, tableActionHeaderClass } from "#/intranet/components/forge/utils/table-styles.ts";

export interface AgentKey {
  id: string;
  name: string;
  createdAt: Date | string;
  lastUsedAt: Date | string | null;
  expiresAt: Date | string;
  expired: boolean;
  revoked?: boolean;
}
export interface AgentKeysProps {
  keys?: AgentKey[];
  loading?: boolean;
  error?: boolean;
  onRetry: () => void;
  onCreate?: (input: { name: string; expiresAt: Date }) => Promise<{ token: string }>;
  onDelete: (id: string) => Promise<void>;
  labels?: Partial<SecurityLabels>;
  locale?: string;
  className?: string;
}
export function AgentKeys(props: AgentKeysProps) {
  return (
    <ActionToastProvider closeLabel={props.labels?.done}>
      <AgentKeysContent {...props} />
    </ActionToastProvider>
  );
}
function KeyDialog({
  open,
  onOpenChange,
  title,
  description,
  children,
  closeLabel,
  busy = false,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description: ReactNode;
  children: ReactNode;
  closeLabel: string;
  busy?: boolean;
}) {
  return (
    <Dialog.Root open={open} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-dark/50" />
        <Dialog.Popup className={accountDialogClass}>
          <div
            data-dialog-header
            className="sticky top-0 z-20 -mx-6 space-y-2 bg-popover px-6 pt-5 pb-0"
          >
            <div className="flex items-start justify-between gap-3">
              <Dialog.Title className="min-w-0 flex-1 text-lg font-semibold break-words">
                {title}
              </Dialog.Title>
              <IconTooltip label={closeLabel}>
                <Dialog.Close
                  type="button"
                  aria-label={closeLabel}
                  disabled={busy}
                  className="inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-md text-foreground hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50 md:size-8"
                >
                  <XIcon className="size-4 shrink-0" aria-hidden="true" />
                </Dialog.Close>
              </IconTooltip>
            </div>
            <Dialog.Description className="text-sm text-muted-foreground">
              {description}
            </Dialog.Description>
          </div>
          {children}
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}
function AgentKeysContent({
  keys,
  loading = false,
  error = false,
  onRetry,
  onCreate,
  onDelete,
  labels: overrides,
  locale,
  className,
}: AgentKeysProps) {
  useLoadingActivity(loading);
  const labels = { ...securityLabels, ...overrides };
  const id = `factory-agent-key-${useId()}`;
  const [creating, setCreating] = useState(false);
  const [name, setName] = useState("");
  const [expiry, setExpiry] = useState("");
  const [maxExpiry, setMaxExpiry] = useState("");
  const [failure, setFailure] = useState("");
  const [secret, setSecret] = useState("");
  const selection = useTableSelection(keys ?? []);
  const selectedKeys = selection.selected;
  const { deletion } = selection;
  const deleting = deletion.items;
  const [createPending, setCreatePending] = useState(false);
  const pending = createPending || selection.pending;
  const bulkDisabled = error || loading || pending || selectedKeys.length === 0;
  const lock = useRef(false);
  const notify = useActionToast();
  const deletionOptions: TableDeletionOptions<AgentKey> = {
    onDelete: (key) => onDelete(key.id),
    onComplete: (count) => notify(count > 1 ? labels.keysDeleted : labels.deleted),
  };
  const closeSecret = () => {
    setSecret("");
    setFailure("");
  };
  return (
    <section className={cn(accountCardClass, className)}>
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="space-y-2">
          <h2 className="font-semibold">{labels.keys}</h2>
          <p className="text-sm text-muted-foreground">{labels.keysDescription}</p>
        </div>
        {onCreate && (
          <button
            type="button"
            className={cn(accountButtonClass, accountPrimaryClass)}
            disabled={!keys || error || pending}
            onClick={() => {
              const now = Date.now();
              const date = new Date(now + 30 * 86400000);
              date.setMinutes(date.getMinutes() - date.getTimezoneOffset());
              setExpiry(date.toISOString().slice(0, 16));
              const maxDate = new Date(now + 90 * 86400000);
              maxDate.setMinutes(maxDate.getMinutes() - maxDate.getTimezoneOffset());
              setMaxExpiry(maxDate.toISOString().slice(0, 16));
              setName("");
              setFailure("");
              setCreating(true);
            }}
          >
            <PlusIcon className="size-4 shrink-0" aria-hidden="true" />
            {labels.createKey}
          </button>
        )}
      </div>
      <div className="mt-5 min-h-24 min-w-0" aria-busy={loading}>
        {error && (
          <div role="alert" className="space-y-3">
            <p>{labels.keysError}</p>
            <button
              type="button"
              className={accountButtonClass}
              disabled={loading}
              onClick={onRetry}
            >
              <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
              {labels.retry}
            </button>
          </div>
        )}
        {!keys ? (
          !error && <output>{labels.loadingKeys}</output>
        ) : !keys.length ? (
          <p className="py-6 text-muted-foreground">{labels.noKeys}</p>
        ) : (
          <div className="relative overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border">
                  <th scope="col" className="w-10">
                    <label className="inline-flex size-10 items-center justify-center">
                      <input
                        type="checkbox"
                        aria-label={labels.selectAllKeys}
                        className="size-4 cursor-pointer accent-primary focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed"
                        checked={selection.all}
                        ref={(input) => {
                          if (input) {
                            input.indeterminate = selection.mixed;
                          }
                        }}
                        disabled={error || loading || pending}
                        onChange={(event) => selection.toggleAll(event.target.checked)}
                      />
                    </label>
                  </th>
                  {(["name", "status", "created", "lastUsed", "expires"] as const).map((column) => (
                    <th
                      key={column}
                      scope="col"
                      className="p-2 text-left font-medium text-muted-foreground"
                    >
                      {labels[column]}
                    </th>
                  ))}
                  <th scope="col" className={cn(tableActionHeaderClass, "w-14")}>
                    <span className="sr-only">{labels.actions}</span>
                    <div className="h-10">
                      <IconTooltip label={`${labels.deleteSelectedKeys} (${selectedKeys.length})`}>
                        <button
                          type="button"
                          className={cn(
                            accountButtonClass,
                            "size-10 p-0",
                            bulkDisabled
                              ? "bg-background text-foreground disabled:hover:bg-background"
                              : "border-transparent",
                          )}
                          aria-label={`${labels.deleteSelectedKeys} (${selectedKeys.length})`}
                          disabled={bulkDisabled}
                          onClick={() => {
                            deletion.open(deletionOptions);
                          }}
                        >
                          <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
                        </button>
                      </IconTooltip>
                    </div>
                  </th>
                </tr>
              </thead>
              <tbody>
                {keys.map((key) => (
                  <tr key={key.id} className="border-b border-border last:border-0">
                    <td>
                      <label className="inline-flex size-10 items-center justify-center">
                        <input
                          type="checkbox"
                          aria-label={`${labels.selectKey} ${key.name}`}
                          className="size-4 cursor-pointer accent-primary focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed"
                          checked={selectedKeys.some((selected) => selected.id === key.id)}
                          disabled={error || loading || pending}
                          onChange={(event) => selection.toggle(key.id, event.target.checked)}
                        />
                      </label>
                    </td>
                    <td className="max-w-56 truncate p-2 font-medium">{key.name}</td>
                    <td className="p-2">
                      <span
                        className={cn(
                          "rounded-full px-2 py-1 text-xs",
                          key.expired || key.revoked
                            ? "bg-status-canceled text-status-canceled-foreground"
                            : "bg-status-success text-status-success-foreground",
                        )}
                      >
                        {key.revoked
                          ? labels.revoked
                          : key.expired
                            ? labels.expired
                            : labels.active}
                      </span>
                    </td>
                    <td className="p-2 whitespace-nowrap tabular-nums">
                      {accountDate(key.createdAt, locale)}
                    </td>
                    <td className="p-2 whitespace-nowrap tabular-nums">
                      {key.lastUsedAt ? accountDate(key.lastUsedAt, locale) : labels.never}
                    </td>
                    <td className="p-2 whitespace-nowrap tabular-nums">
                      {accountDate(key.expiresAt, locale)}
                    </td>
                    <td className={tableActionCellClass}>
                      <IconTooltip label={`${labels.delete} ${key.name}`}>
                        <button
                          type="button"
                          className={cn(accountButtonClass, "size-10 border-transparent p-0")}
                          aria-label={`${labels.delete} ${key.name}`}
                          disabled={error || loading || pending}
                          onClick={() => {
                            deletion.open(deletionOptions, [key]);
                          }}
                        >
                          <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
                        </button>
                      </IconTooltip>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
      <KeyDialog
        closeLabel={labels.close ?? labels.cancel}
        busy={pending}
        open={creating}
        onOpenChange={(open) => {
          if (!lock.current) setCreating(open);
        }}
        title={labels.createKey}
        description={labels.createDescription}
      >
        <form
          className="contents"
          aria-busy={pending}
          onSubmit={async (event) => {
            event.preventDefault();
            if (lock.current || error || !onCreate) return;
            const expiresAt = new Date(expiry);
            const now = Date.now();
            if (
              !name.trim() ||
              name.trim().length > 100 ||
              !Number.isFinite(expiresAt.getTime()) ||
              expiresAt.getTime() <= now ||
              expiresAt.getTime() > now + 90 * 86400000
            ) {
              setFailure(labels.invalidKey);
              return;
            }
            lock.current = true;
            setCreatePending(true);
            setFailure("");
            try {
              const { token } = await onCreate({ name: name.trim(), expiresAt });
              setCreating(false);
              setSecret(token);
            } catch {
              setFailure(labels.createError);
            } finally {
              lock.current = false;
              setCreatePending(false);
            }
          }}
        >
          <div className="grid gap-2">
            <label htmlFor={`${id}-name`}>{labels.name}</label>
            <input
              id={`${id}-name`}
              value={name}
              onChange={(e) => setName(e.target.value)}
              maxLength={100}
              required
              autoComplete="off"
              readOnly={pending}
              className={accountInputClass}
            />
          </div>
          <div className="grid gap-2">
            <label htmlFor={`${id}-expiry`}>{labels.expiryDate}</label>
            <input
              id={`${id}-expiry`}
              type="datetime-local"
              max={maxExpiry}
              value={expiry}
              onChange={(e) => setExpiry(e.target.value)}
              required
              readOnly={pending}
              className={accountInputClass}
            />
          </div>
          <div className="min-h-5 text-sm text-destructive">
            {failure && <p role="alert">{failure}</p>}
          </div>
          <div
            data-dialog-footer
            className="sticky bottom-0 z-10 -mx-6 flex flex-wrap justify-end gap-2 bg-popover px-6 pt-0 pb-5"
          >
            <button
              type="button"
              className={accountButtonClass}
              disabled={pending}
              onClick={() => setCreating(false)}
            >
              {labels.cancel}
            </button>
            <button
              type="submit"
              className={cn(accountButtonClass, accountPrimaryClass)}
              disabled={pending || error}
            >
              {pending ? labels.creating : labels.createKey}
            </button>
          </div>
        </form>
      </KeyDialog>
      <KeyDialog
        closeLabel={labels.close ?? labels.cancel}
        open={Boolean(secret)}
        onOpenChange={(open) => {
          if (!open) closeSecret();
        }}
        title={labels.keyCreated}
        description={labels.copyDescription}
      >
        <input
          aria-label={labels.newKey}
          value={secret}
          readOnly
          className={cn(accountInputClass, "font-mono")}
          onFocus={(e) => e.target.select()}
        />
        <div className="min-h-5 text-sm text-destructive">
          {failure && <p role="alert">{failure}</p>}
        </div>
        <div
          data-dialog-footer
          className="sticky bottom-0 z-10 -mx-6 flex flex-wrap justify-end gap-2 bg-popover px-6 pt-0 pb-5"
        >
          <button type="button" className={accountButtonClass} onClick={closeSecret}>
            {labels.done}
          </button>
          <button
            type="button"
            className={cn(accountButtonClass, accountPrimaryClass)}
            onClick={async () => {
              try {
                await navigator.clipboard.writeText(secret);
                notify(labels.copied);
              } catch {
                setFailure(labels.copyError);
              }
            }}
          >
            <CopyIcon className="size-4 shrink-0" aria-hidden="true" />
            {labels.copy}
          </button>
        </div>
      </KeyDialog>
      <KeyDialog
        closeLabel={labels.close ?? labels.cancel}
        busy={pending}
        open={deleting.length > 0}
        onOpenChange={(open) => {
          if (!open) deletion.close();
        }}
        title={deleting.length > 1 ? labels.deleteKeys : labels.deleteKey}
        description={
          <>
            {deleting.length > 1 ? labels.deleteKeysDescription : labels.deleteDescription}{" "}
            <strong>{deleting.map((key) => key.name).join(", ")}</strong>
          </>
        }
      >
        <div className="min-h-5 text-sm text-destructive">
          {deletion.failure && (
            <p role="alert">
              {deletion.attempted > 1 ? labels.deleteKeysError : labels.deleteError}
            </p>
          )}
        </div>
        <div
          data-dialog-footer
          className="sticky bottom-0 z-10 -mx-6 flex flex-wrap justify-end gap-2 bg-popover px-6 pt-0 pb-5"
        >
          <button
            type="button"
            className={accountButtonClass}
            disabled={pending}
            onClick={() => deletion.close()}
          >
            {labels.cancel}
          </button>
          <button
            type="button"
            className={cn(
              accountButtonClass,
              "border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/90",
            )}
            disabled={pending || loading || error}
            onClick={() => {
              if (!pending && !loading && !error) void deletion.confirm(deletionOptions);
            }}
          >
            {pending ? labels.deleting : labels.delete}
          </button>
        </div>
      </KeyDialog>
    </section>
  );
}

