"use client";

import { Avatar } from "@base-ui/react/avatar";
import { Tabs } from "@base-ui/react/tabs";
import { LoaderCircleIcon } from "lucide-react";
import { useId, useRef, useState, type ReactNode } from "react";

import { ActionToastProvider, useActionToast } from "#/intranet/components/forge/action-toast.tsx";
import {
  AccountEmailChange,
  type AccountEmailChangeProps,
} from "#/intranet/components/forge/plugins/auth/account-email-change.tsx";
import { accountLabels, type AccountLabels } from "#/intranet/components/forge/plugins/auth/account-labels.ts";
import {
  accountCardClass,
  accountButtonClass,
  accountPrimaryClass,
  accountInputClass,
} from "#/intranet/components/forge/plugins/auth/account-styles.ts";
import { cn } from "#/intranet/forge/utils.ts";

export interface AccountTab {
  id: string;
  label: string;
  content: ReactNode;
}
interface DefaultAccountProps {
  /** Host-selected plugin sections; IDs must be unique and exclude about/security. */
  tabs?: AccountTab[];
  activeTab?: string;
  onTabChange?: (tab: string) => void;
  onChangeEmail?: (email: string) => Promise<void>;
  emailChangeLabels?: AccountEmailChangeProps["labels"];
  onUpdateProfile: (profile: { name: string }) => Promise<void>;
  security: ReactNode;
  content?: never;
}
export type AccountPageProps = {
  user: { id: string; name: string; email: string; image?: string | null; roleLabel?: string };
  /** Host summary, including custom verification details or avatar actions. */
  header?: ReactNode;
  labels?: Partial<AccountLabels>;
  className?: string;
} & (
  | DefaultAccountProps
  | {
      /** Host navigation and routed forms replace the default About/Security panels. */
      content: ReactNode;
      onUpdateProfile?: never;
      security?: never;
    }
);

export function AccountPage(props: AccountPageProps) {
  return (
    <ActionToastProvider closeLabel={props.labels?.close}>
      <AccountPageContent key={props.user.id} {...props} />
    </ActionToastProvider>
  );
}
function AccountPageContent(props: AccountPageProps) {
  const { user, header, labels: overrides, className } = props;
  const labels = { ...accountLabels, ...overrides };
  const initials = (user.name || user.email)
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part.charAt(0))
    .join("")
    .toUpperCase();
  return (
    <div className={cn("mx-auto flex w-full max-w-7xl min-w-0 flex-col gap-6", className)}>
      {header ?? (
        <>
          <h1 className="text-2xl font-bold text-foreground">{labels.title}</h1>
          <section className={cn(accountCardClass, "flex flex-wrap items-center gap-4")}>
            <div className="flex min-w-0 items-center gap-4">
              <Avatar.Root className="relative flex size-16 shrink-0 overflow-hidden rounded-full border border-border">
                <Avatar.Image
                  src={user.image ?? undefined}
                  alt={user.name}
                  className="size-full object-cover"
                />
                <Avatar.Fallback className="flex size-full items-center justify-center bg-muted text-xl text-muted-foreground">
                  {initials}
                </Avatar.Fallback>
              </Avatar.Root>
              <div className="min-w-0">
                <h2 className="truncate text-lg font-semibold">{user.name}</h2>
                <p className="truncate text-sm text-muted-foreground">{user.email}</p>
              </div>
            </div>
            {user.roleLabel && (
              <dl className="ml-auto text-sm">
                <dt className="text-muted-foreground">{labels.role}</dt>
                <dd className="font-medium">{user.roleLabel}</dd>
              </dl>
            )}
          </section>
        </>
      )}
      {"content" in props ? props.content : <DefaultAccountSections {...props} />}
    </div>
  );
}

function DefaultAccountSections({
  user,
  onUpdateProfile,
  security,
  tabs = [],
  activeTab,
  onTabChange,
  onChangeEmail,
  emailChangeLabels,
  labels: overrides,
}: Omit<AccountPageProps, "content"> & DefaultAccountProps) {
  const labels = { ...accountLabels, ...overrides };
  const id = `factory-account-${useId()}`;
  const [name, setName] = useState(user.name);
  const [pending, setPending] = useState(false);
  const [failed, setFailed] = useState(false);
  const lock = useRef(false);
  const notify = useActionToast();
  return (
    <Tabs.Root
      defaultValue="about"
      value={activeTab}
      onValueChange={(value) => onTabChange?.(String(value))}
      className="grid min-w-0 gap-6"
    >
      <div className="border-b border-border/60">
        <Tabs.List aria-label={labels.sections} className="-mb-px flex gap-0 overflow-x-auto">
          {[
            { id: "about", label: labels.about },
            ...tabs,
            { id: "security", label: labels.security },
          ].map((tab) => (
            <Tabs.Tab
              key={tab.id}
              value={tab.id}
              className="relative min-h-11 cursor-pointer border-b-2 border-transparent px-4 text-sm font-medium text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring data-active:border-primary data-active:text-primary"
            >
              {tab.label}
            </Tabs.Tab>
          ))}
        </Tabs.List>
      </div>
      <Tabs.Panel value="about" keepMounted className="data-hidden:hidden">
        <form
          className="grid gap-4"
          aria-busy={pending}
          onSubmit={async (event) => {
            event.preventDefault();
            if (lock.current || !name.trim() || !event.currentTarget.reportValidity()) return;
            lock.current = true;
            setPending(true);
            setFailed(false);
            try {
              await onUpdateProfile({ name: name.trim() });
              notify(labels.saved);
            } catch {
              setFailed(true);
            } finally {
              lock.current = false;
              setPending(false);
            }
          }}
        >
          <section className={accountCardClass}>
            <h2 className="font-semibold">{labels.about}</h2>
            <p className="mt-2 text-sm text-muted-foreground">{labels.aboutDescription}</p>
            <div className="mt-5 grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <label htmlFor={`${id}-name`}>{labels.name}</label>
                <input
                  id={`${id}-name`}
                  name="name"
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                  autoComplete="name"
                  maxLength={200}
                  readOnly={pending}
                  required
                  className={accountInputClass}
                />
              </div>
              <div className="grid gap-2">
                <label htmlFor={`${id}-email`}>{labels.email}</label>
                <input
                  id={`${id}-email`}
                  name="email"
                  type="email"
                  value={user.email}
                  autoComplete="email"
                  readOnly
                  className={cn(accountInputClass, "bg-muted/50 text-muted-foreground")}
                />
              </div>
            </div>
          </section>
          <div className="min-h-5 text-sm text-destructive">
            {failed && <p role="alert">{labels.saveError}</p>}
          </div>
          <button
            type="submit"
            disabled={pending || !name.trim()}
            className={cn(accountButtonClass, accountPrimaryClass, "justify-self-start")}
          >
            {pending && <LoaderCircleIcon className="size-4 animate-spin" aria-hidden="true" />}
            {pending ? labels.saving : labels.save}
          </button>
        </form>
        {onChangeEmail && (
          <AccountEmailChange
            email={user.email}
            onChangeEmail={onChangeEmail}
            labels={emailChangeLabels}
          />
        )}
      </Tabs.Panel>
      {tabs.map((tab) => (
        <Tabs.Panel key={tab.id} value={tab.id} keepMounted className="min-w-0 data-hidden:hidden">
          {tab.content}
        </Tabs.Panel>
      ))}
      <Tabs.Panel value="security" className="min-w-0">
        {security}
      </Tabs.Panel>
    </Tabs.Root>
  );
}

"use client";

import {
  ArrowLeftIcon,
  CheckCircleIcon,
  EyeIcon,
  EyeOffIcon,
  LoaderCircleIcon,
  MailCheckIcon,
} from "lucide-react";
import { useId, useRef, useState, type ComponentType, type ReactNode } from "react";

import { ActionToastProvider, useActionToast } from "#/intranet/components/forge/action-toast.tsx";
import { IconTooltip } from "#/intranet/components/forge/icon-tooltip.tsx";
import { Link, type LinkProps } from "#/intranet/components/forge/ui/link.tsx";
import { passwordLabels, type PasswordLabels } from "#/intranet/components/forge/plugins/auth/password-labels.ts";
import { cn } from "#/intranet/forge/utils.ts";

const inputClass =
  "h-12 w-full rounded-lg border border-input bg-transparent px-3 text-base shadow-xs outline-none focus-visible:ring-2 focus-visible:ring-ring md:text-sm";
const buttonClass =
  "inline-flex h-12 items-center justify-center gap-2 rounded-lg bg-primary px-4 text-sm font-medium text-primary-foreground outline-none hover:bg-primary/90 focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 cursor-pointer disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed";
const linkClass =
  "inline-flex items-center gap-2 rounded-sm text-sm font-medium text-primary hover:underline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring";

interface FormProps {
  labels?: Partial<PasswordLabels>;
  className?: string;
}
interface RecoveryProps extends FormProps {
  enabled?: boolean;
  loginHref?: string;
  linkComponent?: ComponentType<LinkProps>;
}
export interface ForgotPasswordFormProps extends RecoveryProps {
  onRequestReset: (email: string) => Promise<void>;
}
export interface ChangePasswordValues {
  currentPassword: string;
  newPassword: string;
}
export interface ChangePasswordFormProps extends FormProps {
  /** The host must validate the session, current password and new password on the server. */
  onChangePassword: (values: ChangePasswordValues) => Promise<void>;
  minLength?: number;
  maxLength?: number;
}
export interface ResetPasswordFormProps extends RecoveryProps {
  /** The host checks the link before rendering; the server must verify the token on submission. */
  validLink: boolean;
  onResetPassword: (newPassword: string) => Promise<void>;
  requestResetHref?: string;
  minLength?: number;
  maxLength?: number;
}
export type ChangePasswordPageProps = ChangePasswordFormProps;

type PasswordFormProps = ChangePasswordFormProps & {
  mode?: "change" | "reset";
  fullWidthSubmit?: boolean;
  requestResetLink?: ReactNode;
};

function useSubmission() {
  const lock = useRef(false);
  const [pending, setPending] = useState(false);
  const [failed, setFailed] = useState(false);
  const [succeeded, setSucceeded] = useState(false);
  async function submit(action: () => Promise<void>, form: HTMLFormElement) {
    if (lock.current) return;
    lock.current = true;
    setPending(true);
    setFailed(false);
    setSucceeded(false);
    try {
      await action();
      form.reset();
      setSucceeded(true);
    } catch {
      setFailed(true);
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  return { pending, failed, succeeded, submit };
}

export function ForgotPasswordForm({
  onRequestReset,
  enabled = true,
  loginHref,
  labels: overrides,
  className,
  linkComponent: FormLink = Link,
}: ForgotPasswordFormProps) {
  const labels = { ...passwordLabels, ...overrides };
  const id = `factory-password-form-${useId()}`;
  const state = useSubmission();
  return (
    <div className={cn("grid gap-6", className)}>
      <div>
        <h1 className="text-3xl font-semibold tracking-tight">
          {state.succeeded ? labels.checkEmail : labels.forgotTitle}
        </h1>
        <p className="mt-3 text-sm leading-relaxed text-muted-foreground">
          {state.succeeded ? labels.resetSent : labels.forgotDescription}
        </p>
      </div>
      {state.succeeded ? (
        <output className="flex items-center gap-3 rounded-xl bg-status-success p-4 text-sm text-status-success-foreground">
          <MailCheckIcon className="size-5 shrink-0 text-primary" aria-hidden="true" />
          {labels.checkSpam}
        </output>
      ) : !enabled ? (
        <output className="rounded-xl border border-border bg-muted/50 p-4 text-sm">
          {labels.resetUnavailable}
        </output>
      ) : (
        <form
          className="grid gap-5"
          aria-busy={state.pending}
          onSubmit={(event) => {
            event.preventDefault();
            const form = event.currentTarget;
            if (state.pending || !form.reportValidity()) return;
            const email = new FormData(form).get("email");
            if (typeof email === "string")
              void state.submit(() => onRequestReset(email.trim()), form);
          }}
        >
          <div className="grid gap-2">
            <label htmlFor={`${id}-email`}>{labels.email}</label>
            <input
              id={`${id}-email`}
              name="email"
              type="email"
              autoComplete="email"
              autoCapitalize="none"
              spellCheck={false}
              className={inputClass}
              required
              readOnly={state.pending}
              aria-describedby={state.failed ? `${id}-error` : undefined}
            />
          </div>
          {state.failed && (
            <p id={`${id}-error`} role="alert" className="text-sm text-destructive">
              {labels.resetRequestError}
            </p>
          )}
          <button type="submit" className={buttonClass} disabled={state.pending}>
            {state.pending && (
              <LoaderCircleIcon className="size-4 animate-spin" aria-hidden="true" />
            )}
            {state.pending ? labels.sendingLink : labels.sendResetLink}
          </button>
        </form>
      )}
      {loginHref && (
        <FormLink
          href={loginHref}
          className={cn(
            linkClass,
            "min-h-10 justify-self-start rounded-lg px-3 hover:bg-primary/5 hover:no-underline",
          )}
        >
          <ArrowLeftIcon className="size-4" aria-hidden="true" />
          {labels.backToLogin}
        </FormLink>
      )}
    </div>
  );
}

function PasswordFormContent({
  onChangePassword,
  minLength = 8,
  maxLength = 128,
  labels: overrides,
  className,
  mode = "change",
  fullWidthSubmit,
  requestResetLink,
}: PasswordFormProps) {
  const labels = { ...passwordLabels, ...overrides };
  const id = `factory-password-form-${useId()}`;
  const state = useSubmission();
  const [visiblePasswords, setVisiblePasswords] = useState({
    currentPassword: false,
    newPassword: false,
  });
  const reset = mode === "reset";
  const notify = useActionToast();
  return (
    <div className={cn("grid gap-5", className)}>
      {reset && state.succeeded && (
        <output className="flex items-center gap-3 rounded-xl bg-status-success p-4 text-sm text-status-success-foreground">
          <CheckCircleIcon className="size-5 shrink-0 text-primary" aria-hidden="true" />
          {labels.resetSuccess}
        </output>
      )}
      {!(reset && state.succeeded) && (
        <form
          className="grid gap-5"
          aria-busy={state.pending}
          onReset={() => setVisiblePasswords({ currentPassword: false, newPassword: false })}
          onSubmit={(event) => {
            event.preventDefault();
            const form = event.currentTarget;
            if (state.pending || !form.reportValidity()) return;
            const data = new FormData(form);
            const currentPassword = reset ? "" : data.get("currentPassword");
            const newPassword = data.get("newPassword");
            if (typeof currentPassword !== "string" || typeof newPassword !== "string") return;
            void state.submit(async () => {
              await onChangePassword({ currentPassword, newPassword });
              if (!reset) notify(labels.passwordChanged);
            }, form);
          }}
        >
          {(["currentPassword", "newPassword"] as const).map((name) => {
            if (reset && name === "currentPassword") return null;
            const isNew = name === "newPassword";
            const showPassword = visiblePasswords[name];
            return (
              <div key={name} className="grid gap-2">
                <label htmlFor={`${id}-${name}`}>{labels[name]}</label>
                <div className="relative">
                  <input
                    id={`${id}-${name}`}
                    name={name}
                    type={showPassword ? "text" : "password"}
                    autoComplete={isNew ? "new-password" : "current-password"}
                    autoCapitalize="none"
                    spellCheck={false}
                    className={cn(inputClass, "pr-12")}
                    minLength={isNew ? minLength : undefined}
                    maxLength={isNew ? maxLength : undefined}
                    required
                    readOnly={state.pending}
                    aria-describedby={
                      isNew
                        ? state.failed
                          ? `${id}-hint ${id}-error`
                          : `${id}-hint`
                        : state.failed
                          ? `${id}-error`
                          : undefined
                    }
                  />
                  <IconTooltip label={showPassword ? labels.hidePassword : labels.showPassword}>
                    <button
                      type="button"
                      onClick={() =>
                        setVisiblePasswords({ ...visiblePasswords, [name]: !showPassword })
                      }
                      disabled={state.pending}
                      aria-label={showPassword ? labels.hidePassword : labels.showPassword}
                      aria-controls={`${id}-${name}`}
                      aria-pressed={showPassword}
                      className="absolute inset-y-0 right-0 flex w-12 cursor-pointer items-center justify-center rounded-lg text-muted-foreground hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50"
                    >
                      {showPassword ? (
                        <EyeOffIcon className="size-4" aria-hidden="true" />
                      ) : (
                        <EyeIcon className="size-4" aria-hidden="true" />
                      )}
                    </button>
                  </IconTooltip>
                </div>
                {isNew && (
                  <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
                    <p id={`${id}-hint`} className="text-xs text-muted-foreground">
                      {labels.passwordHint}
                    </p>
                    {requestResetLink}
                  </div>
                )}
              </div>
            );
          })}
          <div className="grid gap-2">
            <button
              type="submit"
              className={cn(buttonClass, !reset && !fullWidthSubmit && "justify-self-start")}
              disabled={state.pending}
            >
              {state.pending && (
                <LoaderCircleIcon className="size-4 animate-spin" aria-hidden="true" />
              )}
              {state.pending
                ? labels.changingPassword
                : reset
                  ? labels.resetSubmit
                  : labels.changePassword}
            </button>
            <p
              id={`${id}-error`}
              role={state.failed ? "alert" : undefined}
              aria-hidden={!state.failed}
              className={cn("text-sm text-destructive", !state.failed && "invisible")}
            >
              {reset ? labels.resetError : labels.changePasswordError}
            </p>
          </div>
        </form>
      )}
    </div>
  );
}

export function ChangePasswordForm(props: ChangePasswordFormProps) {
  return <PasswordForm {...props} />;
}

export function ResetPasswordForm({
  onResetPassword,
  validLink,
  enabled = true,
  loginHref,
  requestResetHref,
  labels: overrides,
  className,
  linkComponent: FormLink = Link,
  minLength,
  maxLength,
}: ResetPasswordFormProps) {
  const labels = { ...passwordLabels, ...overrides };
  const requestResetLink =
    enabled && requestResetHref ? (
      <FormLink href={requestResetHref} className={cn(linkClass, "text-xs")}>
        {labels.requestNewLink}
      </FormLink>
    ) : null;
  return (
    <div className={cn("grid gap-6", className)}>
      <div>
        <h1 className="text-3xl font-semibold tracking-tight">{labels.resetTitle}</h1>
        <p className="mt-3 text-sm leading-relaxed text-muted-foreground">
          {labels.resetDescription}
        </p>
      </div>
      {!enabled ? (
        <output className="text-sm">{labels.resetUnavailable}</output>
      ) : !validLink ? (
        <p role="alert" className="text-sm text-destructive">
          {labels.invalidResetLink}
        </p>
      ) : (
        <PasswordForm
          mode="reset"
          labels={labels}
          minLength={minLength}
          maxLength={maxLength}
          onChangePassword={({ newPassword }) => onResetPassword(newPassword)}
          requestResetLink={requestResetLink}
        />
      )}
      {enabled && !validLink && requestResetLink}
      {loginHref && (
        <FormLink
          href={loginHref}
          className={cn(
            linkClass,
            "min-h-10 justify-self-start rounded-lg px-3 hover:bg-primary/5 hover:no-underline",
          )}
        >
          <ArrowLeftIcon className="size-4" aria-hidden="true" />
          {labels.backToLogin}
        </FormLink>
      )}
    </div>
  );
}

/** Place inside AuthLayout, or the host's existing authentication layout. */
export function ChangePasswordPage({
  className,
  labels: overrides,
  ...props
}: ChangePasswordPageProps) {
  const labels = { ...passwordLabels, ...overrides };
  return (
    <section className={cn("grid gap-6", className)}>
      <div>
        <h1 className="text-3xl font-semibold tracking-tight">{labels.changePasswordTitle}</h1>
        <p className="mt-3 text-sm leading-relaxed text-muted-foreground">
          {labels.changePasswordSubtitle}
        </p>
      </div>
      <PasswordForm {...props} labels={labels} fullWidthSubmit />
    </section>
  );
}

function PasswordForm(props: PasswordFormProps) {
  return (
    <ActionToastProvider>
      <PasswordFormContent {...props} />
    </ActionToastProvider>
  );
}

"use client";

import { useId, useRef, useState } from "react";

import {
  accountCardClass,
  accountInputClass,
  accountButtonClass,
  accountPrimaryClass,
} from "#/intranet/components/forge/plugins/auth/account-styles.ts";
import { cn } from "#/intranet/forge/utils.ts";

export const emailChangeLabels = {
  title: "Change email",
  description:
    "Confirm the change using the email sent by this site. Your current address stays active until confirmation.",
  email: "New email address",
  submit: "Send confirmation",
  sending: "Sending…",
  sent: "Check your email to confirm the change.",
  error: "Could not request the change. Please try again.",
};
export interface AccountEmailChangeProps {
  email: string;
  /** Host authorizes the signed-in account and uses its provider's confirmation flow. */
  onChangeEmail: (email: string) => Promise<void>;
  labels?: Partial<typeof emailChangeLabels>;
  className?: string;
}
export function AccountEmailChange({
  email,
  onChangeEmail,
  labels: overrides,
  className,
}: AccountEmailChangeProps) {
  const labels = { ...emailChangeLabels, ...overrides };
  const id = `factory-email-change-${useId()}`;
  const [value, setValue] = useState("");
  const [status, setStatus] = useState<"idle" | "pending" | "sent" | "error">("idle");
  const lock = useRef(false);
  return (
    <form
      className={cn(accountCardClass, "mt-6 grid gap-4", className)}
      aria-busy={status === "pending"}
      onSubmit={async (event) => {
        event.preventDefault();
        if (
          lock.current ||
          !event.currentTarget.reportValidity() ||
          value.trim().toLowerCase() === email.toLowerCase()
        )
          return;
        lock.current = true;
        setStatus("pending");
        try {
          await onChangeEmail(value.trim());
          setStatus("sent");
          setValue("");
        } catch {
          setStatus("error");
        } finally {
          lock.current = false;
        }
      }}
    >
      <h2 className="font-semibold">{labels.title}</h2>
      <p className="text-sm text-muted-foreground">{labels.description}</p>
      <label htmlFor={id}>
        {labels.email} <span aria-hidden="true">*</span>
      </label>
      <input
        id={id}
        type="email"
        autoComplete="email"
        maxLength={254}
        required
        value={value}
        readOnly={status === "pending"}
        className={accountInputClass}
        onChange={(event) => {
          setValue(event.target.value);
          setStatus("idle");
        }}
      />
      <div className="grid text-sm">
        <p aria-hidden="true" className="invisible col-start-1 row-start-1">
          {labels.error}
        </p>
        <p aria-hidden="true" className="invisible col-start-1 row-start-1">
          {labels.sent}
        </p>
        {status === "error" && (
          <p role="alert" className="col-start-1 row-start-1 text-destructive">
            {labels.error}
          </p>
        )}
        {status === "sent" && <output className="col-start-1 row-start-1">{labels.sent}</output>}
      </div>
      <button
        type="submit"
        disabled={
          status === "pending" ||
          !value.trim() ||
          value.trim().toLowerCase() === email.toLowerCase()
        }
        className={cn(accountButtonClass, accountPrimaryClass, "justify-self-start")}
      >
        {status === "pending" ? labels.sending : labels.submit}
      </button>
    </form>
  );
}

"use client";

import { LoaderCircleIcon, LogOutIcon } from "lucide-react";
import { useRef, useState, type ComponentProps } from "react";

import { cn } from "#/intranet/forge/utils.ts";

/** Share one action across mutually exclusive controls, such as password and Google sign-in. */
export function useAuthAction() {
  const lock = useRef(false);
  const [status, setStatus] = useState<"idle" | "pending" | "success" | "error">("idle");
  async function run(action: () => Promise<void>) {
    if (lock.current) return;
    lock.current = true;
    setStatus("pending");
    try {
      await action();
      setStatus("success");
    } catch {
      lock.current = false;
      setStatus("error");
    }
  }
  return {
    run,
    pending: status === "pending",
    failed: status === "error",
    completed: status === "success",
    disabled: status === "pending" || status === "success",
  };
}

export interface AuthControlProps extends Omit<ComponentProps<"button">, "children"> {
  pending?: boolean;
  label?: string;
  pendingLabel?: string;
}

const buttonClass =
  "inline-flex h-12 items-center justify-center gap-2 rounded-lg border border-border bg-background px-4 text-sm font-medium text-foreground hover:bg-muted outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-4 cursor-pointer disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed";

// Monochrome Google mark follows the host's semantic foreground color.
function GoogleIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
      <path d="M21.6 12.23c0-.71-.06-1.39-.18-2.05H12v3.88h5.38a4.6 4.6 0 0 1-2 3.02v2.51h3.24c1.9-1.75 2.98-4.33 2.98-7.36ZM12 22c2.7 0 4.96-.9 6.62-2.41l-3.24-2.51c-.9.6-2.06.97-3.38.97-2.61 0-4.82-1.76-5.61-4.12H3.05v2.59A10 10 0 0 0 12 22Zm-5.61-8.07a6 6 0 0 1 0-3.86V7.48H3.05a10 10 0 0 0 0 9.04l3.34-2.59ZM12 5.95c1.47 0 2.79.51 3.83 1.51L18.7 4.6A9.6 9.6 0 0 0 12 2a10 10 0 0 0-8.95 5.48l3.34 2.59C7.18 7.71 9.39 5.95 12 5.95Z" />
    </svg>
  );
}

/** Controlled button; pair with useAuthAction and place failure feedback in the host layout. */
export function GoogleSignInButton({
  pending = false,
  disabled,
  label = "Continue with Google",
  pendingLabel = "Connecting to Google...",
  className,
  ...props
}: AuthControlProps) {
  return (
    <button
      {...props}
      type="button"
      disabled={disabled || pending}
      aria-busy={pending}
      className={cn(buttonClass, className)}
    >
      {pending ? <LoaderCircleIcon className="animate-spin" aria-hidden="true" /> : <GoogleIcon />}
      {pending ? pendingLabel : label}
    </button>
  );
}

/** Shares state and feedback with a surrounding menu or page through useAuthAction. */
export function SignOutButton({
  pending = false,
  disabled,
  label = "Sign out",
  pendingLabel = "Signing out...",
  className,
  ...props
}: AuthControlProps) {
  return (
    <button
      {...props}
      type="button"
      disabled={disabled || pending}
      aria-busy={pending}
      className={cn(buttonClass, className)}
    >
      {pending ? (
        <LoaderCircleIcon className="animate-spin" aria-hidden="true" />
      ) : (
        <LogOutIcon aria-hidden="true" />
      )}
      {pending ? pendingLabel : label}
    </button>
  );
}

