import { z } from "zod";

export const employeeRoleSchema = z.enum(["user", "admin"]);

export const createEmployeeSchema = z.object({
  name: z.string().trim().min(1).max(200),
  email: z.string().trim().pipe(z.email()),
  role: employeeRoleSchema.default("user"),
});

export const listEmployeesSchema = z.object({
  offset: z.number().int().nonnegative().default(0),
});

export const setEmployeeBanSchema = z.object({
  id: z.string().min(1),
  banned: z.boolean(),
});

export const employeeIdSchema = z.object({ id: z.string().min(1) });

export const updateEmployeeSchema = createEmployeeSchema.extend({
  id: z.string().min(1),
});

export const EMPLOYEE_PAGE_SIZE = 25;
export type EmployeeRole = z.infer<typeof employeeRoleSchema>;
export type CreateEmployee = z.infer<typeof createEmployeeSchema>;
export type UpdateEmployee = z.infer<typeof updateEmployeeSchema>;
export interface Employee {
  id: string;
  name: string;
  email: string;
  role?: string | null;
  image?: string | null;
  emailVerified: boolean;
  banned?: boolean | null;
  mustChangePassword?: boolean | null;
  /** Public-profile publication status supplied by the host, independent of account access. */
  websitePublished?: boolean;
}
export type VerificationResult = { status: "sent" | "verified" | "unavailable" };
export type InvitationResult = { invitationSent: boolean };
export function isEmployeeAdmin(role: string | null | undefined): boolean {
  return role?.split(",").includes("admin") ?? false;
}

"use client";
import { Avatar } from "@base-ui/react/avatar";
import { ShieldCheckIcon, ShieldOffIcon } from "lucide-react";
import { useState } from "react";

import { ActionToastProvider } from "#/intranet/components/forge/action-toast.tsx";
import { IconTooltip } from "#/intranet/components/forge/icon-tooltip.tsx";
import { useLoadingActivity } from "#/intranet/components/forge/loading-indicator.tsx";
import {
  EmployeeActions,
  type EmployeeActionCallbacks,
} from "#/intranet/components/forge/plugins/employees/employee-actions.tsx";
import { EmployeeCreateDialog } from "#/intranet/components/forge/plugins/employees/employee-create-dialog.tsx";
import { EmployeeDeleteDialog } from "#/intranet/components/forge/plugins/employees/employee-delete-dialog.tsx";
import { EmployeeWebsiteStatus } from "#/intranet/components/forge/plugins/employees/employee-website-status.tsx";
export { EmployeeDeleteDialog } from "#/intranet/components/forge/plugins/employees/employee-delete-dialog";
export type {
  EmployeeDeletionAdapter,
  EmployeeDeletionGroup,
  EmployeeDeletionPreview,
  EmployeeDeletionDecisions,
  EmployeeDeleteDialogProps,
} from "#/intranet/components/forge/plugins/employees/employee-delete-dialog";
import { employeeLabels, type EmployeeLabels } from "#/intranet/components/forge/plugins/employees/labels.ts";
import {
  EMPLOYEE_PAGE_SIZE,
  isEmployeeAdmin,
  type CreateEmployee,
  type InvitationResult,
  type Employee,
} from "#/intranet/components/forge/plugins/employees/schema.ts";
import { TablePagination } from "#/intranet/components/forge/table-pagination.tsx";
import { matchesTableSearch, TableSearch } from "#/intranet/components/forge/table-search.tsx";
import {
  TableBulkDelete,
  TableSelectionCheckbox,
  useTableSelection,
} from "#/intranet/components/forge/table-selection.tsx";
import { cn } from "#/intranet/forge/utils.ts";
import {
  tableActionCellClass,
  tableActionHeaderClass,
  tableCellClass,
  tableClass,
  tableHeaderClass,
  tablePanelClass,
  tableRowClass,
} from "#/intranet/components/forge/utils/table-styles.ts";
import { retainRemovedItems, useOptimisticAction } from "#/intranet/components/forge/utils/use-optimistic-action.ts";
export { EmployeeCreateDialog } from "#/intranet/components/forge/plugins/employees/employee-create-dialog";
export { EmployeePhotoField } from "#/intranet/components/forge/plugins/employees/employee-photo-field";
export type { EmployeePhotoFieldProps } from "#/intranet/components/forge/plugins/employees/employee-photo-field";
export type {
  Employee,
  CreateEmployee,
  UpdateEmployee,
  VerificationResult,
  InvitationResult,
} from "#/intranet/components/forge/plugins/employees/schema";
export type { EmployeeLabels } from "#/intranet/components/forge/plugins/employees/labels";
export interface EmployeesPageProps extends EmployeeActionCallbacks {
  employees: readonly Employee[];
  /** For server pagination, filter the full directory before supplying this page. */
  search?: string;
  onSearchChange?: (search: string) => void;
  currentUserId: string;
  /** Role from the host's authenticated session. Missing or non-admin roles render nothing. */
  currentUserRole: string | null | undefined;
  total: number;
  offset: number;
  onOffsetChange: (offset: number) => void;
  onCreate: (values: CreateEmployee) => Promise<InvitationResult>;
  loading?: boolean;
  error?: boolean;
  labels?: Partial<EmployeeLabels>;
  className?: string;
}
function EmployeesPageContent({
  employees: suppliedEmployees,
  search: controlledSearch,
  onSearchChange,
  currentUserId,
  currentUserRole,
  total,
  offset,
  onOffsetChange,
  onCreate,
  loading = false,
  error = false,
  onUpdate,
  onSetWebsitePublished,
  onDelete,
  deletion,
  onUploadPhoto,
  photoOptions,
  onSendVerification,
  labels: overrides,
  className,
}: EmployeesPageProps) {
  useLoadingActivity(loading);
  const [localSearch, setLocalSearch] = useState("");
  const search = controlledSearch ?? localSearch;
  const optimistic = useOptimisticAction(suppliedEmployees, `${currentUserId}:${offset}:${search}`);
  const employees = optimistic.value;
  const visibleTotal = Math.max(0, total + employees.length - suppliedEmployees.length);
  const labels = { ...employeeLabels, ...overrides };
  // ponytail: fallback searches supplied rows; use onSearchChange for server pagination.
  const filteredEmployees = onSearchChange
    ? employees
    : employees.filter((employee) =>
        matchesTableSearch(
          search,
          employee.name,
          employee.email,
          isEmployeeAdmin(employee.role) ? labels.roleAdmin : labels.roleUser,
          employee.banned ? labels.disabled : labels.active,
          employee.emailVerified ? labels.verified : labels.unverified,
        ),
      );
  const selectable = isEmployeeAdmin(currentUserRole)
    ? filteredEmployees.filter(
        (employee) => employee.id !== currentUserId && !employee.id.startsWith("pending-"),
      )
    : [];
  const selection = useTableSelection(
    selectable,
    `${currentUserId}:${currentUserRole}:${offset}:${search}`,
  );
  const selectionDisabled = loading || error || optimistic.pending || selection.pending;
  if (!isEmployeeAdmin(currentUserRole)) return null;
  return (
    <section
      className={cn(tablePanelClass, "mx-auto w-full max-w-7xl px-0", className)}
      aria-label={labels.title}
    >
      <header className="flex flex-wrap items-center justify-between gap-4 px-6 pb-6">
        <h1 className="font-sans text-base font-semibold">{labels.title}</h1>
        <div className="ml-auto flex max-w-full flex-wrap items-center justify-end gap-2">
          <TableSearch
            value={search}
            label={labels.search}
            clearLabel={labels.clearSearch}
            onValueChange={(value) => {
              setLocalSearch(value);
              onSearchChange?.(value);
              if (onSearchChange) onOffsetChange(0);
            }}
          />
          <EmployeeCreateDialog
            currentUserRole={currentUserRole}
            disabled={selectionDisabled}
            onCreate={(values) => {
              const employee: Employee = {
                id: `pending-${crypto.randomUUID()}`,
                name: values.name,
                email: values.email,
                role: values.role,
                emailVerified: false,
              };
              return optimistic.run(
                (rows) => [employee, ...rows],
                () => onCreate(values),
              );
            }}
            labels={labels}
          />
        </div>
      </header>
      <div className="px-6">
        <div className="min-w-0 overflow-x-auto">
          <table className={tableClass} aria-busy={loading}>
            {loading && filteredEmployees.length > 0 && (
              <caption className="sr-only">
                <output>{labels.loading}</output>
              </caption>
            )}
            <thead className="[&_tr]:border-b">
              <tr className={tableRowClass}>
                <th scope="col" className="w-10 p-2">
                  <TableSelectionCheckbox
                    label={labels.selectAllRows}
                    checked={selection.all}
                    mixed={selection.mixed}
                    onChange={selection.toggleAll}
                    disabled={selectionDisabled || !selectable.length}
                  />
                </th>
                <th scope="col" className={tableHeaderClass}>
                  {labels.name}
                </th>
                <th scope="col" className={tableHeaderClass}>
                  {labels.email}
                </th>
                <th scope="col" className={tableHeaderClass}>
                  {labels.role}
                </th>
                <th scope="col" className={tableHeaderClass}>
                  {labels.status}
                </th>
                <th scope="col" className={tableHeaderClass}>
                  {labels.website}
                </th>
                <th scope="col" className={tableActionHeaderClass}>
                  <div className="flex items-center justify-end gap-2">
                    {labels.actions}
                    {deletion ? (
                      <EmployeeDeleteDialog
                        bulk
                        employees={selection.selected}
                        adapter={deletion}
                        labels={labels}
                        disabled={selectionDisabled}
                      />
                    ) : (
                      <TableBulkDelete
                        selection={selection}
                        getName={(employee) => employee.name}
                        onDelete={(employee) => onDelete(employee.id)}
                        labels={labels}
                        disabled={selectionDisabled}
                        description={labels.deleteDescription.replace(
                          "{name}",
                          selection.selected.map((row) => row.name).join(", "),
                        )}
                      />
                    )}
                  </div>
                </th>
              </tr>
            </thead>
            <tbody className="[&_tr:last-child]:border-0">
              {retainRemovedItems(filteredEmployees, suppliedEmployees, optimistic.pending).map(
                (employee) => (
                  <tr
                    key={employee.id}
                    hidden={
                      selection.isDeleting(employee.id) ||
                      !filteredEmployees.some((row) => row.id === employee.id)
                    }
                    className={tableRowClass}
                  >
                    <td className="w-10 p-2">
                      <TableSelectionCheckbox
                        label={`${labels.selectRow}: ${employee.name}`}
                        checked={selection.selected.some((row) => row.id === employee.id)}
                        mixed={false}
                        onChange={(checked) => selection.toggle(employee.id, checked)}
                        disabled={
                          selectionDisabled ||
                          !(employee.id !== currentUserId && !employee.id.startsWith("pending-"))
                        }
                      />
                    </td>
                    <td
                      aria-label={employee.name}
                      className={cn(tableCellClass, "whitespace-nowrap")}
                    >
                      <div className="flex items-center gap-3">
                        <Avatar.Root className="flex size-9 shrink-0 items-center justify-center overflow-hidden rounded-full border border-border">
                          <Avatar.Image
                            className="size-full object-cover"
                            src={employee.image ?? undefined}
                            alt=""
                          />
                          <Avatar.Fallback>
                            {employee.name
                              .trim()
                              .split(/\s+/)
                              .slice(0, 2)
                              .map((part) => part.charAt(0))
                              .join("")
                              .toUpperCase()}
                          </Avatar.Fallback>
                        </Avatar.Root>
                        <span className="max-w-48 truncate font-medium" title={employee.name}>
                          {employee.name}
                        </span>
                      </div>
                    </td>
                    <td
                      className={cn(tableCellClass, "whitespace-nowrap")}
                      aria-label={employee.email}
                    >
                      <div className="flex items-center gap-3">
                        <IconTooltip
                          label={employee.emailVerified ? labels.verified : labels.unverified}
                        >
                          <button
                            type="button"
                            aria-label={
                              employee.emailVerified ? labels.verified : labels.unverified
                            }
                            className={cn(
                              "inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring md:size-8",
                              employee.emailVerified
                                ? "bg-status-success text-status-success-foreground"
                                : "bg-status-pending text-status-pending-foreground",
                            )}
                          >
                            {employee.emailVerified ? (
                              <ShieldCheckIcon className="size-4 shrink-0" aria-hidden="true" />
                            ) : (
                              <ShieldOffIcon className="size-4 shrink-0" aria-hidden="true" />
                            )}
                          </button>
                        </IconTooltip>
                        <span className="max-w-72 truncate" title={employee.email}>
                          {employee.email}
                        </span>
                      </div>
                    </td>
                    <td className={cn(tableCellClass, "whitespace-nowrap")}>
                      {isEmployeeAdmin(employee.role) ? labels.roleAdmin : labels.roleUser}
                    </td>
                    <td className={cn(tableCellClass, "whitespace-nowrap")}>
                      <span
                        className={cn(
                          "inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-xs font-medium before:size-1.5 before:shrink-0 before:rounded-full before:bg-current",
                          employee.banned
                            ? "bg-status-canceled text-status-canceled-foreground"
                            : "bg-status-success text-status-success-foreground",
                        )}
                      >
                        {employee.banned ? labels.disabled : labels.active}
                      </span>
                    </td>
                    <td className={cn(tableCellClass, "whitespace-nowrap")}>
                      <EmployeeWebsiteStatus
                        published={employee.websitePublished}
                        labels={labels}
                      />
                    </td>
                    <td className={tableActionCellClass}>
                      <EmployeeActions
                        deletion={deletion}
                        onUploadPhoto={onUploadPhoto}
                        photoOptions={photoOptions}
                        employee={employee}
                        disabled={
                          loading ||
                          error ||
                          optimistic.pending ||
                          selection.pending ||
                          employee.id.startsWith("pending-")
                        }
                        currentUserId={currentUserId}
                        labels={labels}
                        onSetWebsitePublished={
                          onSetWebsitePublished
                            ? (id, published) =>
                                optimistic.run(
                                  (rows) =>
                                    rows.map((row) =>
                                      row.id === id ? { ...row, websitePublished: published } : row,
                                    ),
                                  () => onSetWebsitePublished(id, published),
                                )
                            : undefined
                        }
                        onUpdate={(values) =>
                          optimistic.run(
                            (rows) =>
                              rows.map((row) =>
                                row.id === values.id
                                  ? {
                                      ...row,
                                      ...values,
                                      emailVerified:
                                        row.email === values.email && row.emailVerified,
                                    }
                                  : row,
                              ),
                            () => onUpdate(values),
                          )
                        }
                        onDelete={(id) =>
                          optimistic.run(
                            (rows) => rows.filter((row) => row.id !== id),
                            () => onDelete(id),
                          )
                        }
                        onSendVerification={onSendVerification}
                      />
                    </td>
                  </tr>
                ),
              )}
              {((error && !loading) || optimistic.error || filteredEmployees.length === 0) && (
                <tr>
                  <td colSpan={7} className={cn(tableCellClass, "py-8")}>
                    {(error && !loading) || optimistic.error ? (
                      <p role="alert" className="text-destructive">
                        {error ? labels.error : labels.updateError}
                      </p>
                    ) : (
                      <output className="text-muted-foreground">
                        {loading ? labels.loading : search.trim() ? labels.noMatches : labels.empty}
                      </output>
                    )}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        <TablePagination
          disabled={selectionDisabled}
          summary={`${visibleTotal} ${labels.total}`}
          page={Math.floor(offset / EMPLOYEE_PAGE_SIZE) + 1}
          pageCount={Math.max(1, Math.ceil(total / EMPLOYEE_PAGE_SIZE))}
          label={labels.title}
          previousLabel={labels.previous}
          nextLabel={labels.next}
          previousDisabled={offset <= 0}
          nextDisabled={offset + EMPLOYEE_PAGE_SIZE >= total}
          onPrevious={() => onOffsetChange(Math.max(0, offset - EMPLOYEE_PAGE_SIZE))}
          onNext={() => onOffsetChange(offset + EMPLOYEE_PAGE_SIZE)}
        />
      </div>
    </section>
  );
}

export function EmployeesPage(props: EmployeesPageProps) {
  return (
    <ActionToastProvider>
      <EmployeesPageContent {...props} />
    </ActionToastProvider>
  );
}

"use client";

import { Dialog } from "@base-ui/react/dialog";
import { XIcon, RefreshCwIcon, Trash2Icon } from "lucide-react";
import { useRef, useState } from "react";

import { IconTooltip } from "#/intranet/components/forge/icon-tooltip.tsx";
import { Link } from "#/intranet/components/forge/ui/link.tsx";
import { useLoadingActivity } from "#/intranet/components/forge/loading-indicator.tsx";
import { NativeSelect } from "#/intranet/components/forge/native-select.tsx";
import { employeeLabels, type EmployeeLabels } from "#/intranet/components/forge/plugins/employees/labels.ts";
import {
  buttonClass,
  iconButtonClass,
  outlineButtonClass,
  dialogClass,
  inputClass,
} from "#/intranet/components/forge/plugins/employees/styles.ts";
import { cn } from "#/intranet/forge/utils.ts";

export interface EmployeeDeletionGroup {
  /** Unique across the preview, including when several employees are selected. */
  id: string;
  label: string;
  items: { id: string; title: string; href?: string; status?: string }[];
  choices: { id: string; label: string; description?: string; requiresReplacement?: boolean }[];
  replacements?: { id: string; name: string }[];
}
export interface EmployeeDeletionPreview {
  /** Opaque host-issued version/fingerprint, revalidated at confirmation. */
  token: string;
  groups: EmployeeDeletionGroup[];
}
export type EmployeeDeletionDecisions = Record<string, { choice: string; replacementId?: string }>;
export interface EmployeeDeletionAdapter {
  preview: (employeeIds: string[]) => Promise<EmployeeDeletionPreview>;
  /** Atomically validate the preview, process all groups and remove the accounts. */
  confirm: (
    employeeIds: string[],
    token: string,
    decisions: EmployeeDeletionDecisions,
  ) => Promise<void>;
}
export interface EmployeeDeleteDialogProps {
  employees: readonly { id: string; name: string }[];
  adapter: EmployeeDeletionAdapter;
  labels?: Partial<EmployeeLabels>;
  disabled?: boolean;
  bulk?: boolean;
  className?: string;
}
export function EmployeeDeleteDialog({
  employees,
  adapter,
  labels: overrides,
  disabled,
  bulk = false,
  className,
}: EmployeeDeleteDialogProps) {
  const labels = { ...employeeLabels, ...overrides };
  const [open, setOpen] = useState(false);
  const [preview, setPreview] = useState<EmployeeDeletionPreview | null>(null);
  const [targets, setTargets] = useState<typeof employees>([]);
  const [decisions, setDecisions] = useState<EmployeeDeletionDecisions>({});
  const [status, setStatus] = useState<"idle" | "loading" | "error" | "saving">("idle");
  const generation = useRef(0);
  useLoadingActivity(open && status === "loading");
  const saving = useRef(false);
  async function load(selected = targets) {
    const request = ++generation.current;
    setPreview(null);
    setDecisions({});
    setStatus("loading");
    try {
      const result = await adapter.preview(selected.map((employee) => employee.id));
      if (request === generation.current) {
        setPreview(result);
        setStatus("idle");
      }
    } catch {
      if (request === generation.current) setStatus("error");
    }
  }
  const ready =
    preview &&
    preview.groups.every((group) => {
      const decision = decisions[group.id];
      const choice = group.choices.find((item) => item.id === decision?.choice);
      return (
        choice &&
        (!choice.requiresReplacement ||
          group.replacements?.some((person) => person.id === decision.replacementId))
      );
    });
  const pending = status === "loading" || status === "saving";
  const actionLabel =
    !bulk && employees.length === 1
      ? `${labels.delete} ${employees[0].name}`
      : labels.deleteSelected;
  return (
    <Dialog.Root
      open={open}
      onOpenChange={(next) => {
        if (saving.current) return;
        setOpen(next);
        if (next) {
          setTargets([...employees]);
          void load(employees);
        } else {
          generation.current++;
          setPreview(null);
        }
      }}
    >
      <IconTooltip label={actionLabel}>
        <Dialog.Trigger
          aria-label={actionLabel}
          disabled={disabled || !employees.length}
          className={cn(
            iconButtonClass,
            "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
            className,
          )}
        >
          <Trash2Icon className="size-4" aria-hidden="true" />
        </Dialog.Trigger>
      </IconTooltip>
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup className={cn(dialogClass, "max-h-[90dvh]")}>
          <div
            data-dialog-header
            className="sticky top-0 z-20 -mx-6 mb-0 flex items-start justify-between gap-3 bg-background px-6 pt-5 pb-2"
          >
            <Dialog.Title className="min-w-0 flex-1 text-lg font-semibold break-words">
              {labels.deleteTitle}
            </Dialog.Title>
            <IconTooltip label={labels.close}>
              <Dialog.Close
                type="button"
                aria-label={labels.close}
                disabled={status === "saving"}
                className="inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-md text-foreground hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50 md:size-8"
              >
                <XIcon className="size-4 shrink-0" aria-hidden="true" />
              </Dialog.Close>
            </IconTooltip>
          </div>
          <Dialog.Description className="text-sm text-muted-foreground">
            {labels.deleteDescription.replace(
              "{name}",
              targets.map((employee) => employee.name).join(", "),
            )}
          </Dialog.Description>
          {status === "loading" && <output>{labels.loadingRelatedData}</output>}
          {status === "error" && (
            <p role="alert" className="text-destructive">
              {labels.deleteError}
            </p>
          )}
          {preview?.groups.map((group) => (
            <fieldset
              key={group.id}
              disabled={pending}
              className="grid gap-3 border-t border-border pt-4"
            >
              <legend className="font-semibold">{group.label}</legend>
              <details>
                <summary className="cursor-pointer text-sm focus-visible:outline-2 focus-visible:outline-ring">
                  {labels.relatedItems} ({group.items.length})
                </summary>
                <ul className="mt-2 max-h-48 space-y-2 overflow-auto text-sm">
                  {group.items.map((item) => (
                    <li key={item.id}>
                      {item.href ? (
                        <Link
                          href={item.href}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-primary underline"
                        >
                          {item.title}
                        </Link>
                      ) : (
                        item.title
                      )}
                      {item.status && (
                        <span className="ml-2 text-muted-foreground">{item.status}</span>
                      )}
                    </li>
                  ))}
                </ul>
              </details>
              {group.choices.map((choice) => (
                <label key={choice.id} className="flex gap-2 text-sm">
                  <input
                    type="radio"
                    name={`factory-delete-${group.id}`}
                    value={choice.id}
                    checked={decisions[group.id]?.choice === choice.id}
                    onChange={() =>
                      setDecisions({ ...decisions, [group.id]: { choice: choice.id } })
                    }
                  />
                  <span>
                    {choice.label}
                    {choice.description && (
                      <span className="mt-1 block text-muted-foreground">{choice.description}</span>
                    )}
                  </span>
                </label>
              ))}
              {group.choices.find((choice) => choice.id === decisions[group.id]?.choice)
                ?.requiresReplacement && (
                <label className="grid gap-2 text-sm">
                  {labels.replacement}
                  <NativeSelect
                    aria-label={labels.replacement}
                    className={inputClass}
                    value={decisions[group.id]?.replacementId ?? ""}
                    onChange={(event) =>
                      setDecisions({
                        ...decisions,
                        [group.id]: { ...decisions[group.id], replacementId: event.target.value },
                      })
                    }
                  >
                    <option value="">{labels.chooseReplacement}</option>
                    {group.replacements?.map((person) => (
                      <option key={person.id} value={person.id}>
                        {person.name}
                      </option>
                    ))}
                  </NativeSelect>
                </label>
              )}
            </fieldset>
          ))}
          <div
            data-dialog-footer
            className="sticky bottom-0 z-10 -mx-6 flex flex-wrap justify-end gap-2 bg-background px-6 pt-0 pb-5"
          >
            <Dialog.Close className={outlineButtonClass} disabled={status === "saving"}>
              {labels.cancel}
            </Dialog.Close>
            {status === "error" && (
              <IconTooltip label={labels.reloadRelatedData}>
                <button
                  aria-label={labels.reloadRelatedData}
                  type="button"
                  className={iconButtonClass}
                  onClick={() => void load()}
                >
                  <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
                </button>
              </IconTooltip>
            )}
            <button
              type="button"
              className={cn(buttonClass, "bg-destructive/10 text-destructive")}
              disabled={pending || !ready || status === "error"}
              onClick={async () => {
                if (saving.current || !preview || !ready) return;
                saving.current = true;
                setStatus("saving");
                try {
                  await adapter.confirm(
                    targets.map((employee) => employee.id),
                    preview.token,
                    decisions,
                  );
                  setOpen(false);
                  setPreview(null);
                  setStatus("idle");
                } catch {
                  setStatus("error");
                } finally {
                  saving.current = false;
                }
              }}
            >
              {status === "saving" ? labels.deleting : labels.delete}
            </button>
          </div>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

"use client";
import { Dialog } from "@base-ui/react/dialog";
import { XIcon, PlusIcon } from "lucide-react";
import { useId, useState } from "react";

import { IconTooltip } from "#/intranet/components/forge/icon-tooltip.tsx";
import { NativeSelect } from "#/intranet/components/forge/native-select.tsx";
import { employeeLabels, type EmployeeLabels } from "#/intranet/components/forge/plugins/employees/labels.ts";
import {
  createEmployeeSchema,
  isEmployeeAdmin,
  type CreateEmployee,
  type InvitationResult,
} from "#/intranet/components/forge/plugins/employees/schema.ts";
import {
  dialogClass,
  inputClass,
  outlineButtonClass,
  primaryButtonClass,
} from "#/intranet/components/forge/plugins/employees/styles.ts";
import { cn } from "#/intranet/forge/utils.ts";
import { submitDialogOnShortcut } from "#/intranet/components/forge/utils/dialog-submit.ts";
import { useMutationAction } from "#/intranet/components/forge/utils/use-optimistic-action.ts";

export interface EmployeeCreateDialogProps {
  /** Role from the host's authenticated session. Missing or non-admin roles render nothing. */
  currentUserRole: string | null | undefined;
  onCreate: (values: CreateEmployee) => Promise<InvitationResult>;
  labels?: Partial<EmployeeLabels>;
  className?: string;
  disabled?: boolean;
}

export function EmployeeCreateDialog({
  currentUserRole,
  onCreate,
  labels: overrides,
  className,
  disabled = false,
}: EmployeeCreateDialogProps) {
  const labels = { ...employeeLabels, ...overrides };
  const id = `factory-employee-create-${useId()}`;
  const [open, setOpen] = useState(false);
  const mutation = useMutationAction(currentUserRole);
  const pending = mutation.pending;
  const [failed, setFailed] = useState(false);
  const [deliveryFailed, setDeliveryFailed] = useState(false);
  if (!isEmployeeAdmin(currentUserRole)) return null;

  async function submit(form: HTMLFormElement) {
    if (pending) return;
    const data = new FormData(form);
    setFailed(false);
    const accepted = await mutation.run(
      async () => onCreate(createEmployeeSchema.parse(Object.fromEntries(data))),
      (result) => {
        form.reset();
        setDeliveryFailed(!result.invitationSent);
        if (result.invitationSent) setOpen(false);
      },
    );
    if (!accepted && mutation.isCurrent()) setFailed(true);
  }

  return (
    <Dialog.Root
      open={open}
      onOpenChange={(next) => {
        if (pending) return;
        setFailed(false);
        setDeliveryFailed(false);
        setOpen(next);
      }}
    >
      <Dialog.Trigger className={cn(primaryButtonClass, className)} disabled={disabled}>
        <PlusIcon className="size-4 shrink-0" aria-hidden="true" />
        {labels.add}
      </Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup className={dialogClass} onKeyDownCapture={submitDialogOnShortcut}>
          <div
            data-dialog-header
            className="sticky top-0 z-20 -mx-6 space-y-2 bg-background px-6 pt-5 pb-0"
          >
            <div className="flex items-start justify-between gap-3">
              <Dialog.Title className="min-w-0 flex-1 text-lg font-semibold break-words">
                {labels.add}
              </Dialog.Title>
              <IconTooltip label={labels.close}>
                <Dialog.Close
                  type="button"
                  aria-label={labels.close}
                  disabled={pending}
                  className="inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-md text-foreground hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50 md:size-8"
                >
                  <XIcon className="size-4 shrink-0" aria-hidden="true" />
                </Dialog.Close>
              </IconTooltip>
            </div>
            <Dialog.Description className="text-sm text-muted-foreground">
              {labels.instructions}
            </Dialog.Description>
          </div>
          {deliveryFailed ? (
            <div className="contents space-y-4">
              <p role="alert">{labels.invitationFailed}</p>
              <div
                data-dialog-footer
                className="sticky bottom-0 z-10 -mx-6 flex justify-end bg-background px-6 pt-0 pb-5"
              >
                <Dialog.Close className={outlineButtonClass}>{labels.close}</Dialog.Close>
              </div>
            </div>
          ) : (
            <form
              className="contents space-y-4"
              onSubmit={(event) => {
                event.preventDefault();
                void submit(event.currentTarget);
              }}
            >
              <div className="grid gap-2">
                <label htmlFor={`${id}-name`}>
                  {labels.name} <span aria-hidden="true">*</span>
                </label>
                <input
                  className={inputClass}
                  id={`${id}-name`}
                  name="name"
                  autoComplete="name"
                  maxLength={200}
                  required
                  readOnly={pending}
                />
              </div>
              <div className="grid gap-2">
                <label htmlFor={`${id}-email`}>
                  {labels.email} <span aria-hidden="true">*</span>
                </label>
                <input
                  className={inputClass}
                  id={`${id}-email`}
                  name="email"
                  type="email"
                  autoComplete="email"
                  required
                  readOnly={pending}
                />
              </div>
              <div className="grid gap-2">
                <label htmlFor={`${id}-role`}>{labels.role}</label>
                <NativeSelect
                  id={`${id}-role`}
                  name="role"
                  defaultValue="user"
                  disabled={pending}
                  className={inputClass}
                >
                  <option value="user">{labels.roleUser}</option>
                  <option value="admin">{labels.roleAdmin}</option>
                </NativeSelect>
              </div>
              {failed && (
                <p role="alert" className="text-destructive">
                  {labels.createError}
                </p>
              )}
              <div
                data-dialog-footer
                className="sticky bottom-0 z-10 -mx-6 flex flex-wrap justify-end gap-3 bg-background px-6 pt-0 pb-5"
              >
                <Dialog.Close type="button" className={outlineButtonClass} disabled={pending}>
                  {labels.cancel}
                </Dialog.Close>
                <button className={primaryButtonClass} type="submit" disabled={pending}>
                  {pending ? labels.adding : labels.save}
                </button>
              </div>
            </form>
          )}
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

import { cn } from "#/intranet/forge/utils.ts";

export const inputClass =
  "h-10 w-full min-w-0 rounded-lg border border-input bg-background px-3 text-base text-foreground placeholder:text-muted-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50 aria-invalid:ring-2 aria-invalid:ring-destructive md:text-sm";
export const buttonClass =
  "inline-flex min-h-10 items-center justify-center gap-2 rounded-md px-3 text-sm font-medium transition-colors md:min-h-8 outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 disabled:bg-background disabled:text-foreground disabled:hover:bg-background disabled:hover:text-foreground [&_svg]:size-4 cursor-pointer disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed";
export const primaryButtonClass = `${buttonClass} bg-primary text-primary-foreground hover:bg-primary/90`;
export const outlineButtonClass = `${buttonClass} border border-border hover:bg-accent`;
export const iconButtonClass = cn(
  buttonClass,
  "size-10 min-h-10 shrink-0 border border-border bg-background p-0 hover:bg-accent hover:text-accent-foreground disabled:pointer-events-auto md:size-8 md:min-h-8",
);
export const dialogClass =
  "fixed max-h-[calc(100dvh-2rem)] scroll-pt-56 scroll-pb-32 overflow-y-auto top-1/2 left-1/2 z-50 w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 space-y-4 rounded-xl border border-border bg-background px-6 text-foreground shadow-lg";

import type { EmployeeLabels } from "#/intranet/components/forge/plugins/employees/labels.ts";
import { cn } from "#/intranet/forge/utils.ts";

export interface EmployeeWebsiteStatusProps {
  published: boolean | undefined;
  labels: Pick<EmployeeLabels, "websiteVisible" | "websiteHidden" | "websiteUnknown">;
  className?: string;
}

export function EmployeeWebsiteStatus({
  published,
  labels,
  className,
}: EmployeeWebsiteStatusProps) {
  if (published === undefined)
    return <span className={cn("text-muted-foreground", className)}>{labels.websiteUnknown}</span>;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-xs font-medium before:size-1.5 before:shrink-0 before:rounded-full before:bg-current",
        published
          ? "bg-status-success text-status-success-foreground"
          : "bg-status-not-started text-status-not-started-foreground",
        className,
      )}
    >
      {published ? labels.websiteVisible : labels.websiteHidden}
    </span>
  );
}

"use client";
import { Dialog } from "@base-ui/react/dialog";
import { XIcon, PencilIcon, SendHorizontalIcon, Trash2Icon } from "lucide-react";
import { useId, useState } from "react";

import { useActionToast, ActionToastProvider } from "#/intranet/components/forge/action-toast.tsx";
import { IconTooltip } from "#/intranet/components/forge/icon-tooltip.tsx";
import { NativeSelect } from "#/intranet/components/forge/native-select.tsx";
import {
  EmployeeDeleteDialog,
  type EmployeeDeletionAdapter,
} from "#/intranet/components/forge/plugins/employees/employee-delete-dialog.tsx";
import {
  EmployeePhotoField,
  type EmployeePhotoFieldProps,
} from "#/intranet/components/forge/plugins/employees/employee-photo-field.tsx";
import { EmployeeWebsiteStatus } from "#/intranet/components/forge/plugins/employees/employee-website-status.tsx";
import { employeeLabels, type EmployeeLabels } from "#/intranet/components/forge/plugins/employees/labels.ts";
import {
  isEmployeeAdmin,
  updateEmployeeSchema,
  type Employee,
  type UpdateEmployee,
  type VerificationResult,
} from "#/intranet/components/forge/plugins/employees/schema.ts";
import {
  buttonClass,
  iconButtonClass,
  primaryButtonClass,
  outlineButtonClass,
  inputClass,
  dialogClass,
} from "#/intranet/components/forge/plugins/employees/styles.ts";
import { cn } from "#/intranet/forge/utils.ts";
import { submitDialogOnShortcut } from "#/intranet/components/forge/utils/dialog-submit.ts";
import { tableActionsClass } from "#/intranet/components/forge/utils/table-styles.ts";
import { useMutationAction } from "#/intranet/components/forge/utils/use-optimistic-action.ts";
export interface EmployeeActionCallbacks {
  deletion?: EmployeeDeletionAdapter;
  onUploadPhoto?: (id: string, file: File) => Promise<void>;
  photoOptions?: Pick<EmployeePhotoFieldProps, "dimensions" | "labels" | "cropLabels">;
  onUpdate: (values: UpdateEmployee) => Promise<void>;
  /** Persist public-profile visibility and refresh the host's employee data. */
  onSetWebsitePublished?: (id: string, published: boolean) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
  /** @deprecated The employee list no longer provides an access toggle. */
  onSetBan?: (id: string, banned: boolean) => Promise<void>;
  onSendVerification: (id: string) => Promise<VerificationResult>;
}
export interface EmployeeActionsProps extends EmployeeActionCallbacks {
  employee: Employee;
  currentUserId: string;
  labels?: Partial<EmployeeLabels>;
  className?: string;
  disabled?: boolean;
}
function EmployeeActionsContent({
  employee,
  currentUserId,
  onUpdate,
  onSetWebsitePublished,
  onDelete,
  deletion,
  onUploadPhoto,
  photoOptions,
  onSendVerification,
  labels: overrides,
  className,
  disabled = false,
}: EmployeeActionsProps) {
  const labels = { ...employeeLabels, ...overrides };
  const id = `factory-employee-edit-${useId()}`;
  const [editing, setEditing] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const mutation = useMutationAction(`${currentUserId}:${employee.id}`);
  const pending = mutation.pending;
  const [actionKind, setFailedAction] = useState<string | null>(null);
  const failedAction = mutation.error ? actionKind : null;
  const [feedback, setFeedback] = useState<{ error: boolean; message: string } | null>(null);
  const notify = useActionToast();
  const isSelf = employee.id === currentUserId;
  const emailAction = employee.mustChangePassword ? labels.sendInvitation : labels.sendEmail;
  function run<T>(
    kind: "edit" | "remove" | "send" | "website",
    action: () => Promise<T>,
    accept?: (result: T) => void,
  ) {
    if (disabled || pending) return;
    setFailedAction(kind);
    setFeedback(null);
    return mutation.run(action, accept);
  }
  return (
    <div className={cn("flex flex-col items-end gap-1", className)}>
      <div className={tableActionsClass}>
        <IconTooltip label={`${emailAction} ${employee.name}`}>
          <button
            type="button"
            className={iconButtonClass}

            disabled={
              disabled ||
              pending ||
              employee.banned ||
              (!employee.mustChangePassword && employee.emailVerified)
            }
            aria-label={`${emailAction} ${employee.name}`}
            onClick={() =>
              void run(
                "send",
                () => onSendVerification(employee.id),
                ({ status }) => {
                  if (status === "unavailable") {
                    setFeedback({ error: true, message: labels.emailUnavailable });
                  } else {
                    notify(
                      status === "verified"
                        ? labels.verified
                        : employee.mustChangePassword
                          ? labels.invitationSent
                          : labels.emailSent,
                    );
                  }
                },
              )
            }
          >
            <SendHorizontalIcon aria-hidden="true" />
          </button>
        </IconTooltip>
        <Dialog.Root
          open={editing}
          onOpenChange={(open) => {
            if (!pending) {
              setFailedAction(null);
              setEditing(open);
            }
          }}
        >
          <IconTooltip label={`${labels.edit} ${employee.name}`}>
            <Dialog.Trigger
              disabled={disabled || pending}
              className={iconButtonClass}

              aria-label={`${labels.edit} ${employee.name}`}
            >
              <PencilIcon className="size-4 shrink-0" aria-hidden="true" />
            </Dialog.Trigger>
          </IconTooltip>
          <Dialog.Portal>
            <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
            <Dialog.Popup
              className={cn(dialogClass, "max-h-[90dvh]")}
              onKeyDownCapture={submitDialogOnShortcut}
            >
              <div
                data-dialog-header
                className="sticky top-0 z-20 -mx-6 space-y-2 bg-background px-6 pt-5 pb-0"
              >
                <div className="flex items-start gap-3">
                  <div className="flex min-w-0 flex-1 flex-wrap items-start justify-between gap-3">
                    <Dialog.Title className="text-lg font-semibold">
                      {labels.editTitle}
                    </Dialog.Title>
                    {employee.websitePublished !== undefined &&
                      (onSetWebsitePublished ? (
                        <button
                          type="button"
                          aria-label={labels.website}
                          aria-pressed={employee.websitePublished}
                          disabled={disabled || pending}
                          className="ml-auto inline-flex min-h-10 cursor-pointer items-center rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50 md:min-h-8"
                          onClick={() =>
                            void run(
                              "website",
                              () => onSetWebsitePublished(employee.id, !employee.websitePublished),
                              () => notify(labels.websiteUpdated),
                            )
                          }
                        >
                          <EmployeeWebsiteStatus
                            published={employee.websitePublished}
                            labels={labels}
                          />
                        </button>
                      ) : (
                        <EmployeeWebsiteStatus
                          published={employee.websitePublished}
                          labels={labels}
                          className="ml-auto"
                        />
                      ))}
                  </div>
                  <IconTooltip label={labels.close}>
                    <Dialog.Close
                      type="button"
                      aria-label={labels.close}
                      disabled={pending}
                      className={iconButtonClass}
                    >
                      <XIcon className="size-4 shrink-0" aria-hidden="true" />
                    </Dialog.Close>
                  </IconTooltip>
                </div>
                <Dialog.Description className="text-sm text-muted-foreground">
                  {labels.editDescription}
                </Dialog.Description>
                {failedAction === "website" && (
                  <p role="alert" className="text-sm text-destructive">
                    {labels.websiteError}
                  </p>
                )}
              </div>
              <form
                className="contents space-y-4"
                onSubmit={(event) => {
                  event.preventDefault();
                  const data = new FormData(event.currentTarget);
                  void run(
                    "edit",
                    async () => {
                      await onUpdate(
                        updateEmployeeSchema.parse({
                          ...Object.fromEntries(data),
                          id: employee.id,
                          role: isSelf ? "admin" : data.get("role"),
                        }),
                      );
                    },
                    () => {
                      notify(labels.updated);
                      setEditing(false);
                    },
                  );
                }}
              >
                {onUploadPhoto && (
                  <EmployeePhotoField
                    {...photoOptions}
                    src={employee.image}
                    disabled={disabled || pending}
                    onUpload={(file) => onUploadPhoto(employee.id, file)}
                  />
                )}
                <div className="grid gap-2">
                  <label htmlFor={`${id}-name`}>
                    {labels.name} <span aria-hidden="true">*</span>
                  </label>
                  <input
                    className={inputClass}
                    id={`${id}-name`}
                    name="name"
                    defaultValue={employee.name}
                    maxLength={200}
                    required
                    readOnly={pending}
                  />
                </div>
                <div className="grid gap-2">
                  <label htmlFor={`${id}-email`}>
                    {labels.email} <span aria-hidden="true">*</span>
                  </label>
                  <input
                    className={inputClass}
                    id={`${id}-email`}
                    name="email"
                    type="email"
                    defaultValue={employee.email}
                    required
                    readOnly={pending}
                  />
                </div>
                <div className="grid gap-2">
                  <label htmlFor={`${id}-role`}>{labels.role}</label>
                  <NativeSelect
                    id={`${id}-role`}
                    name="role"
                    defaultValue={isEmployeeAdmin(employee.role) ? "admin" : "user"}
                    disabled={pending || isSelf}
                    className={inputClass}
                  >
                    <option value="user">{labels.roleUser}</option>
                    <option value="admin">{labels.roleAdmin}</option>
                  </NativeSelect>
                </div>
                {failedAction === "edit" && (
                  <p role="alert" className="text-destructive">
                    {labels.editError}
                  </p>
                )}
                <div
                  data-dialog-footer
                  className="sticky bottom-0 z-10 -mx-6 flex flex-wrap justify-end gap-3 bg-background px-6 pt-0 pb-5"
                >
                  <button
                    type="button"
                    className={outlineButtonClass}
                    disabled={pending}
                    onClick={() => setEditing(false)}
                  >
                    {labels.cancel}
                  </button>
                  <button
                    type="submit"
                    className={primaryButtonClass}
                    disabled={disabled || pending}
                  >
                    {pending ? labels.saving : labels.saveChanges}
                  </button>
                </div>
              </form>
            </Dialog.Popup>
          </Dialog.Portal>
        </Dialog.Root>
        {deletion ? (
          <EmployeeDeleteDialog
            employees={[employee]}
            adapter={deletion}
            labels={labels}
            disabled={disabled || pending || isSelf}
          />
        ) : (
          <Dialog.Root
            open={deleting}
            onOpenChange={(open) => {
              if (!pending) {
                setFailedAction(null);
                setDeleting(open);
              }
            }}
          >
            <IconTooltip label={`${labels.delete} ${employee.name}`}>
              <Dialog.Trigger
                disabled={disabled || pending || isSelf}
                className={cn(
                  iconButtonClass,
                  "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
                )}
                aria-label={`${labels.delete} ${employee.name}`}
              >
                <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
              </Dialog.Trigger>
            </IconTooltip>
            <Dialog.Portal>
              <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
              <Dialog.Popup className={dialogClass}>
                <div
                  data-dialog-header
                  className="sticky top-0 z-20 -mx-6 space-y-2 bg-background px-6 pt-5 pb-0"
                >
                  <div className="flex items-start justify-between gap-3">
                    <Dialog.Title className="min-w-0 flex-1 text-lg font-semibold break-words">
                      {labels.deleteTitle}
                    </Dialog.Title>
                    <IconTooltip label={labels.close}>
                      <Dialog.Close
                        type="button"
                        aria-label={labels.close}
                        disabled={pending}
                        className={iconButtonClass}
                      >
                        <XIcon className="size-4 shrink-0" aria-hidden="true" />
                      </Dialog.Close>
                    </IconTooltip>
                  </div>
                  <Dialog.Description className="text-sm text-muted-foreground">
                    {labels.deleteDescription.replace("{name}", employee.name)}
                  </Dialog.Description>
                </div>
                {failedAction === "remove" && (
                  <p role="alert" className="text-destructive">
                    {labels.deleteError}
                  </p>
                )}
                <div
                  data-dialog-footer
                  className="sticky bottom-0 z-10 -mx-6 flex flex-wrap justify-end gap-3 bg-background px-6 pt-0 pb-5"
                >
                  <button
                    type="button"
                    className={outlineButtonClass}
                    disabled={pending}
                    onClick={() => setDeleting(false)}
                  >
                    {labels.cancel}
                  </button>
                  <button
                    type="button"
                    className={cn(
                      buttonClass,
                      "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
                    )}
                    disabled={disabled || pending || isSelf}
                    onClick={() =>
                      void run(
                        "remove",
                        () => onDelete(employee.id),
                        () => setDeleting(false),
                      )
                    }
                  >
                    {pending ? labels.deleting : labels.delete}
                  </button>
                </div>
              </Dialog.Popup>
            </Dialog.Portal>
          </Dialog.Root>
        )}
      </div>
      {failedAction === "send" && (
        <p role="alert" className="text-xs text-destructive">
          {labels.emailError}
        </p>
      )}
      {feedback && (
        <p
          role={feedback.error ? "alert" : "status"}
          className={cn(
            "max-w-60 text-xs whitespace-normal",
            feedback.error ? "text-destructive" : "text-muted-foreground",
          )}
        >
          {feedback.message}
        </p>
      )}
    </div>
  );
}

export function EmployeeActions(props: EmployeeActionsProps) {
  return (
    <ActionToastProvider>
      <EmployeeActionsContent key={`${props.currentUserId}:${props.employee.id}`} {...props} />
    </ActionToastProvider>
  );
}

"use client";

import { UploadIcon, UserRoundIcon } from "lucide-react";
import { useId, useRef, useState } from "react";

import { Image } from "#/intranet/components/forge/ui/image.tsx";
import { ImageCropDialog, type ImageCropLabels, type ImageCropSize } from "#/intranet/components/forge/image-crop.tsx";
import { outlineButtonClass } from "#/intranet/components/forge/plugins/employees/styles.ts";
import { cn } from "#/intranet/forge/utils.ts";

export const employeePhotoLabels = {
  label: "Employee photo",
  /** @deprecated The photo picker no longer displays helper text. */
  hint: "",
  missing: "No photo",
  choose: "Choose photo",
  change: "Change photo",
};
export interface EmployeePhotoFieldProps {
  src?: string | null;
  onUpload: (file: File) => Promise<void>;
  dimensions?: ImageCropSize;
  labels?: Partial<typeof employeePhotoLabels>;
  cropLabels?: Partial<ImageCropLabels>;
  disabled?: boolean;
  className?: string;
}
/** Optional employee media; the host owns storage, validation and persistence. */
export function EmployeePhotoField({
  src,
  onUpload,
  dimensions = { width: 512, height: 512 },
  labels: overrides,
  cropLabels,
  disabled,
  className,
}: EmployeePhotoFieldProps) {
  const labels = { ...employeePhotoLabels, ...overrides };
  const id = `factory-employee-photo-${useId()}`;
  const input = useRef<HTMLInputElement>(null);
  const [file, setFile] = useState<File | null>(null);
  return (
    <div className={cn("grid gap-3", className)}>
      <label htmlFor={id} className="text-sm font-medium">
        {labels.label}
      </label>
      <div className="flex items-center gap-4">
        <div className="flex size-20 shrink-0 items-center justify-center overflow-hidden rounded-lg border border-border bg-muted">
          {src ? (
            <Image
              src={src}
              alt={labels.label}
              width={80}
              height={80}
              className="size-full object-cover"
            />
          ) : (
            <>
              <UserRoundIcon aria-hidden="true" className="size-8 text-muted-foreground" />
              <span className="sr-only">{labels.missing}</span>
            </>
          )}
        </div>
        <button
          type="button"
          className={cn(outlineButtonClass, "min-w-0 py-2 disabled:pointer-events-auto")}
          disabled={disabled || !!file}
          onClick={() => input.current?.click()}
        >
          <UploadIcon aria-hidden="true" className="size-4 shrink-0" />
          {src ? labels.change : labels.choose}
        </button>
      </div>
      <input
        ref={input}
        id={id}
        type="file"
        accept="image/jpeg,image/png,image/webp"
        disabled={disabled || !!file}
        className="hidden"
        onChange={(event) => {
          setFile(event.target.files?.[0] ?? null);
          event.target.value = "";
        }}
      />
      {file && (
        <ImageCropDialog
          file={file}
          {...dimensions}
          labels={cropLabels}
          onCancel={() => setFile(null)}
          onConfirm={async (cropped) => {
            await onUpload(cropped);
            setFile(null);
          }}
        />
      )}
    </div>
  );
}

import {
  createEmployeeSchema,
  employeeIdSchema,
  EMPLOYEE_PAGE_SIZE,
  isEmployeeAdmin,
  listEmployeesSchema,
  setEmployeeBanSchema,
  updateEmployeeSchema,
  type Employee,
  type CreateEmployee,
  type UpdateEmployee,
  type VerificationResult,
} from "#/intranet/components/forge/plugins/employees/schema.ts";

/** Structural subset of Better Auth's admin API; the host owns its auth instance. */
export interface EmployeesAuthApi {
  listUsers(input: {
    headers: Headers;
    query: { limit: number; offset: number; sortBy: string; sortDirection: "asc" };
  }): Promise<{ users: Employee[]; total: number }>;
  createUser(input: {
    headers: Headers;
    body: CreateEmployee & { data: { mustChangePassword: boolean } };
  }): Promise<{ user: Employee }>;
  getUser(input: { headers: Headers; query: { id: string } }): Promise<Employee>;
  adminUpdateUser(input: {
    headers: Headers;
    body: {
      userId: string;
      data: { name: string; email: string; role: string; emailVerified?: boolean };
    };
  }): Promise<Employee>;
  banUser(input: { headers: Headers; body: { userId: string } }): Promise<{ user: Employee }>;
  unbanUser(input: { headers: Headers; body: { userId: string } }): Promise<{ user: Employee }>;
  removeUser(input: { headers: Headers; body: { userId: string } }): Promise<unknown>;
  sendVerificationEmail(input: { body: { email: string; callbackURL: string } }): Promise<unknown>;
}
export interface EmployeeActor {
  id: string;
  role?: string | null;
  banned?: boolean | null;
  mustChangePassword?: boolean | null;
}
export interface EmployeeServiceOptions {
  api: EmployeesAuthApi;
  headers: Headers;
  /** A freshly authenticated server session, never client input. Create per request. */
  actor: EmployeeActor | null;
  verificationEnabled: boolean;
  /** Issue an expiring single-use link and await delivery; reject when sending fails. */
  sendInvitation: (employee: Employee, invitationURL: string) => Promise<void>;
  /** Replace provider deletion with the host's atomic retention/account transaction. */
  removeEmployee?: (id: string, decision: unknown) => Promise<void>;
  /** Required when Customers is installed: exclude profiles before pagination and mutations. */
  directory?: {
    list(offset: number, limit: number): Promise<{ users: Employee[]; total: number }>;
    contains(id: string): Promise<boolean>;
  };
}

export function createEmployeeService({
  api,
  headers,
  actor,
  verificationEnabled,
  sendInvitation,
  removeEmployee,
  directory,
}: EmployeeServiceOptions) {
  if (!actor || actor.banned || actor.mustChangePassword || !isEmployeeAdmin(actor.role)) {
    throw new Error("Administrator access required.");
  }
  const actorId = actor.id;
  async function requireEmployee(id = actorId) {
    if (directory && (!(await directory.contains(actorId)) || !(await directory.contains(id))))
      throw new Error("Employee access required.");
  }
  return {
    list(input: unknown) {
      const { offset } = listEmployeesSchema.parse(input);
      return requireEmployee().then(() => {
        if (directory) return directory.list(offset, EMPLOYEE_PAGE_SIZE);
        return api.listUsers({
          headers,
          query: { limit: EMPLOYEE_PAGE_SIZE, offset, sortBy: "name", sortDirection: "asc" },
        });
      });
    },
    async create(input: unknown, invitationURL: string) {
      const data = createEmployeeSchema.parse(input);
      await requireEmployee();
      if (!verificationEnabled) throw new Error("Email delivery is not configured.");
      const { user } = await api.createUser({
        headers,
        body: { ...data, data: { mustChangePassword: true } },
      });
      try {
        await sendInvitation(user, invitationURL);
        return { user, invitationSent: true };
      } catch {
        // Keep the created account visible so an administrator can retry delivery.
        return { user, invitationSent: false };
      }
    },
    async setBan(input: unknown) {
      const { id, banned } = setEmployeeBanSchema.parse(input);
      await requireEmployee(id);
      const request = { headers, body: { userId: id } };
      const { user } = banned ? await api.banUser(request) : await api.unbanUser(request);
      return user;
    },
    async update(input: unknown) {
      const data: UpdateEmployee = updateEmployeeSchema.parse(input);
      await requireEmployee(data.id);
      if (data.id === actorId && data.role !== "admin")
        throw new Error("You cannot remove your own administrator access.");
      const employee = await api.getUser({ headers, query: { id: data.id } });
      const email = data.email.toLowerCase();
      return api.adminUpdateUser({
        headers,
        body: {
          userId: data.id,
          data: {
            name: data.name,
            email,
            role: data.role,
            ...(email !== employee.email.toLowerCase() ? { emailVerified: false } : {}),
          },
        },
      });
    },
    async remove(input: unknown, decision?: unknown) {
      const { id } = employeeIdSchema.parse(input);
      await requireEmployee(id);
      if (id === actorId) throw new Error("You cannot delete your own account.");
      if (removeEmployee) await removeEmployee(id, decision);
      else await api.removeUser({ headers, body: { userId: id } });
      return { success: true };
    },
    /** callbackURL must be constructed by the host from its configured origin and validated locale. */
    async sendVerification(
      input: unknown,
      callbackURL: string,
      invitationURL: string,
    ): Promise<VerificationResult> {
      const { id } = employeeIdSchema.parse(input);
      await requireEmployee(id);
      const employee = await api.getUser({ headers, query: { id } });
      if (employee.banned) throw new Error("This account is disabled.");
      if (!employee.mustChangePassword && employee.emailVerified) return { status: "verified" };
      if (!verificationEnabled) return { status: "unavailable" };
      // Authorize the recipient above; forwarding admin cookies would target the admin instead.
      if (employee.mustChangePassword) {
        await sendInvitation(employee, invitationURL);
      } else {
        await api.sendVerificationEmail({ body: { email: employee.email, callbackURL } });
      }
      return { status: "sent" };
    },
  };
}

